INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'Buyer is Jutland Board & Packaging A/S, unrated, with a parent guarantee from Jutland Industri Holding A/S.', 'Buyer Jutland Board & Packaging A/S, unrated; parent guarantee from Jutland Industri Holding A/S', 'Section 4.2, key terms table, row 1', 'The Seller is not named anywhere in the document. No rating trigger is mentioned. The source is a due diligence summary as modelled, not the contract text.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '2_facility', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'Onshore wind farm (Havrebakke) with 8 turbines and 48.0 MW installed capacity, in Ringkøbing-Skjern, Denmark, bidding zone DK1.', '8 turbines, 48.0 MW, Ringkøbing-Skjern, DK1', 'Section 4.2, key terms table, row 2 (project header gives 48 MW onshore, Denmark, DK1)', 'Only one capacity figure is given, and it is not labelled AC or DC.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'The supply period is 10 years from the commercial operation date (COD). Target COD is 1 Oct 2027.', '10 years from COD', 'Section 4.2, key terms table, row 3', '', 'faithful');
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'Target COD is 1 Oct 2027 and the longstop date is 31 Mar 2028. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1.75m.', 'Target COD 1 Oct 2027; longstop 31 Mar 2028; LDs EUR 9,600/day, cap EUR 1.75m', 'Section 4.2, key terms table, row 4', '', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'The contract price is EUR 54.50/MWh. 30 % of the price is CPI-indexed from 2029.', 'EUR 54.50/MWh; 30 % CPI-indexed from 2029', 'Section 4.2, key terms table, row 5', 'The price is stated in the summary table only. The underlying contract clause is not cited, and the document does not say whether the price is fixed or escalating before 2029.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'Pay-as-produced, covering 100 % of output. Expected annual production (P50) is 158 GWh/yr, and a minimum of 118.5 GWh/yr is stated.', 'Pay-as-produced, 100 % of output; P50 158 GWh/yr; minimum 118.5 GWh/yr', 'Section 4.2, key terms table, row 6', 'The remedy if production falls below the 118.5 GWh/yr minimum is not stated. The document does not say whether the minimum is an availability or a production guarantee.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'The Seller sells electricity and all guarantees of origin (GoOs) to the Buyer.', 'Electricity + all GoOs to buyer', 'Section 4.2, key terms table, row 7', 'No GoO volume or price is stated. Capacity or other attributes are not mentioned.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'The Buyer may curtail up to 150 hours per year, compensated at the contract price. Curtailment ordered by the TSO is uncompensated.', 'Buyer right 150 h/yr, compensated at contract price; TSO curtailment uncompensated', 'Section 4.2, key terms table, row 8', 'Negative-price treatment is not addressed. The document does not say whether the compensated curtailed energy counts as deemed delivered.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'Physical settlement at the 60 kV Havrebakke substation. The Buyer is the balance responsible party (BRP) and bears imbalance costs.', 'Physical, 60 kV Havrebakke substation; buyer is BRP and bears imbalance', 'Section 4.2, key terms table, row 9', '', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'The Seller provides a bank guarantee of EUR 2,500,000 running to COD plus 12 months. The Buyer provides a letter of credit (LC) for 9 months of payments.', 'Seller bank guarantee EUR 2,500,000 to COD + 12 months; buyer LC 9 months of payments', 'Section 4.2, key terms table, row 10', 'The Buyer LC is sized as 9 months of payments, not as a fixed amount, and its duration is not stated.', 'faithful');
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'The termination amount is calculated as mark-to-market against the forward curve for the remaining term.', 'Mark-to-market vs forward curve for remaining term', 'Section 4.2, key terms table, row 11', 'The main events of default are not listed anywhere in the document. The calculation is described in one line only, with no formula or valuation party.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ic-key-terms', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T09:28:50+00:00', 1, 'Where the cost of a change in law exceeds EUR 250k per year, the parties renegotiate. If renegotiation fails, either party has a mutual termination right with no termination amount. A force majeure event lasting more than 180 days gives a termination right.', 'Renegotiation above EUR 250k/yr, then mutual termination right without termination amount; FM > 180 days termination right', 'Section 4.2, key terms table, row 12', 'The document does not say who bears change-in-law costs below the EUR 250k/yr threshold. It also does not say which party holds the force majeure termination right.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'Seller is Havrebakke Vind ApS. Buyer is Jutland Board & Packaging A/S, which is unrated. The Buyer''s payment obligations are guaranteed by its parent, Jutland Industri Holding A/S, through a parent company guarantee in Annex 4.', 'Seller: Havrebakke Vind ApS. Buyer: Jutland Board & Packaging A/S, unrated. Payment obligations guaranteed by Jutland Industri Holding A/S.', 'Part I; Part II 9.2; Annex 4 (as cited in the summary''s Key Terms table)', 'This document is a legal due diligence summary of the PPA, not the PPA itself. The summary states that the parent guarantee is the credit being relied on. It names no rating trigger.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '2_facility', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'Eight onshore wind turbines with 48.0 MW capacity at Havrebakke, Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'Eight onshore turbines, 48.0 MW, Havrebakke, Ringkøbing-Skjern Municipality, DK1.', 'Part I; Annex 1', 'The summary gives a single MW figure and does not split it into AC and DC.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'The Supply Period is ten years and starts on the Commercial Operation Date.', 'The Supply Period runs ten (10) years from the Commercial Operation Date.', 'Part I', '', 'faithful');
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'Target COD is 1 October 2027 and the Longstop Date is 31 March 2028. Delay damages are EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Delay damages EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Part II 3', 'Failure to reach COD by the Longstop Date is also listed as an Event of Default (see term 11).', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'The price is EUR 54.50 per MWh, taken from the Election Sheet. Thirty per cent of the price is adjusted annually by the Danish consumer price index, starting 1 January 2029.', 'EUR 54.50 per MWh per the Election Sheet.', 'Part II 7.1; Annex 2 (Election Sheet)', 'The price is stated in the Election Sheet rather than in the body. The indexation sentence is: ''Thirty per cent of the price is adjusted annually from 1 January 2029 by the Danish consumer price index.''', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'Pay-as-produced: the Buyer takes 100 % of Metered Output. Expected Annual Production is 158,000 MWh (P50). Minimum Annual Production is 118,500 MWh, and a shortfall payment is the remedy.', 'Minimum Annual Production 118,500 MWh with a shortfall payment.', 'Part I; Part II 4', 'The summary does not say how the shortfall payment is calculated or over what measurement period. Pay-as-produced is stated in Section 1: ''The agreement is a pay-as-produced physical PPA under Danish law''.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'The Seller sells electricity and all Guarantees of Origin, transferred at no additional cost. No capacity product is sold.', 'Electricity and all Guarantees of Origin, transferred at no additional cost.', 'Part II 8', '', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'The Buyer may instruct reductions for up to 150 hours per Contract Year. Curtailed energy is paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer. The Seller has no equivalent curtailment right.', 'Buyer may instruct reductions for up to 150 hours per Contract Year, paid as Deemed Delivered Electricity at the Contract Price.', 'Part II 5.4–5.5', 'The cap is in hours only; no MWh cap is stated. The summary does not address negative prices. The no-compensation point for operator-instructed reductions is from this sentence: ''Reductions instructed by the transmission system operator are not compensated by the Buyer.''', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'Physical delivery at the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Part I; Part II 4.2, 5.2', 'Settlement is physical, so no financial reference price applies.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'Seller: bank guarantee of EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Seller: bank guarantee EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Part II 9', 'The summary gives no euro amount for the Buyer''s letter of credit and no duration for the Buyer''s letter of credit or parent guarantee.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'Events of Default include non-payment within ten Business Days of notice, insolvency, and failure to reach COD by the Longstop Date. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Part II 12–13', 'The summary says the Reference Forward Price source is named in the agreement and is a published forward curve for DK1, but it does not name the source or the discount rate. The listed Events of Default are the ones the summary names and may not be exhaustive.', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-legal-dd-summary', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T09:29:33+00:00', 1, 'A cost impact above EUR 250,000 in a Contract Year triggers good-faith renegotiation. If there is no agreement within 90 days, the affected Party may terminate without a Termination Amount. Force majeure lasting more than 180 consecutive days gives either Party a termination right.', 'A cost impact above EUR 250,000 in a Contract Year triggers good-faith renegotiation; absent agreement within 90 days the affected Party may terminate without a Termination Amount.', 'Part II 11, 10 (as cited in the summary''s reference column)', 'The summary does not say which Party bears change-in-law costs below the EUR 250,000 threshold. The termination right after failed renegotiation is mutual, and the summary expects lenders to ask for it to be tightened. The force majeure sentence is: ''Force majeure beyond 180 consecutive days gives either Party a termination right.''', NULL);
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'Seller is Havrebakke Vind ApS; Buyer is Jutland Board & Packaging A/S, which holds no credit rating from a recognised rating agency. The Buyer''s payment obligations are guaranteed by Jutland Industri Holding A/S (the Guarantor) under the Parent Company Guarantee in Annex 4.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; section 9.2; section 9.5; Annex 4', 'The guarantee has no rating trigger. Section 9.5 requires a replacement guarantee, or a doubled Letter of Credit, if the Guarantor stops holding the entire share capital of the Buyer or the guarantee ceases to be in force. Annex 4 clause 5 caps the Guarantor''s liability at the Buyer''s aggregate liability under the Agreement and states no separate amount. The document is a draft dated 12 March 2026 and is not binding until signed.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '2_facility', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'Havrebakke Wind Farm: eight onshore wind turbine generators with a total installed capacity of 48.0 MW, located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Annex 1 gives each turbine as 6.0 MW, with a 125 m hub height and a 162 m rotor diameter. Only one MW figure is stated, with no separate AC and DC capacity.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'The Supply Period is ten (10) years, starting on the Commercial Operation Date.', 'Supply Period: ten (10) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; sections 1.1 and 3.3 (definition and conditions of the Commercial Operation Date)', 'The start is an event, not a fixed date. It occurs when all eight turbines have passed commissioning tests, the grid connection and meters are in place, the registrations are done, and the Seller has given written notice (section 3.3). The Seller must give at least 30 days'' notice of the expected date.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and the Longstop Date is 31 December 2027. If the target is missed, the Seller pays liquidated damages of EUR 9,600 per day of delay, capped at EUR 1,750,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period (target and longstop dates); sections 3.4, 3.5 and 3.6', 'Both dates extend day for day for Force Majeure or Buyer breach, up to 180 days in aggregate (3.5). The liquidated damages are the Buyer''s sole remedy for delay except termination (3.4). After the Longstop Date, as extended, the Buyer may terminate. The Seller then pays accrued liquidated damages and no Termination Amount is due (3.6). At EUR 9,600 per day the cap is reached after about 182 days (calculated here), which is later than the 91 days between the target and the Longstop Date unless the dates are extended.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'The Contract Price is EUR 58.00 per MWh, exclusive of VAT, applying to each MWh of Metered Output from the Commercial Operation Date. There is no indexation: the price is fixed for the Supply Period.', 'Contract Price: EUR 58.00 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output from the Commercial Operation Date.', 'Annex 2 (Election Sheet); referred to from Part I, Price and section 7.1', 'The price is stated only in Annex 2, which prevails over other parts. Annex 2 states: "Indexation: none. The Contract Price is fixed for the Supply Period and shall not be indexed." The only route to a price change is by agreement following a Change in Law (section 11.2).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected Annual Production is 158,000 MWh (P50). Minimum Annual Production is 118,500 MWh (75% of P50). If output in a Contract Year falls below the minimum, the Seller pays the shortfall in MWh times the amount, if positive, by which the average DK1 day-ahead price exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the Metered Output is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; sections 4.1, 4.3, 4.5 and 4.6; Annex 1; Annex 2', 'The Seller guarantees no quantity in any hour, day or month (4.3). Minimum Annual Production is cut pro rata in the first and last Contract Year and is reduced for Force Majeure, Transmission System Operator output reductions and Buyer breach (4.5, 4.6). The shortfall payment is a make-whole against market price, so it is zero when the day-ahead price is at or below EUR 58.00.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'The product is electricity delivered at the Delivery Point plus all Guarantees of Origin issued for the Metered Output, transferred to the Buyer at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'Product: electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of the Metered Output.', 'Part I, Product and Certificates; section 8', 'Guarantees of Origin for each month are transferred to the Buyer''s registry account within 15 Business Days of issue (8.1). The Seller need not procure replacement Guarantees of Origin for any production shortfall (8.2). Certificates under any replacement scheme also pass to the Buyer at no additional cost (8.3).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'Reductions of output instructed by the transmission system operator give rise to no payment by the Buyer, so curtailed energy is not paid as deemed delivered. Any compensation paid by the Transmission System Operator for the reduction belongs to the Seller.', 'Reductions of output instructed by the transmission system operator shall not give rise to any payment by the Buyer.', 'Section 5.4; also sections 4.6 and 5.5', 'The document gives the Buyer no right to curtail. It sets no cap in hours or MWh, and it does not mention negative prices or how they are treated. Deemed quantities (5.5) are used only to reduce the Minimum Annual Production for the shortfall test (4.6), not to create a payment.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'Settlement is physical. The Delivery Point is the metering point on the 60 kV side of the Havrebakke substation, where title and risk pass to the Buyer. The Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement; Part I, Delivery Point and Balancing; sections 4.2 and 5.2; Annex 2', 'No reference price applies because settlement is physical, not financial. The balance responsible party must be registered no later than 30 days before the expected Commercial Operation Date (5.2). The Seller provides day-ahead and intraday production forecasts without warranty (5.1).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'Seller: bank guarantee of EUR 2,000,000, delivered within 10 Business Days after Financial Close and in force until 12 months after the Commercial Operation Date. Buyer: Parent Company Guarantee plus a letter of credit for six months of expected payments (six twelfths of Expected Annual Production times the Contract Price), delivered at least 30 days before expected Commercial Operation Date and in force until 60 days after the end of the Supply Period.', 'The Buyer shall deliver a letter of credit in an amount equal to six (6) months of expected payments under this Agreement, calculated as six twelfths of the Expected Annual Production multiplied by the Contract Price in force at the time of calculation, no later than thirty (30) days before the expected Commercial Operation Date, to remain in force until sixty (60) days after the end of the Supply Period.', 'Part I, Credit Support; sections 9.1 to 9.5; Annex 3; Annex 4', 'The letter of credit amount is not stated as a figure. With the document''s 158,000 MWh and EUR 58.00 it works out to EUR 4,582,000 (calculated here, not stated in the document). It is recalculated each 1 January. Both instruments must come from a bank rated at least A-. If an issuer loses its rating, or an instrument is not extended in time, the other Party may draw the full amount as cash security (9.4). The Seller''s guarantee covers amounts unpaid under sections 3.4, 3.6 or 4.5.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'Events of Default include non-payment (10 Business Days after notice), failure to deliver, restore or replace credit support (10 Business Days after notice), insolvency, an uncured material breach (30 days), assignment in breach, and the Seller missing the Longstop Date or selling to a third party. For the Buyer they also include Guarantor insolvency or an invalid guarantee that is not replaced. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period on Expected Annual Production, discounted at the Danish central bank reference rate plus 2 percentage points, determined by the Non-Defaulting Party.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Sections 12.1, 12.2, 13.2 to 13.6; definition of Reference Forward Price in section 1.1; Annex 2 (production profile factor)', 'The Reference Forward Price is the average of DK1 baseload forwards quoted by at least three market participants chosen by the Non-Defaulting Party, adjusted by the factor 0.88 in Annex 2. The amount is payable only if it is a loss for the Non-Defaulting Party; if it is a gain, nothing is payable (13.4). It is the exclusive remedy for loss of bargain (13.5). No Termination Amount applies on termination under sections 2.3, 3.6, 10.4 or 11.3 (13.6).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v1-draft', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T09:30:40+00:00', 1, 'If a Change in Law raises a Party''s cost of performing by more than EUR 250,000 in any Contract Year, the Parties negotiate in good faith an adjustment, which may include the Contract Price. If none is agreed within 90 days of notice, the affected Party may terminate on 60 days'' notice with no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice, also with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Sections 11.1 to 11.3; section 17.2 and 17.3 (taxes and regulatory costs); sections 10.1 to 10.4', 'Below the threshold no adjustment right exists, so the cost stays where it falls. Section 17.2 allocates taxes: the Seller bears those on generation and injection into the grid, and the Buyer bears those on offtake, transport, consumption or resale. New taxes after signing follow that split and are subject to section 11 if the threshold is met (17.3). Change in Law excludes general corporate income tax changes and changes published in final form before signing. Force Majeure excludes lack of funds, market price changes and insufficient wind (10.1). The force majeure termination period is 180 consecutive days (10.4).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'Seller is Havrebakke Vind ApS and Buyer is Jutland Board & Packaging A/S, both Danish companies. The Buyer holds no credit rating, and its payment obligations are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee in Annex 4.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; Part II s. 9.2 and s. 9.5; Annex 4', 'The Buyer is unrated (''The Buyer does not hold a credit rating from a recognised rating agency''), so its credit rests on the guarantee plus the letter of credit in s. 9.2. The guarantee has no rating trigger. The only trigger is s. 9.5: if the Guarantor stops holding the Buyer''s entire share capital, or the guarantee ceases to be in force, the Buyer must within 20 Business Days deliver a replacement guarantee acceptable to the Seller or double the letter of credit. The guarantee covers all Buyer payment obligations, including the Termination Amount (Annex 4, para 2), but the Guarantor''s liability is capped at the Buyer''s own aggregate liability (Annex 4, para 5). Delivery of the guarantee is a condition precedent (s. 2.1(d)).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'Onshore wind farm of eight turbines with 48.0 MW total installed capacity, at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Only one capacity figure (48.0 MW) is given; the document does not distinguish AC from DC capacity. Annex 1 states each turbine is rated 6.0 MW, with a 60 kV grid connection from the Havrebakke substation.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'The Supply Period is twelve years from the Commercial Operation Date.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; Part II s. 1.1 (Commercial Operation Date) and s. 3.3', 'The Commercial Operation Date is the date the Seller notifies the Buyer that the s. 3.3 conditions are met (all eight turbines commissioned, grid connection and meters verified, registrations completed). The period therefore starts on the actual date, not the target date. If commercial operation is on the 1 October 2027 target, the period would run to about 30 September 2039 (our calculation, not stated in the document).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and the Longstop Date is 31 March 2028. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1,750,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period; Part II s. 3.4, s. 3.5, s. 3.6; s. 1.1 (Longstop Date)', 'Both dates are extended day for day for Force Majeure or Buyer breach, up to 180 days in aggregate (s. 3.5). The liquidated damages are the Buyer''s sole remedy for delay, except the right to terminate after the Longstop Date under s. 3.6, which carries no Termination Amount. Overlap to check: s. 12.1(f) also makes failure to reach commercial operation by the Longstop Date a Seller Event of Default, which would carry a Termination Amount under s. 13.3, and the document does not say which route prevails.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'The Contract Price is EUR 54.50 per MWh excluding VAT, stated in Annex 2 (Election Sheet). Thirty per cent of the price is adjusted each 1 January from 2029 by the change in the Danish consumer price index over the preceding calendar year, and the remaining seventy per cent is fixed for the Supply Period.', 'Contract Price: EUR 54.50 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output and of Deemed Delivered Electricity from the Commercial Operation Date.', 'Annex 2 (Election Sheet), Contract Price and Indexation; Part I, Price; Part II s. 7.1', 'The price is not stated in the body, which refers to Annex 2 and says any adjustment is governed exclusively by Annex 2. Indexation wording in Annex 2: ''Thirty per cent (30%) of the Contract Price shall be adjusted on 1 January of each Contract Year from 2029 by the percentage change in the Danish consumer price index over the preceding calendar year.'' There is no adjustment on 1 January 2028, and the document states no cap or floor on the index.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected annual production is 158,000 MWh (P50) and the Minimum Annual Production is 118,500 MWh. If the Metered Output plus Deemed Delivered Electricity falls below the minimum, the Seller pays a shortfall payment capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the sum of the Metered Output and the Deemed Delivered Electricity is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; Part II s. 4.1, s. 4.3, s. 4.5, s. 4.6; Annex 1; Annex 2', 'The shortfall payment is positive only when the average DK1 day-ahead price exceeds the Contract Price. For the first and last Contract Year the minimum is reduced pro rata (s. 4.5), and it is further reduced for Force Majeure, Transmission System Operator output reductions and Buyer breach (s. 4.6). Annex 1 states the minimum equals 75 per cent of the Expected Annual Production. The Seller gives no guarantee for any particular quantity in any hour, day or month (s. 4.3), and the availability figure of 97 per cent in Annex 1 is an assumption behind the P50, not a guarantee.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'The Buyer purchases the electricity and all Guarantees of Origin issued for the Metered Output, with the certificates transferred at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'Product: electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of the Metered Output.', 'Part I, Product and Certificates; Part II s. 8.1, s. 8.2, s. 8.3', 'Certificates are transferred monthly within 15 Business Days after issue (s. 8.1). No Guarantees of Origin are issued for Deemed Delivered Electricity, and the Seller need not procure replacement certificates for any shortfall against the Expected Annual Production (s. 8.2). If the Guarantee of Origin scheme is replaced, certificates under the successor scheme pass to the Buyer at no additional cost (s. 8.3).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'The Buyer may instruct output reductions for up to 150 hours per Contract Year on at least two hours'' notice, and the energy not generated is paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the Transmission System Operator give rise to no payment by the Buyer, and any compensation from the Transmission System Operator belongs to the Seller.', 'The Buyer may instruct the Seller to reduce the output of the Facility for up to one hundred and fifty (150) hours per Contract Year, and the electricity that would otherwise have been generated during such hours shall be treated as Deemed Delivered Electricity and paid at the Contract Price.', 'Part II s. 5.4, s. 5.5, s. 5.6, s. 4.6; Annex 2', 'The cap is stated in hours only; no MWh cap is given, and the Seller may refuse instructions beyond the limit. Deemed quantities are calculated from the mast wind data, the power curve and turbine availability (s. 5.6). Deemed Delivered Electricity counts towards the Minimum Annual Production (s. 4.5), and Transmission System Operator reductions reduce that minimum (s. 4.6). The document contains no provision on negative prices.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'Settlement is physical, with delivery at the metering point on the 60 kV side of the Havrebakke substation, where title and risk pass to the Buyer. The Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; Part II s. 4.2, s. 5.2; Annex 2', 'No reference price is stated because settlement is physical, not financial. The balance responsible party must be registered at least 30 days before the expected Commercial Operation Date (s. 5.2), and the Seller supplies day-ahead and intraday production forecasts without warranty (s. 5.1).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'The Seller provides a EUR 2,000,000 bank guarantee within 10 Business Days after Financial Close, in force until 12 months after the Commercial Operation Date. The Buyer provides the Parent Company Guarantee and a letter of credit equal to nine months of expected payments, delivered at least 30 days before the expected Commercial Operation Date and in force until 60 days after the end of the Supply Period.', 'The Seller shall deliver a bank guarantee in the amount of EUR 2,000,000 within ten (10) Business Days after Financial Close, to remain in force until twelve (12) months after the Commercial Operation Date.', 'Part I, Credit Support; Part II s. 9.1 to s. 9.5; Annex 2; Annex 3; Annex 4', 'Buyer letter of credit (s. 9.2): nine twelfths of the Expected Annual Production times the Contract Price in force, recalculated each 1 January. At the initial price that is about EUR 6.46 million (118,500 MWh x EUR 54.50; our calculation, not stated in the document). Both issuing banks must be rated at least A- (s. 9.1, s. 9.2). The Seller guarantee can be drawn only for unpaid amounts under ss. 3.4, 3.6 or 4.5 and expires 12 months after commercial operation, so it does not cover later Seller payment obligations. The Seller may draw the Buyer letter of credit after 10 Business Days'' notice of non-payment, and the Buyer must restore it within 10 Business Days (s. 9.3). A bank downgrade or missing extension requires replacement within 20 Business Days, failing which the other party may draw the full amount as cash security (s. 9.4).', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'Events of Default include non-payment (10 Business Days after notice), failure to deliver, restore or replace credit support, insolvency, uncured material breach (30 days) and prohibited assignment, plus Seller failure to reach commercial operation by the Longstop Date or selling to a third party, and Guarantor insolvency or lapse of the guarantee for the Buyer. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price on the Expected Annual Production for the rest of the Supply Period, discounted at the Danish central bank reference rate plus 2 percentage points and determined by the Non-Defaulting Party.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Part II s. 12.1, s. 13.2 to s. 13.6; s. 1.1 (Reference Forward Price); Annex 2 (production profile factor)', 'The calculation is fully defined in the attached documents: the Reference Forward Price (s. 1.1) is the average of at least three market quotes for DK1 baseload, adjusted by the factor 0.88 in Annex 2. Payment runs one way: if the amount is a loss for the Non-Defaulting Party the Defaulting Party pays it within 20 Business Days, and if it is a gain nothing is payable by either party (s. 13.4). Terminations under ss. 2.3, 3.6, 10.4 and 11.3 carry no Termination Amount (s. 13.6). Before commercial operation the remainder of the Supply Period is measured from the Target Commercial Operation Date (s. 13.3). Overlap between s. 3.6 and s. 12.1(f) on Longstop Date termination is flagged under term 4.', 'correct');
INSERT INTO extractions VALUES (1, 'havrebakke-ppa-v2-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T09:32:20+00:00', 1, 'If a Change in Law raises a party''s cost of performing by more than EUR 250,000 in any Contract Year, the parties negotiate in good faith an adjustment that may include the Contract Price. If none is agreed within 90 days after notice, the affected party may terminate on 60 days'' notice with no Termination Amount, and Force Majeure lasting more than 180 consecutive days gives either party a termination right on 30 days'' notice, also with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Part II s. 11.1 to s. 11.3; s. 17.2 and s. 17.3; s. 10.1 to s. 10.4', 'The document does not assign Change in Law cost to either party outright: below the threshold each party carries its own cost, and above it the remedy is renegotiation and then termination. Section 17.2 allocates taxes and charges on generation and injection to the Seller and those on offtake, transport, consumption or resale to the Buyer, and s. 17.3 says new levies are allocated that way and are subject to s. 11 where the threshold is met. Change in Law excludes corporate income tax of general application and changes published in final form before the Signing Date (s. 11.1). Force Majeure excludes lack of funds, market price changes and insufficient wind (s. 10.1).', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'Seller is Lichtung Offshore Wind GmbH & Co. KG (Emden, single-purpose project company). Buyer is Rheintal Spezialchemie AG (Worms), rated BBB+ on the Signing Date (3 November 2025). The Buyer has no guarantor, but must post a EUR 20,000,000 letter of credit if its rating falls below BBB- or is withdrawn.', 'On the Signing Date the Buyer holds a long-term credit rating of BBB+ from a recognised rating agency.', 'Part I, Parties; Part II, section 9.3', 'No parent guarantee or other third-party support for the Buyer was found. The only Buyer-side protection is the rating-triggered letter of credit (20 Business Days to post after the trigger; returned after 6 consecutive months back at BBB- or above). The guarantor named in Part I is the Seller''s (Lichtung Energie Holding GmbH), not the Buyer''s. The rating agency is not named.', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'Offshore wind farm of 300 MW installed capacity (20 turbines of 15 MW each on monopile foundations), about 60 km north-west of Borkum in the German North Sea, connected through the TSO''s offshore grid connection system. Grid connection capacity allocated is 300 MW.', 'The Facility is an offshore wind farm with an installed capacity of 300 MW located in the German North Sea approximately 60 km north-west of Borkum, consisting of twenty (20) wind turbine generators of 15 MW each on monopile foundations, one offshore substation and the inter-array cables, connected to the onshore transmission grid through the offshore grid connection system of the transmission system operator.', 'Part I, Facility; Part II, section 1.1 (Installed Capacity); Annex 1, items 1-4', 'Only one capacity figure (300 MW) is given; no separate AC and DC figures. The Facility''s bidding zone is not stated in so many words. DE-LU is the zone of the Reference Price and of the Buyer''s production sites (Part I, Parties; section 1.1), and section 11.4(b) refers to the area in which the Facility and the Buyer''s sites are located. Annex 1 gives the site as the German Exclusive Economic Zone, so no municipality applies.', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'Fifteen years from the Start Date of 1 January 2029, ending 31 December 2043. The period is fixed to the calendar and does not move if commissioning is late.', 'Supply Period: fifteen (15) years commencing on the Start Date of 1 January 2029.', 'Part I, Supply Period; Part II, section 1.1 (Start Date, Contract Year)', 'The start is a fixed date, not the commissioning date. Part I says the period ''is not extended by any delay in commissioning''. Settlement starts at the later of the Start Date and the day after the Commissioning Date (section 4.1).', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'Target commissioning is on or before the Start Date, 1 January 2029; the Longstop Commissioning Date is 1 July 2029. Delay compensation is EUR 40,000 per day from the Start Date, capped at EUR 6,000,000 in aggregate.', 'If the Facility has not been commissioned by the Start Date, the Seller shall pay the Buyer delay compensation of EUR 40,000 for each day from the Start Date until the Facility is commissioned, up to an aggregate cap of EUR 6,000,000 (Delay Compensation).', 'Part II, sections 3.1(d), 3.2, 3.3, 3.4, 4.5 and 1.1 (Longstop Commissioning Date)', 'The Facility counts as commissioned at 240 MW (80% of 300 MW), not at full capacity (section 3.2). The cap equals 150 days of delay, so it is reached before the longstop, which falls about 181 days after the Start Date. Delay compensation is the Buyer''s sole financial remedy for late commissioning. Its accrual is suspended during Force Majeure, but the longstop is not extended. After the longstop the Buyer may terminate with no Termination Amount payable (section 3.4). For the first Contract Year the Contract Quantity is reduced for hours before settlement begins (section 4.5).', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'Strike Price of EUR 72.00 per MWh in the first Contract Year (2029), increased by 2% each 1 January from the second Contract Year (2030), compounding and rounded to two decimals (EUR 73.44 in 2030, EUR 74.91 in 2031). The Strike Price includes the consideration for the Guarantees of Origin.', 'Strike Price: EUR 72.00 per MWh, increased by two per cent (2%) on 1 January of each Contract Year from the second Contract Year onwards.', 'Part I, Price; Part II, section 7.1', 'The price is stated in the body (Part I and section 7.1), not in an annex or election sheet. It is a strike price settled against the hourly DE-LU day-ahead Reference Price, not a flat price per MWh delivered (section 4.2). The escalation is a fixed 2% on the whole Strike Price and is not linked to an inflation index.', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'Fixed baseload volume, not pay-as-produced: 1,000,000 MWh per Contract Year in equal hourly quantities, settled regardless of actual output. The Seller''s P50 estimate is about 1,280,000 MWh a year, so the Contract Quantity is about 78% of P50. No availability or production guarantee is given, so there is no remedy for under-production.', 'Contract Quantity: 1,000,000 MWh per Contract Year, delivered as a baseload profile in equal hourly quantities.', 'Part I, Contract Quantity; Part II, sections 4.1, 5.3 and 5.5; Annex 1, item 5', 'Section 5.5 reads: ''The Seller gives no guarantee of availability or production.'' Outages do not reduce the Contract Quantity (section 5.3). The Contract Quantity is reduced only for the first-year delay (section 4.5) and in proportion to capacity made unavailable by Force Majeure (section 10.4). ''Delivered'' in Part I is a loose word: settlement is financial. The P50 estimate is expressly not a warranty. The only volume-related remedy is the Guarantee of Origin shortfall mechanism (sections 8.2 and 8.3).', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'The Seller sells a financial settlement of the Contract Quantity against the Reference Price, plus Guarantees of Origin equal to the Contract Quantity each Contract Year. No electricity is sold or delivered. The Guarantee of Origin consideration is included in the Strike Price, with no separate cost.', 'Product: (a) the financial settlement of the Contract Quantity against the Reference Price under section 4, and (b) the transfer to the Buyer of Guarantees of Origin in a quantity equal to the Contract Quantity under section 8.', 'Part I, Product and Certificates; Part II, sections 4.6, 7.1 and 8', 'The Guarantees of Origin carry the technology attribute ''offshore wind''. If the Facility generates less than the Contract Quantity, the Seller buys the shortfall from other German offshore wind facilities at its own cost (section 8.2). The Seller bears issuing fees and the Buyer bears cancellation fees (section 8.4). Negative Price Hours do not reduce the quantity due (section 4.4). The Buyer acquires no title to electricity (section 4.6). No capacity product or other attribute is sold.', 'wrong_value');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'The only curtailment dealt with is TSO-instructed curtailment. It does not reduce the Seller''s obligations on the Contract Quantity unless it is Force Majeure, and TSO compensation belongs to the Seller. Because the Contract Quantity is settled whatever the Facility generates, curtailed energy is in effect settled in full. No cap in hours or MWh is stated. Negative Price Hours carry no settlement payment, but the Guarantee of Origin quantity is unchanged.', 'The Seller''s obligations in respect of the Contract Quantity shall not be reduced by any curtailment of the Facility''s output instructed by the transmission system operator, save where such curtailment constitutes Force Majeure.', 'Part II, sections 5.4, 4.1, 4.4, 10.1 and 10.2', 'Curtailment for congestion management, redispatch, system security or market-related reasons is expressly not Force Majeure (sections 5.4 and 10.2). TSO curtailment that results from an event which itself is Force Majeure is Force Majeure (section 10.1). The document gives the Buyer no right to curtail. It also does not say whether the Seller may curtail the Facility itself, for example in negative-price hours. The phrase ''deemed delivered'' is not used; the effect comes from the financial settlement structure. Negative prices are handled in section 4.4: the hour is excluded from settlement for both Parties.', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'Settlement is financial and there is no Delivery Point. The Seller sells the Facility''s physical output in the market for its own account, is the balance-responsible party and bears all imbalance costs. The Reference Price is the hourly day-ahead price for the DE-LU bidding zone, and the Buyer balances its own consumption.', 'The Seller sells the physical output of the Facility in the market for its own account and remains responsible for the balancing of the Facility (section 5.2).', 'Part I, Settlement and Delivery Point and Balancing; Part II, sections 1.1 (Reference Price), 4 and 5.2', 'Part I states ''Delivery Point: not applicable'' and that no physical delivery takes place. Where the day-ahead market publishes prices for periods shorter than one hour, the Reference Price is their arithmetic average over the hour. If the Reference Price Source changes, a Replacement Reference Price applies under section 11.', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'Seller: parent company guarantee from Lichtung Energie Holding GmbH for EUR 25,000,000, due within 10 Business Days after signing and kept in force until 12 months after the end of the Supply Period (31 December 2044 on the stated dates). It must be replaced by a EUR 25,000,000 letter of credit if the guarantor becomes insolvent, ceases to be an affiliate or disputes the guarantee. Buyer: nothing at signing; a EUR 20,000,000 letter of credit within 20 Business Days if its rating drops below BBB- or is withdrawn.', 'Seller: parent company guarantee from Lichtung Energie Holding GmbH in the amount of EUR 25,000,000 in the form of Annex 4 (section 9.1).', 'Part I, Credit Support; Part II, sections 9.1-9.4, 2.1(c); Annexes 3 and 4', 'Delivery of the parent company guarantee is a condition precedent to sections 4, 7 and 8 taking effect (section 2.1(c)). The Annex 4 guarantee caps the guarantor''s aggregate liability at EUR 25,000,000 and covers any Termination Amount payable by the Seller. Letters of credit must come from a bank rated A- or better. The Buyer Letter of Credit is returned after 6 consecutive months back at BBB- or above. Support may be drawn only for amounts due and unpaid, after 5 Business Days'' notice, and must be restored within 10 Business Days after a drawing.', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 0, NULL, NULL, 'Part II, sections 12 and 13; Annex 5', 'The Termination Amount is only referenced to Annex 5, which is not attached. Section 13.3 says: ''The Termination Amount shall be calculated in accordance with Annex 5 (Termination Amount Methodology).'' The Annex list ends with ''Annex 5 — Termination Amount Methodology [to be agreed prior to Financial Close]''. Section 1.2 makes Annex 5 govern the calculation, and section 2.1(d) makes agreeing and attaching it a condition precedent to sections 4, 7 and 8 taking effect. Events of Default in section 12.1 are stated: non-payment (10 Business Days after notice); failure to deliver, maintain or restore credit support (10 Business Days); insolvency of the Party or its credit support provider; failure to perform another material obligation (30 days); repudiation; Seller abandonment for 90 consecutive days; Seller failing to transfer the full Guarantees of Origin quantity within 120 days after the Contract Year; and breach of the assignment or change-of-control rules. Termination mechanics are in section 13.1: the Non-Defaulting Party gives notice, with the Early Termination Date 5 to 20 Business Days later. No Termination Amount is payable on termination under sections 2.2, 3.4, 10.5 or 11.2 (section 13.5).', 'correct');
INSERT INTO extractions VALUES (1, 'lichtung-offshore-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T09:33:43+00:00', 1, 'A general Change in Law is borne by the Party on whom the cost or benefit falls, with no adjustment of the Strike Price or Contract Quantity, and no threshold is stated. If a Change in Law removes the Product or a material part of it, either Party may terminate with no Termination Amount after 90 days of good-faith renegotiation. Force Majeure lasting more than 180 consecutive days lets either Party terminate with no Termination Amount.', 'Any other Change in Law, including one that changes the cost of Guarantees of Origin, grid charges or levies, is borne by the Party on whom the cost or benefit falls.', 'Part II, sections 11.2, 11.3, 10.4, 10.5 and 17.3', 'The Change in Law definition excludes changes in taxes on income. Section 17.3 puts levies, caps or skimming mechanisms on generator revenues, or on amounts payable under financial contracts, on the Party they are imposed on, with no price adjustment. For Force Majeure that affects the Seller, the Hourly Quantity and the Guarantee of Origin obligation fall in proportion to the capacity lost (section 10.4). Force Majeure excludes low wind, price changes, lack of funds and market-related curtailment (section 10.2). A Change in Reference Price Source gives no termination or price-adjustment right (section 11.7).', 'wrong_value');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Seller: Olivos Solar Proyecto Dos S.L. (Spain), a special purpose company owning the Facility. Buyer: Meseta Energía Comercializadora S.A. (Spain), a licensed electricity trader. The Buyer has no guarantor: no parent company guarantee is provided, and its obligations are supported solely by the letter of credit in section 9.2.', 'The Buyer is a licensed electricity trader and no guarantee of the Buyer''s obligations is provided by any affiliate of the Buyer.', 'Cover page; Part I (Parties); Part II sections 9.2 and 9.6; Annex 4', 'Section 9.6 says the Buyer contracts as a stand-alone trader and its shareholders have given no undertaking. The document states no corporate credit rating or rating trigger for the Buyer. Ratings are required only of the banks issuing the credit support (A- minimum, sections 9.1, 9.2 and 9.5).', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Ground-mounted solar PV plant (bifacial crystalline silicon modules on single-axis trackers) with 90 MWp DC installed capacity and 75 MW AC grid export capacity. Site: Valdeolivos, Province of Badajoz, Extremadura, Spain. Pricing and settlement refer to the Spanish bidding zone.', 'Facility: a ground-mounted solar photovoltaic plant with an installed capacity of 90 MWp (direct current) and a grid export capacity of 75 MW (alternating current) located at Valdeolivos in the Province of Badajoz, Spain, as further described in Annex 1.', 'Part I (Facility); Annex 1, A1.1 to A1.4', 'The bidding zone is not named in the facility description itself. It appears as ''the Spanish bidding zone'' in sections 7.3, 7.4 and 13.3. The 75 MW AC limit is set at the inverters in line with the access and connection permits (A1.3).', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Twelve years, starting on the Commercial Operation Date. That date occurs when the Seller gives notice with certificates that the section 3.4 conditions are met: definitive authorisation, TSO confirmation of 75 MW export, metering verified, and at least 60 MW AC exported for 72 continuous hours.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I (Supply Period); Part II sections 1.1 and 3.4', 'The start is tied to an event, not a calendar date. COD can be declared at 60 MW of the 75 MW AC export capacity. The Seller must give at least 30 days'' notice of the expected COD.', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Target COD is 30 June 2027 and the Longstop Date is 31 December 2027. For each day of delay after the target date the Seller pays EUR 6,000, capped at EUR 1,500,000 in aggregate. These damages are the Buyer''s sole remedy for delay until the Longstop Date. Both dates extend day for day for Force Majeure or a TSO delay, up to 180 days. If COD has not occurred by the Longstop Date as extended, the Buyer may terminate and no Termination Amount is payable.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 30 June 2027, the Seller shall pay the Buyer liquidated damages of EUR 6,000 for each day of delay, up to an aggregate cap of EUR 1,500,000.', 'Part I (Target Commercial Operation Date); Part II sections 1.1 and 3.5 to 3.7', 'The extension requires the Seller to notify the Buyer within 5 Business Days of the event (3.6). The indicative construction milestones in 3.2 are reporting items only, and slippage against them is not a breach.', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'EUR 38.75 per MWh, fixed for the Supply Period with no indexation or escalation. The price includes Guarantees of Origin and excludes VAT. No payment is due for hours with a negative day-ahead price.', 'Contract Price: EUR 38.75 per MWh, fixed for the Supply Period without indexation.', 'Part I (Price); Part II sections 7.1 and 7.4', 'There is no indexation, so there is no start date or share. The only stated adjustments are the negative price rule (7.4) and the new-tax mechanism (17.3).', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output, with no minimum or maximum annual quantity. Expected Annual Production is 165,000 MWh (P50), an estimate and not a delivery obligation. The Seller guarantees 97% Availability in each Contract Year. If Availability is lower, the Seller pays damages equal to the shortfall in percentage points x 1% of Expected Annual Production x Contract Price x 50%. These damages are capped at 5% of the amount payable by the Buyer for that year and are the sole remedy.', 'The Buyer purchases one hundred per cent (100%) of the Metered Output during the Supply Period.', 'Part I (Contract Quantity and volume structure); Part II sections 4.1, 4.4 and 5.6; Annex 1, A1.5 and A1.6', 'There is no energy-based production guarantee: section 4.4 says the Seller does not commit to any minimum quantity. Availability is measured over Daylight Hours against 95% of irradiance-adjusted capacity (A1.6), and planned maintenance counts as unavailability (5.4). The P50 is not adjusted for module degradation (A1.5).', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'The Buyer purchases the electricity delivered at the Delivery Point together with all Guarantees of Origin issued for it. The GOs are transferred to the Buyer''s register account within 30 days after issue at no additional cost, because the Contract Price already includes them. No capacity product, ancillary service or other attribute is sold.', 'Electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of that electricity.', 'Part I (Product); Part II sections 7.1, 8.1 and 8.2', 'GO volume is not quantified; it follows the Metered Output. GOs also arise in negative-price hours (7.4). A successor certificate must be transferred without any change to the Contract Price (8.2).', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 0, NULL, NULL, NULL, 'The document has no curtailment clause. It does not say who may curtail the Facility, set any cap in hours or MWh, provide for deemed-delivery payment, or address grid-operator curtailment. Related provisions that do exist: (1) in any hour with a negative day-ahead price the Contract Price does not apply and nothing is paid, but the output is still delivered and gives rise to GOs (7.4); (2) the Buyer must accept all generation and may not refuse delivery because the market price is below the Contract Price (4.5); (3) no payment is due for electricity not delivered because of Force Majeure, which includes failure of the transmission grid beyond the Delivery Point (10.1, 10.4). The 75 MW AC limit at the inverters (Annex 1, A1.3) is a design and permit limit, not a curtailment right.', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Physical settlement at the Delivery Point, the 220 kV connection point at the Valdeolivos substation. The Buyer is the market representative and balance responsible party from COD and bears all imbalance costs. The Seller is liable only where an imbalance results from its failure to notify an outage under 5.4 or 5.5. No financial reference price applies; the day-ahead price for the Spanish bidding zone is used only for the negative-price rule in 7.4.', 'The Buyer shall act as the market representative of the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I (Settlement; Delivery Point and Balancing); Part II sections 4.3, 5.2, 5.3 and 7.4; Annex 1, A1.4', 'Imbalance cost is allocated to the Buyer ''from the Commercial Operation Date''. Section 3.3 has the Buyer act as market representative for test electricity under 5.2, but the text does not say who bears imbalance cost on test electricity delivered before COD.', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Seller: performance bond of EUR 1,200,000, delivered within 10 Business Days after the Signing Date and held until COD, from a bank rated at least A-. Buyer: standby letter of credit equal to three months of expected payments, EUR 1,598,437.50 on the Signing Date (one quarter of 165,000 MWh x EUR 38.75). It is delivered at least 10 Business Days before the expected COD and maintained until 60 days after the end of the Supply Period. The Buyer must restore it within 10 Business Days after a drawing. No parent company guarantee is given by either Party.', 'Seller: performance bond of EUR 1,200,000 from the Signing Date until the Commercial Operation Date (Annex 2).', 'Part I (Credit Support); Part II sections 9.1 to 9.6; Annexes 2 and 3', 'The Buyer provides no credit support before COD, and the Seller provides none after COD. The EUR 1,200,000 bond is lower than the EUR 1,500,000 delay damages cap (3.5), and it also covers section 13 amounts before COD. Part I says the Buyer''s letter of credit runs until the end of the Supply Period, while section 9.2 says until 60 days after it; Part I prevails on conflict. The letter of credit may have a one-year term with replacement 30 days before expiry, failing which the Seller may draw the full amount (9.3). The amount in the Annex 3 form is a blank placeholder.', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Events of Default for either Party: non-payment not cured within 10 Business Days after notice; failure to deliver, maintain or restore credit support within 10 Business Days after notice; Insolvency Event; other material breach not remedied within 30 days (90 days where a cure is not possible within 30); and a materially incorrect representation. Seller only: sale to a third party in breach of 4.1, or Permits revoked and not reinstated within 90 days. Buyer only: trader licence or market registration revoked or suspended and not reinstated within 30 days, or revocation of the powers of representation. The Termination Amount is the replacement value for the rest of the Supply Period, set by an independent expert: the present value, at the Interest Rate (ECB main refinancing rate + 4 points), of the difference between the Contract Price and the forward price for the Spanish bidding zone, based on at least two market quotations and applied to the Expected Annual Production. The Defaulting Party pays the Termination Amount and the expert''s costs.', 'The expert shall determine, under section 20.3, the present value at the Interest Rate of the difference between the Contract Price and the forward price for the Spanish bidding zone at the early termination date, evidenced by quotations from at least two (2) market participants, applied to the Expected Annual Production over the remainder of the Supply Period.', 'Part II sections 12.1, 13.1 to 13.4, 1.1 (Interest Rate) and 20.3', 'The calculation method is in the body and does not depend on an unattached document. A negative Termination Amount means nothing is payable by either Party (13.2). No Termination Amount is payable on termination under 2.3, 3.7 or 10.5 (13.5). Where the Seller is the Defaulting Party, the Lender step-in and suspension right in 16.4 applies (up to 120 days). The text gives no sign convention for the price difference beyond the negative-amount rule.', 'correct');
INSERT INTO extractions VALUES (1, 'olivos-solar-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T09:35:26+00:00', 1, 'Change in law: the Seller bears any new tax, levy or charge on generation or sale from the Facility enacted after the Signing Date, unless it exceeds 3% of the Seller''s revenue under the Agreement in the relevant Contract Year. Above that threshold the Parties must meet to agree an equitable adjustment, limited to the portion above 3%. If no adjustment is agreed within 90 days, either Party may refer the matter to an expert. Any benefit from a reduced or abolished generation charge stays with the Seller, and new charges on the Buyer''s purchase or trading are borne by the Buyer. Force majeure: if an event continues for more than 180 consecutive days, either Party may terminate on 30 days'' notice, provided the event is still continuing at the end of the notice period. No Termination Amount is payable.', 'Should any law, regulation or administrative decision enacted after the Signing Date impose a new tax, levy or charge on the generation or sale of electricity from the Facility, the Seller shall bear such cost unless it exceeds three per cent (3%) of the Seller''s revenue under this Agreement in the relevant Contract Year, in which case the Parties shall meet to agree an equitable adjustment.', 'Part II sections 17.3 to 17.5 (change in law); sections 10.1 to 10.5 (force majeure)', 'The allocation sits under ''Taxes, Levies and Regulatory Costs'', not a change-in-law heading. It covers only new taxes, levies and charges. Part II has no general change-in-law clause for other legal or regulatory changes, such as market rules, permitting or grid codes. Above the threshold the Parties only have to meet; no adjustment is guaranteed. Corporate income tax and penalties for the Seller''s non-compliance are excluded (17.5).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'Buyer is Jutland Board & Packaging A/S, which is unrated. Its credit is supported by a parent guarantee from Jutland Industri Holding A/S.', 'Buyer Jutland Board & Packaging A/S, unrated; parent guarantee from Jutland Industri Holding A/S', 'Section 4.2, key terms table, row 1', 'The Seller is not named by legal name; only the project, Havrebakke Wind Farm, is given. No rating trigger or guarantee amount is stated. The table is drawn from a legal due diligence summary and financial model v7, not from the contract itself.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '2_facility', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'Onshore wind farm of 8 turbines and 48.0 MW at Ringkøbing-Skjern, Denmark, in bidding zone DK1.', '8 turbines, 48.0 MW, Ringkøbing-Skjern, DK1', 'Section 4.2, key terms table, row 2; project line in the header', 'Only one capacity figure is given and it is not labelled AC or DC. The technology (onshore wind) is stated in the header line, not in the table row. No site address is given beyond the municipality.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'The supply period is 10 years from COD (commercial operation date).', '10 years from COD', 'Section 4.2, key terms table, row 3', 'The modelling note says the base case runs the contract price for ten years and uses merchant DK1 forward prices after that.', 'faithful');
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'Target COD is 1 Oct 2027 and the longstop date is 31 Mar 2028. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1.75m.', 'Target COD 1 Oct 2027; longstop 31 Mar 2028; LDs EUR 9,600/day, cap EUR 1.75m', 'Section 4.2, key terms table, row 4', 'The consequence of reaching the longstop date (for example a termination right) is not stated.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'The contract price is EUR 54.50/MWh. 30 % of the price is CPI-indexed, starting in 2029.', 'EUR 54.50/MWh; 30 % CPI-indexed from 2029', 'Section 4.2, key terms table, row 5', 'The row does not say whether the price is fixed in nominal or real terms, or the base year for the CPI index.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'Volume is pay-as-produced, covering 100 % of output. Expected annual production (P50) is 158 GWh/yr and a minimum of 118.5 GWh/yr is stated.', 'Pay-as-produced, 100 % of output; P50 158 GWh/yr; minimum 118.5 GWh/yr', 'Section 4.2, key terms table, row 6', 'The remedy if production falls below the minimum is not stated. The row does not say whether the minimum is a contractual guarantee or only a modelling assumption. No availability guarantee is mentioned.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'The Buyer receives the electricity and all guarantees of origin (GoOs).', 'Electricity + all GoOs to buyer', 'Section 4.2, key terms table, row 7', 'No GoO volume or cost is stated. Capacity or other attributes are not mentioned.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'The Buyer may curtail for up to 150 hours per year and is compensated at the contract price. Curtailment ordered by the TSO (the transmission system operator) is not compensated.', 'Buyer right 150 h/yr, compensated at contract price; TSO curtailment uncompensated', 'Section 4.2, key terms table, row 8', 'The treatment of negative prices is not addressed. The row does not say whether compensation takes the form of deemed delivery. No MWh cap is given.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'Settlement is physical, with delivery at the 60 kV Havrebakke substation. The Buyer is the balance responsible party (BRP) and bears imbalance costs.', 'Physical, 60 kV Havrebakke substation; buyer is BRP and bears imbalance', 'Section 4.2, key terms table, row 9', '', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'The Seller provides a bank guarantee of EUR 2,500,000, running to COD plus 12 months. The Buyer provides a letter of credit (LC) for 9 months of payments.', 'Seller bank guarantee EUR 2,500,000 to COD + 12 months; buyer LC 9 months of payments', 'Section 4.2, key terms table, row 10', 'The Buyer''s LC is sized as 9 months of payments, with no EUR amount given. Its duration is not stated.', 'faithful');
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'The termination amount is calculated as mark-to-market against the forward curve for the remaining term.', 'Mark-to-market vs forward curve for remaining term', 'Section 4.2, key terms table, row 11', 'The main events of default are not listed. The row is a one-line summary: it does not say which forward curve is used, who pays whom, or whether a floor or cap applies. The source is a legal due diligence summary, not the contract.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ic-key-terms', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T09:59:24+00:00', 1, 'If the cost of a change in law exceeds EUR 250k per year, the parties renegotiate. If that fails, either party may terminate, with no termination amount payable. A force majeure event lasting more than 180 days gives a termination right.', 'Renegotiation above EUR 250k/yr, then mutual termination right without termination amount; FM > 180 days termination right', 'Section 4.2, key terms table, row 12', 'Who bears change-in-law costs below the EUR 250k/yr threshold is not stated. The row does not say which party''s cost the threshold measures, or who holds the force majeure termination right.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'Seller is Havrebakke Vind ApS. Buyer is Jutland Board & Packaging A/S, which is unrated. Its payment obligations are guaranteed by its parent, Jutland Industri Holding A/S.', 'Seller: Havrebakke Vind ApS. Buyer: Jutland Board & Packaging A/S, unrated. Payment obligations guaranteed by Jutland Industri Holding A/S.', 'Part I; Part II 9.2; Annex 4 (as cited in the summary''s Key terms table)', 'This document is a law firm''s summary of the PPA, not the PPA itself. The instrument is a parent company guarantee, and the summary says it is the credit the committee relies on. No rating trigger is mentioned. The guarantee terms in Annex 4 are not reproduced.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '2_facility', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'Eight onshore wind turbines with 48.0 MW capacity at Havrebakke, Ringkøbing-Skjern Municipality, in bidding zone DK1. The country is Denmark, as the PPA is under Danish law.', 'Eight onshore turbines, 48.0 MW, Havrebakke, Ringkøbing-Skjern Municipality, DK1.', 'Part I; Annex 1 (as cited in the summary''s Key terms table)', 'One capacity figure is given and it is not labelled AC or DC. The summary does not state a DC figure.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'The Supply Period is ten years and starts on the Commercial Operation Date.', 'The Supply Period runs ten (10) years from the Commercial Operation Date.', 'Part I', '', 'faithful');
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'Target COD is 1 October 2027 and the Longstop Date is 31 March 2028. Delay damages are EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Target COD 1 October 2027. Longstop Date 31 March 2028. Delay damages EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Part II 3', 'Failure to reach COD by the Longstop Date is also an Event of Default (see term 11).', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'The price is EUR 54.50 per MWh, stated in the Election Sheet. Thirty per cent of the price is indexed annually to the Danish consumer price index from 1 January 2029.', 'EUR 54.50 per MWh per the Election Sheet. Thirty per cent of the price is adjusted annually from 1 January 2029 by the Danish consumer price index.', 'Part II 7.1; Annex 2 (Election Sheet), as cited in the summary''s Key terms table', 'The price is taken from the summary''s description of the Election Sheet. The sheet itself is not reproduced.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'Pay-as-produced: the Buyer takes 100 % of Metered Output. Expected Annual Production is 158,000 MWh (P50). Minimum Annual Production is 118,500 MWh, and a shortfall payment applies if it is not met.', '100 % of Metered Output. Expected Annual Production 158,000 MWh (P50). Minimum Annual Production 118,500 MWh with a shortfall payment.', 'Part I; Part II 4 (as cited in the summary''s Key terms table)', 'The summary does not say how the shortfall payment is calculated. It also does not say whether the minimum is a production or an availability guarantee, beyond naming it Minimum Annual Production.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'The Seller sells electricity and all Guarantees of Origin, transferred at no additional cost. No capacity product is sold.', 'Electricity and all Guarantees of Origin, transferred at no additional cost. No capacity product.', 'Part II 8', '', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'The Buyer may instruct reductions for up to 150 hours per Contract Year, paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer.', 'Buyer may instruct reductions for up to 150 hours per Contract Year, paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer.', 'Part II 5.4–5.5', 'The summary says the Seller has no equivalent curtailment right. The cap is stated in hours, not MWh. Negative prices are not addressed in this document.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'Settlement is physical, at the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Physical delivery at the metering point on the 60 kV side of the Havrebakke substation. Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Part I; Part II 4.2, 5.2 (as cited in the summary''s Key terms table)', 'Settlement is physical, so no financial reference price applies to this term.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'Seller: bank guarantee of EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: a parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Seller: bank guarantee EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Part II 9', 'The Buyer''s letter of credit is given as a formula (nine months of expected payments), not a figure. The parent guarantee amount and duration are not stated in this summary; they sit in Annex 4.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'Events of Default include non-payment within ten Business Days of notice, insolvency, and failure to reach COD by the Longstop Date. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Non-payment within ten Business Days of notice, insolvency and failure to reach COD by the Longstop Date are Events of Default. Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Part II 12–13', 'The calculation method is described, so the term is marked found. The summary does not give the discount rate or name the forward curve source. It says only that the source is named in the agreement and is a published DK1 forward curve. The list of default events may not be complete.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-legal-dd-summary', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T09:59:56+00:00', 1, 'A Change in Law cost impact above EUR 250,000 in a Contract Year triggers good-faith renegotiation. If there is no agreement within 90 days, the affected Party may terminate without a Termination Amount. Force majeure lasting more than 180 consecutive days gives either Party a termination right.', 'Change in Law is a defined term. A cost impact above EUR 250,000 in a Contract Year triggers good-faith renegotiation; absent agreement within 90 days the affected Party may terminate without a Termination Amount. Force majeure beyond 180 consecutive days gives either Party a termination right.', 'Part II 11, 10 (as cited in the summary''s Key terms table)', 'The summary does not say which Party bears change-in-law costs below the EUR 250,000 threshold. It describes the termination right as mutual and notes that lenders are expected to ask for it to be tightened.', NULL);
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'Seller is Havrebakke Vind ApS; Buyer is Jutland Board & Packaging A/S, which holds no credit rating from a recognised agency. The Buyer''s payment obligations are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee in Annex 4.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; Annex 4; section 9.2', 'There is no rating trigger. Section 9.5 is the nearest equivalent: if the Guarantor ceases to hold the entire share capital of the Buyer, or the guarantee ceases to be in force, the Buyer must within 20 Business Days deliver a replacement guarantee acceptable to the Seller or double the Letter of Credit. The document is a draft dated 12 March 2026 and is not binding until signed.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'Onshore wind farm of eight turbine generators with a total installed capacity of 48.0 MW (8 x 6.0 MW). It is at Havrebakke, Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Only one capacity figure (48.0 MW) is given. The document does not label it AC or DC and gives no separate DC figure.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'The Supply Period is ten (10) years, starting on the Commercial Operation Date. The Target Commercial Operation Date is 1 October 2027.', 'Supply Period: ten (10) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; sections 1.1 and 3.3', 'The start is not a fixed calendar date. The Commercial Operation Date is the date the Seller notifies that the section 3.3 conditions are met: all eight turbines commissioned, grid connected with meters verified, registrations done, and written notice given.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and Longstop Date is 31 December 2027. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1,750,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period; sections 3.4, 3.5 and 3.6; section 1.1', 'Both dates can be extended day for day for Force Majeure or Buyer breach, up to 180 days in aggregate (3.5). The liquidated damages are the Buyer''s sole remedy for delay except termination under 3.6. After the (extended) Longstop Date the Buyer may terminate; no Termination Amount is payable, and accrued liquidated damages are still owed.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'The Contract Price is EUR 58.00 per MWh, exclusive of VAT, applicable to each MWh of Metered Output from the Commercial Operation Date. There is no indexation: the price is fixed for the Supply Period.', 'Contract Price: EUR 58.00 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output from the Commercial Operation Date.', 'Annex 2 (Election Sheet); referenced in Part I, Price and section 7.1', 'The price is stated only in Annex 2, not in the body; Annex 2 prevails. Annex 2 says: ''Indexation: none. The Contract Price is fixed for the Supply Period and shall not be indexed.'' Because there is no indexation, there is no start date or share. Section 11.2 lets the Parties negotiate a price adjustment after a Change in Law, which sits uneasily with Part I saying price adjustment is governed exclusively by Annex 2.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected Annual Production is 158,000 MWh (P50) and Minimum Annual Production is 118,500 MWh (75% of P50). If output falls below the minimum, the Seller pays a shortfall payment capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the Metered Output is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; sections 4.1, 4.3, 4.5, 4.6; Annex 1; Annex 2', 'The guarantee is an annual minimum production, not an availability guarantee. The shortfall payment is zero when the DK1 day-ahead average is at or below the Contract Price. The minimum is pro-rated in the first and last Contract Year and reduced for Force Majeure, TSO-instructed reductions and Buyer breach (4.5, 4.6).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'The Buyer buys electricity at the Delivery Point plus all Guarantees of Origin issued for the Metered Output. The Guarantees of Origin are transferred at no additional cost, and no capacity product, ancillary service or other attribute is sold.', 'Product: electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of the Metered Output.', 'Part I, Product and Certificates; section 8', 'Guarantees of Origin go to the Buyer''s registry account within 15 Business Days after issue (8.1), with no separate price. The Seller need not procure replacement Guarantees of Origin for a production shortfall (8.2). Certificates under any replacement scheme are also transferred at no cost (8.3).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'The only curtailment the document addresses is output reduction instructed by the Transmission System Operator. The Buyer pays nothing for it, any compensation from the Transmission System Operator belongs to the Seller, and such reductions lower the Minimum Annual Production for the shortfall test.', 'Reductions of output instructed by the transmission system operator shall not give rise to any payment by the Buyer.', 'Section 5.4; also sections 4.6 and 5.5', 'The document gives the Buyer no right to curtail, sets no cap in hours or MWh, and does not pay curtailed energy as deemed delivered. The deemed quantity in 5.5 is used only to adjust the minimum production. Negative prices are not mentioned anywhere, and the Buyer must take 100% of Metered Output (4.1). Searched the full text for curtailment, deemed quantity, negative prices and output reductions.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'Settlement is physical, with title and risk passing to the Buyer at the Delivery Point, the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; sections 4.2 and 5.2; Annex 2', 'There is no financial reference price because settlement is physical. The Seller provides day-ahead and intraday production forecasts to the balance responsible party, without warranty (5.1).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'Seller gives a EUR 2,000,000 bank guarantee within 10 Business Days after Financial Close, valid until 12 months after the Commercial Operation Date. Buyer gives the Parent Company Guarantee plus a letter of credit equal to six months of expected payments, delivered at least 30 days before expected commercial operation and kept in force until 60 days after the Supply Period ends.', 'The Seller shall deliver a bank guarantee in the amount of EUR 2,000,000 within ten (10) Business Days after Financial Close, to remain in force until twelve (12) months after the Commercial Operation Date.', 'Part I, Credit Support; section 9 (9.1 to 9.5); Annex 3; Annex 4', 'The Buyer''s letter of credit is six twelfths of Expected Annual Production times the Contract Price, recalculated each 1 January. By my calculation that is about EUR 4.58 million at EUR 58.00/MWh; the document states no figure. Both banks must be rated at least A-. The Parent Company Guarantee stays in force until all amounts are paid in full (Annex 4, clause 6).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'Events of Default include non-payment (10 Business Days after notice), failure to deliver or replace credit support, insolvency, uncured material breach (30 days) and unauthorised assignment, plus Seller failure to reach commercial operation by the Longstop Date and Buyer Guarantor insolvency or guarantee failure. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period, discounted at the Danish central bank reference rate plus 2 points, determined by the Non-Defaulting Party.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Sections 12.1, 13.2 to 13.6; Reference Forward Price in section 1.1; production profile factor in Annex 2', 'The calculation is fully specified in the attached document: Reference Forward Price is defined in 1.1 and the 0.88 profile factor is in Annex 2. The amount is payable only if it is a loss for the Non-Defaulting Party; if it is a gain, nothing is payable by either Party (13.4). It is the exclusive remedy for loss of bargain (13.5). Terminations under 2.3, 3.6, 10.4 or 11.3 carry no Termination Amount (13.6).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v1-draft', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:01:02+00:00', 1, 'If a Change in Law raises a Party''s cost by more than EUR 250,000 in any Contract Year, the Parties must negotiate in good faith an adjustment, which may include the Contract Price. If none is agreed within 90 days, the affected Party may terminate on 60 days'' notice with no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice, also with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Sections 11.1 to 11.3, 10.4, 17.2 and 17.3', 'The cost allocation sits partly under Taxes, Levies and Regulatory Costs: the Seller bears taxes and charges on generation and injection, the Buyer those on offtake, transport, consumption or resale (17.2). New taxes are allocated the same way and are subject to section 11 above the threshold (17.3). The document does not say expressly who bears a change-in-law cost below the EUR 250,000 threshold beyond that split. Corporate income tax of general application is excluded from Change in Law. The price-adjustment possibility in 11.2 conflicts with the Annex 2 statement that the price is fixed.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'Seller is Havrebakke Vind ApS and Buyer is Jutland Board & Packaging A/S, which holds no credit rating. The Buyer''s payment obligations are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee in Annex 4.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; section 9.2; Annex 4', 'The guarantee covers all Buyer payment obligations including the Termination Amount (Annex 4 para 2). The Guarantor''s liability is capped at the Buyer''s own liability (Annex 4 para 5), and it must deliver audited accounts within six months of each financial year end (Annex 4 para 6). No rating trigger is stated for the Buyer or the Guarantor, and the document says nothing about the Guarantor''s financial standing. The Buyer must replace the guarantee or double the letter of credit if the Guarantor ceases to hold the entire share capital of the Buyer or the guarantee ceases to be in force (9.5).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'Onshore wind farm of eight turbines of 6.0 MW each, 48.0 MW in total, at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Only one capacity figure is given, with no separate AC and DC values (wind, so none expected).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'The Supply Period is twelve years and starts on the Commercial Operation Date. That date occurs when all eight turbines have passed commissioning tests, the Facility is connected with meters verified, and registrations are in place. The Seller then gives written notice.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; section 3.3; section 1.1 (Commercial Operation Date)', 'The start date is event-driven. The Target Commercial Operation Date of 1 October 2027 is a target, not the start date.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and the Longstop Date is 31 March 2028. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1,750,000 in aggregate, and are the Buyer''s sole remedy for delay except the right to terminate at the Longstop Date.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period; sections 3.4 to 3.6; section 12.1(f)', 'Both dates extend day for day for Force Majeure or Buyer breach, up to 180 days in aggregate (3.5). Termination at the Longstop Date under 3.6 carries accrued liquidated damages but no Termination Amount. Section 12.1(f) also makes missing the Longstop Date a Seller Event of Default, which on its face opens the Termination Amount route in 13.3. The document does not say which route prevails.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'The Contract Price is EUR 54.50 per MWh, excluding VAT, stated in Annex 2 (Election Sheet). Thirty per cent of the price is adjusted each 1 January from 2029 by the Danish consumer price index change over the preceding calendar year, and the other seventy per cent is fixed.', 'Contract Price: EUR 54.50 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output and of Deemed Delivered Electricity from the Commercial Operation Date.', 'Annex 2 (Election Sheet); referred to in Part I, Price and section 7.1', 'Part I and section 7.1 state no number and refer to Annex 2, which prevails. The indexation sentence in Annex 2 reads: Thirty per cent (30%) of the Contract Price shall be adjusted on 1 January of each Contract Year from 2029 by the percentage change in the Danish consumer price index over the preceding calendar year. Annex 2 is the only route for price adjustment during the Supply Period, apart from the Change in Law renegotiation in 11.2.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected Annual Production is 158,000 MWh (P50) and Minimum Annual Production is 118,500 MWh, 75% of P50. If metered plus deemed output falls short in a Contract Year, the Seller pays the shortfall in MWh times the positive excess of the average DK1 day-ahead price over the Contract Price, capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the sum of the Metered Output and the Deemed Delivered Electricity is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; sections 4.1, 4.3, 4.5, 4.6; Annex 1; Annex 2', 'The minimum is reduced pro rata in the first and last Contract Year and is further reduced for Force Majeure, output reductions instructed by the Transmission System Operator, and Buyer breach (4.6). No payment is due if the day-ahead price does not exceed the Contract Price. There is no separate availability guarantee. The 97 per cent availability in Annex 1 is only an assumption behind the P50. Section 4.3 states the P50 is used for sections 9.2 and 13.3 only.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'The Seller sells electricity from the Facility at the Delivery Point together with all Guarantees of Origin issued for the Metered Output, transferred to the Buyer at no additional cost within 15 Business Days after issue. No capacity product, ancillary service or other attribute is sold.', 'All Guarantees of Origin issued in respect of the Metered Output shall be transferred to the Buyer at no additional cost.', 'Part I, Product and Certificates; section 8', 'No separate price is stated for the certificates. Guarantees of Origin are not issued for Deemed Delivered Electricity and the Seller need not procure replacements for any shortfall (8.2). Certificates under a replacement scheme are also transferred at no additional cost (8.3).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'The Buyer may instruct output reductions for up to 150 hours per Contract Year on at least two hours'' notice. The energy not generated is Deemed Delivered Electricity paid at the Contract Price, and the Seller may refuse instructions beyond the limit. Reductions instructed by the Transmission System Operator give no payment from the Buyer, and any compensation from the Transmission System Operator belongs to the Seller.', 'The Buyer may instruct the Seller to reduce the output of the Facility for up to one hundred and fifty (150) hours per Contract Year, and the electricity that would otherwise have been generated during such hours shall be treated as Deemed Delivered Electricity and paid at the Contract Price.', 'Section 5.4; section 5.5; section 5.6; Annex 2', 'No provision on negative prices was found anywhere in the document. Deemed Delivered Electricity is defined only for Buyer-instructed reductions. Transmission System Operator reductions reduce the Minimum Annual Production in 4.6. Grid failure beyond the Delivery Point is Force Majeure (10.1), with no payment for undelivered electricity during it (10.3).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'Settlement is physical, with title and risk passing to the Buyer at the Delivery Point, the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; sections 4.2, 5.1, 5.2; Annex 2', 'No reference price applies because settlement is physical. The Seller provides day-ahead and intraday production forecasts to the balance responsible party, given without warranty (5.1).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'Seller: a bank guarantee of EUR 2,000,000 within 10 Business Days after Financial Close, in force until 12 months after the Commercial Operation Date. Buyer: the Parent Company Guarantee plus a letter of credit for nine months of expected payments, in force until 60 days after the end of the Supply Period.', 'The Buyer shall deliver a letter of credit in an amount equal to nine (9) months of expected payments under this Agreement, calculated as nine twelfths of the Expected Annual Production multiplied by the Contract Price in force at the time of calculation, no later than thirty (30) days before the expected Commercial Operation Date, to remain in force until sixty (60) days after the end of the Supply Period.', 'Part I, Credit Support; sections 9.1 to 9.5; Annex 3; Annex 4', 'Both instruments must come from a bank rated at least A-. The letter of credit is recalculated each 1 January to the Contract Price then in force. At the Annex 2 price of EUR 54.50 and 158,000 MWh, this is about EUR 6.46 million (my arithmetic from the document''s figures, not stated in it). The Seller guarantee can be drawn only for amounts unpaid under 3.4, 3.6 or 4.5, and it lapses 12 months after the Commercial Operation Date, so later shortfall payments are not secured by it. The Buyer must restore a drawn letter of credit within 10 Business Days (9.3). A lost rating or missed extension must be cured within 20 Business Days, failing which the full amount may be drawn as cash security (9.4).', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'Events of Default are: non-payment (10 Business Days after notice); failure to deliver, restore or replace credit support (10 Business Days after notice); insolvency; an uncured material breach (30 days after notice); and an assignment breach. For the Seller they also cover missing the Longstop Date or selling to a third party, and for the Buyer Guarantor insolvency or a lapsed Parent Company Guarantee. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price on the Expected Annual Production over the remaining Supply Period, discounted at the Danish central bank reference rate plus 2 percentage points and determined by the Non-Defaulting Party.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Section 12.1; section 13.2 to 13.6; section 1.1 (Reference Forward Price); Annex 2', 'The calculation is fully specified in the attached documents. The Reference Forward Price is the average of DK1 baseload forward quotes from at least three market participants chosen by the Non-Defaulting Party, adjusted by the 0.88 production profile factor in Annex 2. The amount is payable only if it is a loss to the Non-Defaulting Party, and it is the exclusive remedy for loss of the bargain (13.4, 13.5). No Termination Amount arises on termination under 2.3, 3.6, 10.4 or 11.3 (13.6). The Parent Company Guarantee covers the Termination Amount (Annex 4 para 2). See the overlap between 3.6 and 12.1(f) noted at term 4.', 'correct');
INSERT INTO extractions VALUES (2, 'havrebakke-ppa-v2-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:02:32+00:00', 1, 'If a Change in Law raises a Party''s cost by more than EUR 250,000 in a Contract Year, the Parties negotiate an adjustment in good faith, which may include the Contract Price. If none is agreed within 90 days of the notice, the affected Party may terminate on 60 days'' notice with no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice, also with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Sections 11.1 to 11.3; section 10.4; sections 17.2 and 17.3', 'Change in Law excludes general corporate income tax changes and changes published in final form before the Signing Date (11.1). The cost allocation sits partly under taxes: the Seller bears taxes on generation and injection and the Buyer bears those on offtake and resale. New taxes follow that split and fall under section 11 only if they meet the EUR 250,000 threshold (17.2, 17.3). No adjustment mechanism is stated below the threshold. Force Majeure excludes lack of funds, market price changes and insufficient wind (10.1).', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'Seller is Lichtung Offshore Wind GmbH & Co. KG (Emden), a single-purpose project company. Buyer is Rheintal Spezialchemie AG (Worms), rated BBB+ at signing. No guarantor of the Buyer is named. The Buyer''s credit protection is a rating trigger: if its rating falls below BBB- (or is withdrawn), it must post a EUR 20,000,000 letter of credit.', 'On the Signing Date the Buyer holds a long-term credit rating of BBB+ from a recognised rating agency.', 'Part I, Parties; Part II, section 9.3', 'The Seller''s credit support provider is Lichtung Energie Holding GmbH, Hamburg (ultimate parent of the Seller). It supports the Seller, not the Buyer. No parent guarantee of the Buyer appears in the document.', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'Offshore wind farm of 300 MW installed capacity in the German North Sea, about 60 km north-west of Borkum. It has twenty 15 MW turbines on monopile foundations and is connected through the transmission system operator''s offshore grid connection system.', 'The Facility is an offshore wind farm with an installed capacity of 300 MW located in the German North Sea approximately 60 km north-west of Borkum, consisting of twenty (20) wind turbine generators of 15 MW each on monopile foundations, one offshore substation and the inter-array cables, connected to the onshore transmission grid through the offshore grid connection system of the transmission system operator.', 'Part I, Facility; Annex 1', 'Only one capacity figure (300 MW) is given; the document does not split it into AC and DC. The bidding zone is not stated for the Facility itself. DE-LU is the zone of the Reference Price and of the Buyer''s production sites, and section 11.4(b) refers to the area in which the Facility is located.', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'Supply Period of fifteen years from the Start Date of 1 January 2029, ending on 31 December 2043. It is not extended by any delay in commissioning.', 'Supply Period: fifteen (15) years commencing on the Start Date of 1 January 2029.', 'Part I, Supply Period; Part II, section 1.1 (Start Date, Contract Year)', 'The period runs from a fixed calendar date, not from commissioning. Settlement starts only from the later of the Start Date and the day after the Commissioning Date (section 4.1). Sections 4, 7 and 8 take effect only once the Conditions Precedent in section 2.1 are met.', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'The Seller uses reasonable endeavours to commission by the Start Date, 1 January 2029. After that it owes delay compensation of EUR 40,000 per day, capped at EUR 6,000,000. The Longstop Commissioning Date is 1 July 2029, after which the Buyer may terminate with no Termination Amount payable.', 'If the Facility has not been commissioned by the Start Date, the Seller shall pay the Buyer delay compensation of EUR 40,000 for each day from the Start Date until the Facility is commissioned, up to an aggregate cap of EUR 6,000,000 (Delay Compensation).', 'Part II, sections 3.1(d), 3.2, 3.3, 3.4 and 1.1 (Longstop Commissioning Date)', 'Commissioning requires turbines totalling at least 240 MW (80% of 300 MW) to have passed take-over tests and be capable of exporting (section 3.2). At EUR 40,000 per day the cap is reached after 150 days, before the longstop date. Delay compensation is the Buyer''s sole financial remedy for late commissioning. Force Majeure suspends its accrual but does not extend the longstop date.', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'Strike Price of EUR 72.00 per MWh in the first Contract Year (2029), stated in Part I and in section 7.1. It rises by 2% on 1 January of each Contract Year from the second (2030) onwards, applied to the whole price and compounding: EUR 73.44 in 2030, EUR 74.91 in 2031.', 'Strike Price: EUR 72.00 per MWh, increased by two per cent (2%) on 1 January of each Contract Year from the second Contract Year onwards.', 'Part I, Price; Part II, section 7.1', 'This is a contract for difference. The Strike Price is settled against the hourly DE-LU day-ahead Reference Price rather than paid as a delivered-energy price. It includes the consideration for the Guarantees of Origin (section 7.1).', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'Fixed baseload volume of 1,000,000 MWh per Contract Year in equal hourly quantities, independent of actual output. The Seller''s P50 estimate is about 1,280,000 MWh a year, so the Contract Quantity is about 78% of P50. The Seller gives no availability or production guarantee, so there is no performance remedy.', 'Contract Quantity: 1,000,000 MWh per Contract Year, delivered as a baseload profile in equal hourly quantities.', 'Part I, Contract Quantity; Part II, sections 4.1, 5.3, 5.5; Annex 1, paragraph 5', 'Section 5.5 states: "The Seller gives no guarantee of availability or production." Outages do not reduce the Contract Quantity (section 5.3). The P50 figure is stated not to be a warranty. The Contract Quantity is reduced for the first Contract Year if commissioning is late (section 4.5) and in proportion to capacity lost to Force Majeure (section 10.4).', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'The product is financial settlement of the Contract Quantity against the Reference Price, plus transfer of Guarantees of Origin equal to the Contract Quantity each Contract Year. No electricity is sold or delivered. The Guarantee of Origin price is included in the Strike Price. The Seller bears issuing fees and the Buyer bears cancellation fees.', 'Product: (a) the financial settlement of the Contract Quantity against the Reference Price under section 4, and (b) the transfer to the Buyer of Guarantees of Origin in a quantity equal to the Contract Quantity under section 8.', 'Part I, Product and Certificates; Part II, sections 4.6, 7.1, 8.1 to 8.4', 'If the Facility generates less than the Contract Quantity, the Seller must procure the Guarantee of Origin shortfall from other German offshore wind facilities at its own cost (section 8.2). Capacity or other attributes are not mentioned anywhere in the document.', 'wrong_value');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'Curtailment is instructed by the transmission system operator, and the document gives the Buyer no right to curtail. Curtailment does not reduce the Seller''s Contract Quantity obligations unless it is Force Majeure; congestion, redispatch, system security and market-related curtailment are expressly not Force Majeure. Compensation from the operator belongs to the Seller. No hours or MWh cap is stated. Hours with a negative Reference Price produce no settlement amount.', '5.4 The Seller''s obligations in respect of the Contract Quantity shall not be reduced by any curtailment of the Facility''s output instructed by the transmission system operator, save where such curtailment constitutes Force Majeure.', 'Part II, sections 5.4, 4.1, 4.4, 10.1, 10.2', 'The document has no separate deemed-delivery clause. The Contract Quantity is settled whether or not the Facility generates (section 4.1), which has the same effect. Negative Price Hours: no Settlement Amount is payable, but the Guarantee of Origin quantity is not reduced (section 4.4). Curtailment resulting from an event that is itself Force Majeure is covered by section 10.1, and section 10.4 then reduces the Hourly Quantity in proportion to the capacity unavailable.', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'Settlement is financial and there is no Delivery Point (stated as not applicable). The Reference Price is the hourly day-ahead price for the DE-LU bidding zone. The Seller remains balance responsible for the Facility and bears all imbalance costs; the Buyer balances its own consumption.', '5.2 The Seller shall remain responsible for the balancing of the Facility and shall bear all imbalance costs.', 'Part I, Delivery Point and Balancing, and Settlement; Part II, sections 1.1 (Reference Price), 4, 5.2', 'The Seller sells the Facility''s physical output in the market for its own account. It must do so without claiming a statutory market premium, so that Guarantees of Origin can be issued (section 4.6).', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'Seller: a EUR 25,000,000 parent company guarantee from Lichtung Energie Holding GmbH, delivered within 10 Business Days after signing and kept until 12 months after the Supply Period ends or earlier discharge. Buyer: none at signing; a EUR 20,000,000 letter of credit is due within 20 Business Days if its rating falls below BBB- or is withdrawn, and is returned after six consecutive months at BBB- or above.', 'Seller: parent company guarantee from Lichtung Energie Holding GmbH in the amount of EUR 25,000,000 in the form of Annex 4 (section 9.1).', 'Part I, Credit Support; Part II, sections 9.1 to 9.4; Annexes 3 and 4', 'If the guarantor becomes insolvent, ceases to be an affiliate or disputes the guarantee, the Seller must replace it within 20 Business Days with a EUR 25,000,000 letter of credit from a bank rated at least A- (section 9.2). Letters of credit expire not earlier than 12 months after issue and extend automatically (Annex 3). The guarantee also covers any Termination Amount payable by the Seller (Annex 4, paragraph 1).', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 0, NULL, NULL, 'Part II, sections 12.1 and 13.3; Annex 5 (not attached)', 'The Termination Amount is defined only by reference to Annex 5, which is not attached. Section 13.3 states: "The Termination Amount shall be calculated in accordance with Annex 5 (Termination Amount Methodology)." The annex list ends with: "Annex 5 — Termination Amount Methodology [to be agreed prior to Financial Close]". Attaching it is also a Condition Precedent (section 2.1(d)). The events of default are listed in section 12.1(a) to (h): non-payment (10 Business Days after notice), failure to provide credit support (10 Business Days), insolvency, other material breach (30 days), repudiation, Seller abandonment for 90 days, Seller failure to transfer Guarantees of Origin within 120 days, and breach of the assignment or change-of-control rules. No Termination Amount is payable on termination under sections 2.2, 3.4, 10.5 or 11.2 (section 13.5).', 'correct');
INSERT INTO extractions VALUES (2, 'lichtung-offshore-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:03:34+00:00', 1, 'A change in law is borne by the Party on whom the cost or benefit falls, with no adjustment of the Strike Price or Contract Quantity. If the Product can no longer exist or be delivered, the Parties negotiate in good faith for 90 days, after which either may terminate with no Termination Amount. Either Party may terminate if Force Majeure lasts more than 180 consecutive days.', '11.3 Any other Change in Law, including one that changes the cost of Guarantees of Origin, grid charges or levies, is borne by the Party on whom the cost or benefit falls.', 'Part II, sections 11.1 to 11.3, 10.5, 17.3', 'No monetary threshold applies to a change in law. The renegotiation right applies only where the Product, or a material part of it, no longer exists (section 11.2). Levies or revenue caps imposed by a public authority stay with the Party on whom they are imposed (section 17.3). Force Majeure termination (section 10.5) carries no Termination Amount.', 'wrong_value');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'Seller is Olivos Solar Proyecto Dos S.L. and Buyer is Meseta Energía Comercializadora S.A., both Spanish companies. The Buyer has no guarantor: its obligations are supported solely by a letter of credit (section 9.2), and no parent company guarantee is given by either Party.', 'The Buyer is a licensed electricity trader and no guarantee of the Buyer''s obligations is provided by any affiliate of the Buyer.', 'Part I, Parties; Part II sections 9.2 and 9.6; Annex 4 (not used)', 'The Buyer contracts as a stand-alone electricity trader and its shareholders have given no undertaking (section 9.6). The only rating requirement is A- for the bank issuing the letter of credit (sections 9.2 and 9.5). No rating trigger on the Buyer itself is stated.', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'Ground-mounted solar PV plant (bifacial modules on single-axis trackers) with 90 MWp DC installed capacity and 75 MW AC grid export capacity. It is at Valdeolivos, Province of Badajoz, Extremadura, Spain, and the price references use the Spanish bidding zone.', 'Facility: a ground-mounted solar photovoltaic plant with an installed capacity of 90 MWp (direct current) and a grid export capacity of 75 MW (alternating current) located at Valdeolivos in the Province of Badajoz, Spain, as further described in Annex 1.', 'Part I, Facility; Annex 1 (A1.1 to A1.4); bidding zone referenced in sections 7.3, 7.4 and 13.3', 'The document refers only to the Spanish bidding zone and gives no zone code. The Extremadura region and the technology detail are in Annex 1, not Part I.', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'Twelve (12) years, starting on the Commercial Operation Date. The Commercial Operation Date occurs when the Seller has given notice, with certificates, that the section 3.4 conditions are met.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; Part II sections 1.1 and 3.4', 'The start is an event, not a fixed date. It is conditional on the authorisation, TSO export confirmation for 75 MW, metering and a 72-hour 60 MW export test under section 3.4.', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'Target Commercial Operation Date is 30 June 2027 and the Longstop Date is 31 December 2027. For delay beyond the target, the Seller pays liquidated damages of EUR 6,000 per day, capped at EUR 1,500,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 30 June 2027, the Seller shall pay the Buyer liquidated damages of EUR 6,000 for each day of delay, up to an aggregate cap of EUR 1,500,000.', 'Part I, Target Commercial Operation Date; Part II sections 1.1, 3.5, 3.6 and 3.7', 'The liquidated damages are the Buyer''s sole remedy for delay until the Longstop Date. Both dates are extended day for day for Force Majeure or TSO delay, up to 180 days in aggregate (section 3.6). After the extended Longstop Date the Buyer may terminate, unpaid delay damages remain payable, and no Termination Amount is payable (section 3.7). The delay damages can be drawn on the Seller''s performance bond (section 9.1).', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'The Contract Price is EUR 38.75 per MWh, fixed for the whole Supply Period with no indexation or escalation, so there is no indexation start date or share. No payment is due for hours with a negative day-ahead price.', 'Contract Price: EUR 38.75 per MWh, fixed for the Supply Period without indexation.', 'Part I, Price; Part II sections 7.1 and 7.4', 'Section 7.1 says the price is not adjusted for inflation, market prices or any other factor, except under sections 7.4 (negative prices) and 17.3 (new taxes above a threshold). The price includes Guarantees of Origin and excludes VAT.', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output, with no minimum or maximum annual quantity. Expected Annual Production is 165,000 MWh (P50), an estimate and not a delivery obligation. The Seller guarantees 97% Availability in each Contract Year, and the remedy is availability damages capped at 5% of the annual amount payable by the Buyer.', 'The Buyer purchases one hundred per cent (100%) of the Metered Output during the Supply Period.', 'Part I, Contract Quantity and volume structure; Part II sections 1.1 (Availability), 4.1, 4.4, 5.4 and 5.6; Annex 1 (A1.5, A1.6)', 'Availability damages = shortfall in percentage points x 1% of Expected Annual Production x Contract Price x 50%. They are the Buyer''s sole remedy for an Availability shortfall (section 5.6). Availability counts hours at 95% of irradiance-adjusted capacity, excludes Force Majeure and grid-connection hours not caused by the Seller, and counts planned maintenance as unavailability. The P50 is not adjusted for module degradation (A1.5).', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'The Seller sells electricity delivered at the Delivery Point together with all Guarantees of Origin issued for it. The Guarantees of Origin are transferred to the Buyer at no additional cost, because the Contract Price includes them. No capacity product, ancillary service or other attribute is sold.', 'Electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of that electricity.', 'Part I, Product; Part II sections 7.1, 7.4 and 8', 'The Seller must instruct transfer to the Buyer''s register account within 30 days after issue (section 8.1). A successor certificate is transferred without price adjustment (section 8.2). Guarantees of Origin are still transferred for electricity delivered in negative-price hours (section 7.4).', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 0, NULL, NULL, NULL, 'The document has no curtailment clause. Nothing says who may curtail the Facility, there is no cap in hours or MWh, and there is no deemed-delivery payment for curtailed energy. Part I, all of Part II (sections 1 to 21) and Annexes 1 to 4 were read for this. Related provisions that do exist: (a) negative prices, where section 7.4 says the Contract Price does not apply and no payment is due for electricity delivered in an hour with a negative day-ahead price, though that output is still delivered and still generates Guarantees of Origin; (b) section 10.4, under which no payment is due for electricity not delivered because of Force Majeure, which includes failure of the transmission grid beyond the Delivery Point (section 10.1); (c) sections 4.1 and 4.5, which oblige the Buyer to take all electricity generated and not refuse delivery. Treatment of grid-operator curtailment is not addressed.', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'Settlement is physical at the Delivery Point, the 220 kV connection point at the Valdeolivos substation, so there is no financial reference price. The Buyer is market representative and balance responsible party from the Commercial Operation Date and bears all imbalance costs.', 'The Buyer shall act as the market representative of the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; Part II sections 4.3, 5.2 and 5.3; Annex 1 (A1.4)', 'The Seller is not liable for imbalance costs except where the imbalance results from its failure to notify an outage under sections 5.4 or 5.5 (section 5.3). Title and risk pass at the Delivery Point (section 4.3). For test electricity before the Commercial Operation Date the Buyer also acts as market representative under section 5.2 (section 3.3).', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'Seller: performance bond of EUR 1,200,000 from the Signing Date until the Commercial Operation Date. Buyer: letter of credit equal to three months of expected payments (EUR 1,598,437.50 on the Signing Date), from the Commercial Operation Date until the end of the Supply Period.', 'Seller: performance bond of EUR 1,200,000 from the Signing Date until the Commercial Operation Date (Annex 2).', 'Part I, Credit Support; Part II sections 9.1 to 9.6; Annex 2; Annex 3', 'Part II timing is more detailed than Part I. The Seller''s bond is due within 10 Business Days after the Signing Date (section 9.1). The Buyer''s letter of credit is due at least 10 Business Days before the expected Commercial Operation Date and is maintained until 60 days after the end of the Supply Period (section 9.2). Part I prevails on conflict. Both instruments come from a bank rated at least A- and are payable on first demand. The Annex 2 bond is valid until the earliest of return of the original, confirmation of the Commercial Operation Date, or 30 June 2028. The letter of credit may have a one-year term with replacement 30 days before expiry (section 9.3). No credit support from the Seller after the Commercial Operation Date is stated. The amount in the Annex 3 form is left blank, but section 9.2 states it.', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'Events of Default for either Party are non-payment (10 Business Days after notice), failure to provide or restore credit support (10 Business Days after notice), an Insolvency Event, an uncured material breach (30 days, or up to 90 days where cure takes longer) and a materially incorrect representation. The Seller also defaults on third-party sales or Permit revocation not reinstated in 90 days, and the Buyer on loss of its trader licence or market registration not reinstated in 30 days, or revocation of its powers of representation. The Termination Amount is an independent expert''s replacement value: the present value at the Interest Rate of the difference between the Contract Price and the forward price for the Spanish bidding zone, applied to Expected Annual Production over the remainder of the Supply Period.', 'The expert shall determine, under section 20.3, the present value at the Interest Rate of the difference between the Contract Price and the forward price for the Spanish bidding zone at the early termination date, evidenced by quotations from at least two (2) market participants, applied to the Expected Annual Production over the remainder of the Supply Period.', 'Part II sections 12.1, 13.1 to 13.5, 16.4 and 20.3', 'The calculation is in the body of the Agreement, not in an unattached document. The Interest Rate is the ECB main refinancing rate plus 4 percentage points (section 1.1). If the Termination Amount is negative, nothing is payable by either Party (section 13.2). The Defaulting Party bears the expert''s costs and pays within 20 Business Days after the determination (sections 13.3 and 13.4). No Termination Amount is payable on termination under sections 2.3, 3.7 or 10.5 (section 13.5). A Lender may suspend early termination for up to 120 days after a Seller default (section 16.4).', 'correct');
INSERT INTO extractions VALUES (2, 'olivos-solar-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:05:05+00:00', 1, 'A new tax, levy or charge on generation or sale from the Facility, enacted after the Signing Date, is borne by the Seller unless it exceeds 3% of the Seller''s revenue under the Agreement in the relevant Contract Year. Above that, the Parties meet to agree an equitable adjustment limited to the excess, and the expert procedure applies if there is no agreement within 90 days. Force Majeure continuing for more than 180 consecutive days gives either Party a right to terminate on 30 days'' notice, with no Termination Amount.', 'Should any law, regulation or administrative decision enacted after the Signing Date impose a new tax, levy or charge on the generation or sale of electricity from the Facility, the Seller shall bear such cost unless it exceeds three per cent (3%) of the Seller''s revenue under this Agreement in the relevant Contract Year, in which case the Parties shall meet to agree an equitable adjustment.', 'Part II section 17.3 (change in law, under Taxes, Levies and Regulatory Costs); sections 17.4 and 17.5; section 10.5 (Force Majeure termination)', 'The allocation sits under section 17, not under a change-in-law heading, and no other change-in-law provision was found. Benefits from abolished or reduced Seller-side charges stay with the Seller, and new Buyer-side charges are borne by the Buyer (section 17.4). No adjustment is available for corporate income tax or penalties from the Seller''s non-compliance (section 17.5). For Force Majeure termination, the event must still be continuing at the end of the notice period (section 10.5).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'The Buyer is Jutland Board & Packaging A/S, which is unrated. Jutland Industri Holding A/S gives a parent guarantee.', 'Buyer Jutland Board & Packaging A/S, unrated; parent guarantee from Jutland Industri Holding A/S', 'Section 4.2, key terms table, row 1', 'The Seller is not named in the document. The guarantee amount, cap, duration and any rating trigger are not stated. The source is a due diligence summary, not the contract itself.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'Onshore wind farm of 8 turbines and 48.0 MW in Ringkøbing-Skjern, Denmark, in bidding zone DK1.', '8 turbines, 48.0 MW, Ringkøbing-Skjern, DK1', 'Section 4.2, key terms table, row 2; project header line', 'A single MW figure is given. The document does not say whether it is AC or DC. No site coordinates or exact site address are given.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'The supply period is 10 years from commercial operation date (COD).', '10 years from COD', 'Section 4.2, key terms table, row 3', 'The modelling note is consistent with this: the base case runs the contract price for ten years, then merchant prices.', 'faithful');
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'Target COD is 1 October 2027 and the longstop date is 31 March 2028. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1.75m.', 'Target COD 1 Oct 2027; longstop 31 Mar 2028; LDs EUR 9,600/day, cap EUR 1.75m', 'Section 4.2, key terms table, row 4', 'The consequence of passing the longstop date, such as a termination right, is not stated.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'The contract price is EUR 54.50/MWh. 30 % of the price is CPI-indexed from 2029.', 'EUR 54.50/MWh; 30 % CPI-indexed from 2029', 'Section 4.2, key terms table, row 5', 'The price is taken from the committee paper table, which is based on the legal due diligence summary and financial model v7. The contract clause is not cited. The CPI index used and the base date are not stated.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'Pay-as-produced, with 100 % of output sold to the Buyer. Expected annual production (P50) is 158 GWh/yr and the minimum is 118.5 GWh/yr.', 'Pay-as-produced, 100 % of output; P50 158 GWh/yr; minimum 118.5 GWh/yr', 'Section 4.2, key terms table, row 6', 'The remedy if production falls below the 118.5 GWh/yr minimum is not stated. It is also not stated whether the minimum is a guarantee or only a modelling floor. No availability guarantee is mentioned.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'The Seller sells electricity and all guarantees of origin (GoOs) to the Buyer.', 'Electricity + all GoOs to buyer', 'Section 4.2, key terms table, row 7', 'The GoO amount and any separate price or cost are not stated. Capacity or other attributes are not mentioned.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'The Buyer may curtail up to 150 hours per year and is compensated at the contract price. Curtailment ordered by the TSO is uncompensated.', 'Buyer right 150 h/yr, compensated at contract price; TSO curtailment uncompensated', 'Section 4.2, key terms table, row 8', 'The treatment of negative prices is not addressed. The wording ''compensated at contract price'' is read as deemed-delivery payment. The document does not use the term ''deemed delivered''.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'Physical settlement at the 60 kV Havrebakke substation. The Buyer is balance responsible (BRP) and bears imbalance cost.', 'Physical, 60 kV Havrebakke substation; buyer is BRP and bears imbalance', 'Section 4.2, key terms table, row 9', 'No reference price is needed because settlement is physical.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'The Seller provides a bank guarantee of EUR 2,500,000, running until COD plus 12 months. The Buyer provides a letter of credit (LC) covering 9 months of payments.', 'Seller bank guarantee EUR 2,500,000 to COD + 12 months; buyer LC 9 months of payments', 'Section 4.2, key terms table, row 10', 'The Buyer''s LC is sized as 9 months of payments, with no amount in EUR. Its duration is not stated.', 'faithful');
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'The termination amount is calculated as mark-to-market against the forward curve for the remaining term.', 'Mark-to-market vs forward curve for remaining term', 'Section 4.2, key terms table, row 11', 'The document lists no events of default. The calculation is described only in outline: the forward curve source, who determines the amount, and whether it is two-way are not stated.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ic-key-terms', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:05:27+00:00', 1, 'A change in law costing above EUR 250k/yr triggers renegotiation, then a mutual termination right without a termination amount. Force majeure lasting more than 180 days gives a termination right.', 'Renegotiation above EUR 250k/yr, then mutual termination right without termination amount; FM > 180 days termination right', 'Section 4.2, key terms table, row 12', 'The document does not say who bears the cost of a change in law below the EUR 250k/yr threshold. It also does not say which party holds the force majeure termination right, or whether that termination carries a termination amount.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'Seller is Havrebakke Vind ApS. Buyer is Jutland Board & Packaging A/S, which is unrated. The Buyer''s payment obligations are guaranteed by its parent, Jutland Industri Holding A/S, under a parent company guarantee in Annex 4.', 'Seller: Havrebakke Vind ApS. Buyer: Jutland Board & Packaging A/S, unrated. Payment obligations guaranteed by Jutland Industri Holding A/S.', 'Part I; Part II 9.2; Annex 4', 'The document is a counsel''s summary of the PPA, not the PPA text. No rating trigger is mentioned. The summary says the parent guarantee is the credit the committee relies on and recommends reviewing the guarantor''s accounts for the last three years.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'Eight onshore wind turbines with 48.0 MW of capacity, at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'Eight onshore turbines, 48.0 MW, Havrebakke, Ringkøbing-Skjern Municipality, DK1.', 'Part I; Annex 1', 'The summary gives a single 48.0 MW figure and does not say whether it is AC or DC.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'The Supply Period is ten years and starts on the Commercial Operation Date.', 'The Supply Period runs ten (10) years from the Commercial Operation Date.', 'Part I', '', 'faithful');
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'Target COD is 1 October 2027 and the Longstop Date is 31 March 2028. Delay damages are EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Target COD 1 October 2027. Longstop Date 31 March 2028. Delay damages EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Part II 3', 'Failure to reach COD by the Longstop Date is also an Event of Default (Part II 12–13).', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'The price is EUR 54.50 per MWh, stated in the Election Sheet. Thirty per cent of the price is indexed annually to the Danish consumer price index from 1 January 2029.', 'EUR 54.50 per MWh per the Election Sheet. Thirty per cent of the price is adjusted annually from 1 January 2029 by the Danish consumer price index.', 'Part II 7.1; Annex 2 (price stated per the Election Sheet)', 'The summary does not say whether Annex 2 is the Election Sheet. It cites both Part II 7.1 and Annex 2 for the price.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'The Buyer takes 100 % of Metered Output on a pay-as-produced basis. Expected Annual Production is 158,000 MWh (P50). Minimum Annual Production is 118,500 MWh, and a shortfall payment is the remedy.', '100 % of Metered Output. Expected Annual Production 158,000 MWh (P50). Minimum Annual Production 118,500 MWh with a shortfall payment.', 'Part I; Part II 4', 'The summary does not state how the shortfall payment is calculated. It does not mention a separate availability guarantee.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'The Seller sells electricity and all Guarantees of Origin, which are transferred at no additional cost. No capacity product is sold.', 'Electricity and all Guarantees of Origin, transferred at no additional cost. No capacity product.', 'Part II 8', '', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'The Buyer may instruct reductions for up to 150 hours per Contract Year, and the curtailed energy is paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer.', 'Buyer may instruct reductions for up to 150 hours per Contract Year, paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer.', 'Part II 5.4–5.5', 'The summary says the Seller has no equivalent curtailment right. The cap is stated in hours only, with no MWh cap. Treatment of negative prices is not addressed in the summary.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'Delivery is physical, at the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Physical delivery at the metering point on the 60 kV side of the Havrebakke substation. Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Part I; Part II 4.2, 5.2', 'Settlement is physical, so no financial reference price applies.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'Seller: a bank guarantee of EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: a parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Seller: bank guarantee EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Part II 9', 'The summary does not state the duration of the Buyer''s letter of credit or the amount or cap of the parent company guarantee.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'Events of Default include non-payment within ten Business Days of notice, insolvency, and failure to reach COD by the Longstop Date. The Termination Amount is the present value, over the remaining Supply Period, of the difference between the Contract Price and the Reference Forward Price.', 'Non-payment within ten Business Days of notice, insolvency and failure to reach COD by the Longstop Date are Events of Default. Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Part II 12–13', 'The calculation method is stated in the summary, so the term is treated as found. The source of the Reference Forward Price is named in the PPA but not in this summary. Counsel confirms it is a published forward curve for DK1. The summary does not say which party pays when the difference is negative.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-legal-dd-summary', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:06:03+00:00', 1, 'Change in Law is a defined term. A cost impact above EUR 250,000 in a Contract Year triggers good-faith renegotiation. If there is no agreement within 90 days, the affected Party may terminate without a Termination Amount. Force majeure lasting more than 180 consecutive days gives either Party a termination right.', 'Change in Law is a defined term. A cost impact above EUR 250,000 in a Contract Year triggers good-faith renegotiation; absent agreement within 90 days the affected Party may terminate without a Termination Amount. Force majeure beyond 180 consecutive days gives either Party a termination right.', 'Part II 11, 10', 'The summary does not say which party bears change-in-law costs below the EUR 250,000 threshold. It describes the termination right as mutual and says lenders are expected to ask for it to be tightened.', NULL);
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'Seller is Havrebakke Vind ApS and Buyer is Jutland Board & Packaging A/S, which holds no credit rating. The Buyer''s payment obligations are guaranteed by its parent Jutland Industri Holding A/S under a Parent Company Guarantee (Annex 4), backed by a Buyer letter of credit.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; section 9.2; section 9.5; Annex 4', 'The document is a draft dated 12 March 2026 and is not binding until signed. Delivery of the Parent Company Guarantee is a condition precedent (section 2.1(d)). The Guarantor''s liability is capped at the Buyer''s own liability (Annex 4, para 5). No credit rating or rating trigger is stated for the Buyer or the Guarantor; ratings (A- or equivalent) are required only of the banks issuing the guarantee and letter of credit. The only trigger on the guarantee is structural: if the Guarantor stops holding all the Buyer''s share capital, or the guarantee lapses, the Buyer must deliver a replacement guarantee or double the letter of credit within 20 Business Days (section 9.5).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'Onshore wind farm of eight turbines with a total installed capacity of 48.0 MW (8 x 6.0 MW), at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Only one capacity figure (48.0 MW) is given; the document does not distinguish AC from DC capacity. Annex 1 adds hub height 125 m, rotor diameter 162 m and a 60 kV grid connection.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'The Supply Period is ten years, starting on the Commercial Operation Date.', 'Supply Period: ten (10) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; section 1.1 (Commercial Operation Date); section 3.3', 'The start is not a fixed calendar date. The Commercial Operation Date occurs when the Seller gives written notice that the section 3.3 conditions are met (all eight turbines commissioned, grid connected, meters verified, registrations done).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and the Longstop Date is 31 December 2027. For delay after the target date the Seller pays liquidated damages of EUR 9,600 per day, capped at EUR 1,750,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period; section 3.4; section 3.5; section 3.6; section 1.1', 'Both dates are extended day for day for Force Majeure or Buyer breach, up to 180 days in aggregate (section 3.5). The liquidated damages are the Buyer''s sole remedy for delay, except the right to terminate if the Longstop Date (as extended) is missed. On that termination the Seller pays accrued unpaid liquidated damages and no Termination Amount is payable (section 3.6). Missing the Longstop Date is also an Event of Default for the Seller (section 12.1(f)).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'The Contract Price is EUR 58.00 per MWh, exclusive of VAT, from the Commercial Operation Date. It is fixed for the Supply Period with no indexation.', 'Contract Price: EUR 58.00 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output from the Commercial Operation Date.', 'Annex 2 (Election Sheet); referenced from Part I, Price and section 7.1', 'The price sits only in Annex 2, not in the body. Annex 2 also states: ''Indexation: none. The Contract Price is fixed for the Supply Period and shall not be indexed.'' Part I and section 7.1 say price adjustment is governed exclusively by Annex 2, but section 11.2 allows a negotiated adjustment to the Contract Price after a Change in Law above the threshold. The document does not reconcile the two.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected annual production is 158,000 MWh (P50) and the Minimum Annual Production is 118,500 MWh (75% of P50). If output falls below the minimum, the Seller pays a shortfall payment capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the Metered Output is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; sections 4.1, 4.3, 4.5, 4.6; Annex 1; Annex 2', 'The shortfall payment is positive only when the DK1 day-ahead price exceeds the Contract Price. The minimum is reduced pro rata in the first and last Contract Year, and further reduced for Force Majeure, Transmission System Operator output reductions and Buyer breach (sections 4.5 and 4.6). The Seller gives no guarantee of quantity in any hour, day or month (section 4.3). The document states a minimum production guarantee, not a separate availability guarantee.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'The Seller sells electricity from the Facility together with all Guarantees of Origin for the Metered Output, transferred to the Buyer at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'Product: electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of the Metered Output.', 'Part I, Product and Certificates; section 8.1; section 8.3', 'Certificates are transferred monthly within 15 Business Days of issue (section 8.1). The Seller need not procure replacement Guarantees of Origin to cover a production shortfall (section 8.2). Certificates under any replacement scheme also pass to the Buyer at no additional cost (section 8.3).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'The document addresses only curtailment instructed by the Transmission System Operator. The Buyer makes no payment for it, any compensation from the Transmission System Operator belongs to the Seller, and the Minimum Annual Production is reduced by the lost output.', 'Reductions of output instructed by the transmission system operator shall not give rise to any payment by the Buyer.', 'Section 5.4; section 4.6; section 5.5', 'Curtailed energy is not paid as deemed delivery. The deemed-quantity method in section 5.5 only adjusts the Minimum Annual Production under section 4.6. The document gives the Buyer no right to curtail the Facility and sets no cap in hours or MWh. It contains no provision on negative prices. These gaps are confirmed by reading the whole document, not by industry practice.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'Settlement is physical, with title and risk passing at the Delivery Point, the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement; Part I, Delivery Point and Balancing; sections 4.2 and 5.2; Annex 2', 'Because settlement is physical, no financial reference price applies. The Seller provides day-ahead and intraday production forecasts to the balance responsible party without warranty (section 5.1).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'Seller: a bank guarantee of EUR 2,000,000, delivered within 10 Business Days after Financial Close and kept in force until 12 months after the Commercial Operation Date. Buyer: the Parent Company Guarantee plus a letter of credit equal to six months of expected payments, in force until 60 days after the end of the Supply Period.', 'The Seller shall deliver a bank guarantee in the amount of EUR 2,000,000 within ten (10) Business Days after Financial Close, to remain in force until twelve (12) months after the Commercial Operation Date.', 'Part I, Credit Support; sections 9.1 to 9.5; Annex 3; Annex 4', 'The Buyer''s letter of credit is six twelfths of Expected Annual Production times the Contract Price, delivered at least 30 days before the expected Commercial Operation Date and recalculated each 1 January (section 9.2). By calculation from the document''s own formula (6/12 x 158,000 MWh x EUR 58.00), the initial amount is about EUR 4,582,000; this figure is not stated in the document. Both banks must be rated at least A- or equivalent. The Seller''s guarantee can be drawn only for unpaid amounts under sections 3.4, 3.6 or 4.5. A lost bank rating or a missing extension must be cured within 20 Business Days, failing which the other Party may draw the full amount as cash security (section 9.4).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'Events of Default include non-payment (10 Business Days after notice), failure to deliver, restore or replace credit support, insolvency, unremedied material breach (30 days), and prohibited assignment. Seller-specific events are missing the Longstop Date and selling to third parties, and Buyer-specific events are Guarantor insolvency or loss of the Parent Company Guarantee. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period, discounted at the Danish central bank reference rate plus 2 percentage points.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Part II, sections 12.1, 13.2 to 13.5; Reference Forward Price in section 1.1; production profile factor in Annex 2', 'The calculation is fully stated in the attached document. The Reference Forward Price is the average of DK1 baseload forward quotes from at least three market participants chosen by the Non-Defaulting Party, adjusted by the Annex 2 profile factor of 0.88. The amount is payable only if it is a loss for the Non-Defaulting Party; if it is a gain, nothing is payable by either Party (section 13.4). It is the exclusive remedy for loss of bargain (section 13.5) and sits outside the EUR 2,000,000 annual liability cap (section 14.2). No Termination Amount applies on termination under sections 2.3, 3.6, 10.4 or 11.3 (section 13.6).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v1-draft', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:07:21+00:00', 1, 'If a Change in Law raises a Party''s cost by more than EUR 250,000 in a Contract Year, the Parties negotiate in good faith an adjustment that may include the Contract Price. If none is agreed within 90 days, the affected Party may terminate on 60 days'' notice with no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice, also with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Part II, sections 11.1 to 11.3; section 17.2 and 17.3; section 10.4', 'Change in Law covers Danish and EU law, grid codes and tariffs, including Guarantee of Origin rules, grid tariffs and taxation of electricity generation. It excludes general corporate income tax changes and changes published in final form before signing (section 11.1). Taxes on generation and grid injection fall on the Seller, and taxes on offtake, transport, consumption or resale fall on the Buyer (section 17.2). New taxes follow that split and are subject to section 11 only if they meet the EUR 250,000 threshold (section 17.3). The document states no adjustment mechanism below the threshold. See also the note under the price term on the tension with Annex 2.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'Seller is Havrebakke Vind ApS and Buyer is Jutland Board & Packaging A/S, which holds no credit rating from a recognised rating agency. The Buyer''s payment obligations, including the Termination Amount, are guaranteed by its sole shareholder Jutland Industri Holding A/S under the Parent Company Guarantee in Annex 4.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; section 9.2; Annex 4 paragraphs 1-2', 'No rating trigger on the Buyer or Guarantor was found. Section 9.5 is triggered instead if the Guarantor ceases to hold the entire share capital of the Buyer or the guarantee ceases to be in force. Annex 4 paragraph 5 limits the Guarantor''s liability to the Buyer''s own liability, and no separate monetary cap is stated. The signature blocks in the document are blank lines.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'Onshore wind farm of eight turbine generators (6.0 MW each) with a total installed capacity of 48.0 MW. It is located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Only one capacity figure (48.0 MW) is given. The document makes no AC/DC distinction.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'The Supply Period is twelve years starting on the Commercial Operation Date. That date is the day the Seller notifies the Buyer that the section 3.3 conditions have been met, with a target of 1 October 2027.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; section 1.1 (Commercial Operation Date); section 3.3', 'The start date is not fixed. It moves with the actual Commercial Operation Date, which is triggered by the Seller''s notice once all eight turbines have passed commissioning and the other section 3.3 conditions are met.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and the Longstop Date is 31 March 2028. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1,750,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period; section 1.1; sections 3.4-3.6', 'Both dates extend day for day for Force Majeure or Buyer breach, up to 180 days in aggregate (3.5). The liquidated damages are the Buyer''s sole remedy for delay, except the right to terminate at the Longstop Date (3.6), where no Termination Amount is payable. Section 12.1(f) also lists failure to reach the Commercial Operation Date by the Longstop Date as a Seller Event of Default; see term 11.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'The Contract Price is EUR 54.50 per MWh, excluding VAT, from the Commercial Operation Date. 30% of the price is adjusted each 1 January from 2029 by the percentage change in the Danish consumer price index over the preceding calendar year, and 70% is fixed for the Supply Period.', 'Contract Price: EUR 54.50 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output and of Deemed Delivered Electricity from the Commercial Operation Date.', 'Annex 2 (Election Sheet), Contract Price and Indexation; Part I, Price; sections 1.1 and 7.1', 'The price figure and the indexation sit only in Annex 2. Part I and section 7.1 refer to it and state no figure themselves. Annex 2 prevails over the rest of the Agreement. The document does not say whether the 30% share compounds year on year or is indexed from the base price. No cap or floor on indexation was found.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected Annual Production is 158,000 MWh (P50) and the Minimum Annual Production is 118,500 MWh (75% of P50). If a Contract Year falls short, the Seller pays the shortfall in MWh times the amount, if positive, by which the average DK1 day-ahead price exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the sum of the Metered Output and the Deemed Delivered Electricity is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; sections 4.1 and 4.3-4.6; Annex 1; Annex 2', 'The shortfall payment is zero whenever the day-ahead price is at or below the Contract Price. The minimum is cut pro rata in the first and last Contract Year and for Force Majeure, transmission system operator-instructed reductions and Buyer breach (4.6). Deemed Delivered Electricity counts toward the minimum. Annex 1 builds 97% availability into the P50, but no separate availability guarantee was found. Section 4.3 states the Seller guarantees no quantity in any hour, day or month.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'The Seller sells electricity delivered at the Delivery Point together with all Guarantees of Origin for the Metered Output, transferred to the Buyer at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'Product: electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of the Metered Output.', 'Part I, Product and Certificates; section 8.1; sections 8.2-8.3; Guarantee of Origin definition in section 1.1', 'No separate price is stated for Guarantees of Origin: they are transferred at no additional cost, so they sit within the Contract Price. They are transferred monthly within 15 Business Days of issue. None are issued for Deemed Delivered Electricity and the Seller need not procure replacements for a shortfall (8.2). Certificates under any replacement scheme also pass to the Buyer at no extra cost (8.3).', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'The Buyer may instruct output reductions for up to 150 hours per Contract Year, with at least two hours'' notice. The electricity not generated is treated as Deemed Delivered Electricity and paid at the Contract Price. Reductions instructed by the transmission system operator are not paid by the Buyer, and any compensation from the operator belongs to the Seller.', 'The Buyer may instruct the Seller to reduce the output of the Facility for up to one hundred and fifty (150) hours per Contract Year, and the electricity that would otherwise have been generated during such hours shall be treated as Deemed Delivered Electricity and paid at the Contract Price.', 'Part I, Annex 2 (Buyer reduction of output); sections 5.4-5.6; section 1.1 (Deemed Delivered Electricity); sections 4.5-4.6', 'The cap is stated in hours (150) with no MWh cap. The Seller may refuse any instruction beyond the limit. Deemed quantities are calculated from the Facility''s mast wind data, the power curve and turbine availability (5.6). Transmission system operator reductions also lower the Minimum Annual Production (4.6). Negative prices are not addressed anywhere in the document.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'Settlement is physical, with title and risk passing at the Delivery Point, the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement; Part I, Delivery Point and Balancing; sections 4.2 and 5.1-5.2; Annex 1; Annex 2', 'Settlement is physical, so no financial reference price applies. The Seller must supply day-ahead and intraday production forecasts, but these are given without warranty (5.1). No clause allocating any imbalance cost to the Seller was found.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'Seller: a bank guarantee of EUR 2,000,000 delivered within 10 Business Days after Financial Close and kept in force until 12 months after the Commercial Operation Date. Buyer: the Parent Company Guarantee, plus a letter of credit equal to nine twelfths of Expected Annual Production times the Contract Price, delivered at least 30 days before the expected Commercial Operation Date and kept in force until 60 days after the Supply Period ends.', 'The Buyer shall deliver a letter of credit in an amount equal to nine (9) months of expected payments under this Agreement, calculated as nine twelfths of the Expected Annual Production multiplied by the Contract Price in force at the time of calculation, no later than thirty (30) days before the expected Commercial Operation Date, to remain in force until sixty (60) days after the end of the Supply Period.', 'Part I, Credit Support; sections 9.1-9.5; Annex 2; Annex 3; Annex 4', 'The letter of credit amount is recalculated each 1 January. At the initial price it works out to about EUR 6.46 million (9/12 x 158,000 MWh x EUR 54.50), a figure derived here, not stated in the document. The issuing banks must be rated at least A- (9.1, 9.2). If the Guarantor ceases to own all of the Buyer''s share capital, or the guarantee lapses, the Buyer must replace the guarantee or double the letter of credit (9.5). The Seller''s guarantee can be drawn only for unpaid amounts under sections 3.4, 3.6 or 4.5.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'Events of Default include non-payment (10 Business Days after notice), failure to deliver or replace credit support, insolvency, uncured material breach (30 days), unauthorised assignment, the Seller missing the Longstop Date or selling to a third party, and a Buyer-side Guarantor insolvency or guarantee failure. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price for Expected Annual Production over the remaining Supply Period, discounted at the Danish central bank reference rate plus 2 percentage points.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Sections 12.1-12.2; sections 13.2-13.6; section 1.1 (Reference Forward Price); Annex 2 (production profile factor 0.88)', 'The calculation is fully defined in the attached document, including the 0.88 production profile factor in Annex 2. The Reference Forward Price is set from quotes by at least three market participants chosen by the Non-Defaulting Party. The amount is payable only if it is a loss for the Non-Defaulting Party. If it is a gain, nothing is payable by either Party (13.4). It is the exclusive remedy for loss of the bargain (13.5). Sections 3.6 and 13.6 say termination at the Longstop Date carries no Termination Amount, while 12.1(f) makes the same failure an Event of Default that permits termination under 13.2 with one. The document does not say which governs.', 'correct');
INSERT INTO extractions VALUES (3, 'havrebakke-ppa-v2-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:08:48+00:00', 1, 'If a Change in Law raises a Party''s cost by more than EUR 250,000 in any Contract Year, the Parties must negotiate in good faith an adjustment, which may include the Contract Price. If none is agreed within 90 days of the notice, the affected Party may terminate on 60 days'' notice with no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Sections 11.1-11.3; sections 17.2-17.3; sections 10.1, 10.3 and 10.4', 'No cost allocation is stated in section 11 itself. For taxes, section 17.2 puts generation and injection costs on the Seller and offtake, transport, consumption and resale costs on the Buyer, and section 17.3 applies it to new taxes subject to the section 11 threshold. The document does not say who bears a below-threshold Change in Law cost other than a tax. Corporate income tax of general application and changes published in final form before the Signing Date are excluded (11.1). No payment, shortfall payment or liquidated damages accrues during Force Majeure (10.3).', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'Seller: Lichtung Offshore Wind GmbH & Co. KG (Emden), a single-purpose project company; Buyer: Rheintal Spezialchemie AG (Worms), rated BBB+ at signing. The Buyer has no guarantor; its credit support is a EUR 20,000,000 letter of credit that falls due if its rating drops below BBB- or is withdrawn.', 'On the Signing Date the Buyer holds a long-term credit rating of BBB+ from a recognised rating agency.', 'Part I, Parties; Part II, section 9.3', 'The document names no guarantor of the Buyer. The guarantor in the document is the Seller''s: Lichtung Energie Holding GmbH, Hamburg, the ultimate parent of the Seller. The Buyer''s trigger is BBB- or equivalent, one notch below the BBB+ it holds today.', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'Offshore wind farm of 300 MW installed capacity (twenty 15 MW turbines on monopile foundations) in the German North Sea, about 60 km north-west of Borkum, in the German Exclusive Economic Zone. Grid connection is through the transmission system operator''s offshore grid connection system, with 300 MW of allocated capacity.', 'The Facility is an offshore wind farm with an installed capacity of 300 MW located in the German North Sea approximately 60 km north-west of Borkum, consisting of twenty (20) wind turbine generators of 15 MW each on monopile foundations, one offshore substation and the inter-array cables, connected to the onshore transmission grid through the offshore grid connection system of the transmission system operator.', 'Part I, Facility; Annex 1, paras 2-4', 'Only one capacity figure (300 MW) is given; no separate AC and DC figures. No municipality applies because the site is offshore. The bidding zone is not stated for the Facility itself. The DE-LU zone appears in the Reference Price definition (section 1.1) and in the description of the Buyer''s production sites.', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'Fifteen years starting on the fixed Start Date of 1 January 2029 and ending on 31 December 2043. The period is not extended if commissioning is late.', 'Supply Period: fifteen (15) years commencing on the Start Date of 1 January 2029.', 'Part I, Supply Period; Part II, section 1.1 (Contract Year, Start Date)', 'The start is a calendar date, not the commissioning event. Settlement begins only from the later of the Start Date and the day after the Commissioning Date (section 4.1). Sections 4, 7 and 8 take effect only once the Conditions Precedent in section 2.1 are met. If they are not met by 30 June 2026, either Party may terminate (section 2.2).', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'Commissioning is targeted on or before the Start Date of 1 January 2029; the Facility counts as commissioned at 240 MW (80% of 300 MW). The Longstop Commissioning Date is 1 July 2029. Delay compensation is EUR 40,000 per day from the Start Date, capped at EUR 6,000,000, and after the longstop the Buyer may terminate without any Termination Amount.', 'If the Facility has not been commissioned by the Start Date, the Seller shall pay the Buyer delay compensation of EUR 40,000 for each day from the Start Date until the Facility is commissioned, up to an aggregate cap of EUR 6,000,000 (Delay Compensation).', 'Part II, sections 1.1 (Longstop Commissioning Date), 3.1(d), 3.2, 3.3, 3.4 and 4.5', 'The Start Date target is a reasonable-endeavours milestone (section 3.1). Delay compensation is the Buyer''s sole financial remedy for late commissioning. Its accrual is suspended during Force Majeure, but the longstop is not extended. Derived: EUR 6,000,000 / EUR 40,000 = 150 days, so the cap is reached about 30 May 2029, roughly a month before the longstop. In the first Contract Year the Contract Quantity is reduced for hours before settlement begins (section 4.5).', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'The Strike Price is EUR 72.00 per MWh in the first Contract Year (2029), stated in Part I (Price) and section 7.1. It rises by a fixed 2% on 1 January of each Contract Year from the second (1 January 2030), applied to the whole price: EUR 73.44 in 2030 and EUR 74.91 in 2031.', 'Strike Price: EUR 72.00 per MWh, increased by two per cent (2%) on 1 January of each Contract Year from the second Contract Year onwards.', 'Part I, Price; Part II, section 7.1', 'The escalator is a fixed 2% per year, not linked to an inflation index. The price is stated in the body of the agreement, not in an annex. The Strike Price includes the consideration for the Guarantees of Origin (section 7.1). It is a strike price settled against the Reference Price, not a price paid per MWh delivered.', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'Fixed volume, not pay-as-produced: the Contract Quantity is 1,000,000 MWh per Contract Year as a baseload profile (114.155 MWh per hour in an 8,760-hour year), independent of actual output. The Seller''s P50 estimate is about 1,280,000 MWh a year, so the Contract Quantity is about 78% of P50.', 'The Contract Quantity does not vary with the actual output of the Facility.', 'Part I, Contract Quantity; Part II, sections 4.1, 5.3, 5.5; Annex 1, para 5', 'There is no availability or production guarantee and so no remedy for underproduction: ''The Seller gives no guarantee of availability or production.'' (section 5.5). The P50 figure is an estimate, not a warranty (Annex 1). Outages do not reduce the Contract Quantity (section 5.3). The quantity is reduced only for late commissioning in the first year (section 4.5) and in proportion to capacity made unavailable by Force Majeure (section 10.4). If output is below the Contract Quantity, the Seller must buy replacement Guarantees of Origin (section 8.2).', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'The product is financial settlement of the Contract Quantity against the Reference Price, plus transfer of Guarantees of Origin equal to the Contract Quantity each Contract Year with the technology attribute ''offshore wind''. No electricity is sold or delivered, and the Guarantees of Origin have no separate price because the Strike Price includes them.', 'Product: (a) the financial settlement of the Contract Quantity against the Reference Price under section 4, and (b) the transfer to the Buyer of Guarantees of Origin in a quantity equal to the Contract Quantity under section 8.', 'Part I, Product and Certificates; Part II, sections 7.1, 8.1-8.4', 'Guarantee of Origin transfers are due within 45 days after each quarter, with the balance within 90 days after year end. A shortfall is covered by the Seller buying certificates from other German offshore wind facilities at its own cost (section 8.2). The Seller bears issuing fees and the Buyer bears cancellation fees (section 8.4). No capacity product or other attribute is mentioned in Part I or section 8.', 'wrong_value');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'Curtailment instructed by the transmission system operator does not reduce the Seller''s obligations in respect of the Contract Quantity unless it constitutes Force Majeure, and the Seller keeps any compensation the operator pays. Because the Contract Quantity is settled regardless of actual generation, curtailed energy is in effect settled as if produced.', 'The Seller''s obligations in respect of the Contract Quantity shall not be reduced by any curtailment of the Facility''s output instructed by the transmission system operator, save where such curtailment constitutes Force Majeure.', 'Part II, sections 5.4, 4.1, 4.4, 10.1, 10.2, 10.4', 'Curtailment for congestion management, redispatch, system security or market-related reasons is expressly not Force Majeure. A grid-operator instruction caused by an event that is itself Force Majeure is covered by section 10.1, and section 10.4 then reduces the Hourly Quantity in proportion to the capacity made unavailable. No cap in hours or MWh is stated, and the document gives the Buyer no right to curtail. Negative prices: no Settlement Amount is payable by either Party in a Negative Price Hour (Reference Price below zero), and Guarantees of Origin are not reduced for such hours (section 4.4).', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'Settlement is financial with no physical delivery, so no Delivery Point applies. The Reference Price is the hourly day-ahead price for the DE-LU bidding zone; the Seller is balance responsible for the Facility and bears all imbalance costs, while the Buyer balances its own consumption.', 'The Seller shall remain responsible for the balancing of the Facility and shall bear all imbalance costs.', 'Part I, Delivery Point and Balancing, Settlement; Part II, sections 1.1 (Reference Price), 4, 5.2', 'If the day-ahead operator publishes prices for periods shorter than one hour, the Reference Price is their arithmetic average. If the Reference Price source changes (section 11.4), a Replacement Reference Price is negotiated or set by an expert (section 11.5). Meanwhile the Parties settle provisionally on the price the Seller reasonably considers closest to the former one, with a later true-up (section 11.6).', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'Seller: a parent company guarantee of EUR 25,000,000 from Lichtung Energie Holding GmbH, delivered within 10 Business Days after signing and kept in force until 12 months after the end of the Supply Period (or earlier discharge of the Seller''s obligations). It is replaced by a EUR 25,000,000 letter of credit from an A- bank if the guarantor becomes insolvent, ceases to be an affiliate or disputes the guarantee. Buyer: none at signing; a EUR 20,000,000 letter of credit within 20 Business Days if its rating falls below BBB- or is withdrawn, returnable after six consecutive months back at BBB- or better.', 'Seller: parent company guarantee from Lichtung Energie Holding GmbH in the amount of EUR 25,000,000 in the form of Annex 4 (section 9.1).', 'Part I, Credit Support; Part II, sections 9.1-9.4, 2.1(c); Annexes 3 and 4', 'Delivery of the Seller''s guarantee is a Condition Precedent (section 2.1(c)). The guarantee''s liability is capped at EUR 25,000,000 and covers any Termination Amount payable by the Seller (Annex 4, paras 1-2). Under the form of letter of credit (Annex 3), expiry is not earlier than 12 months after issue and extends automatically unless the bank gives 60 days'' notice. Credit support is returned within 20 Business Days after the later of the end of the Supply Period and payment of all amounts due (section 9.4).', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 0, NULL, NULL, 'Part II, section 12.1 (Events of Default); section 13.3 and Annex 5 (Termination Amount Methodology)', 'The Termination Amount calculation is not found. Section 13.3 says ''The Termination Amount shall be calculated in accordance with Annex 5 (Termination Amount Methodology).'' and the annex list reads ''Annex 5 — Termination Amount Methodology [to be agreed prior to Financial Close]''. No Annex 5 text is attached. Section 1.2 makes Annex 5 govern the calculation, and attaching it is a Condition Precedent (section 2.1(d)). Events of Default that are stated (section 12.1) are: non-payment (10 Business Days after notice); failure to deliver, maintain or restore credit support (10 Business Days after notice); insolvency of the Party or its credit support provider; other material breach not remedied within 30 days; repudiation; Seller abandonment for 90 consecutive days; Seller failing to transfer the full Guarantees of Origin within 120 days after the Contract Year ends; and breach of the assignment or change-of-control rules. The Non-Defaulting Party terminates by notice, with an Early Termination Date 5 to 20 Business Days later (section 13.1). No Termination Amount is payable on termination under sections 2.2, 3.4, 10.5 or 11.2 (section 13.5).', 'correct');
INSERT INTO extractions VALUES (3, 'lichtung-offshore-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:10:24+00:00', 1, 'A Change in Law is borne by the Party on whom the cost or benefit falls, with no adjustment of the Strike Price or Contract Quantity and no stated threshold; only if the Product no longer exists may either Party terminate (no Termination Amount), after 90 days of good-faith renegotiation. Force Majeure continuing for more than 180 consecutive days lets either Party terminate, also with no Termination Amount.', 'Any other Change in Law, including one that changes the cost of Guarantees of Origin, grid charges or levies, is borne by the Party on whom the cost or benefit falls.', 'Part II, sections 11.1-11.3, 10.5, 17.3', 'Section 17.3 applies the same allocation to levies, caps or skimming mechanisms on generator revenues or on financial contracts: the Party on whom it is imposed bears it. Changes in taxes on income are excluded from Change in Law (section 11.1). A Change in Reference Price Source gives neither Party a termination right or a price adjustment (section 11.7); it triggers the replacement-price process in sections 11.4-11.6.', 'wrong_value');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Seller: Olivos Solar Proyecto Dos S.L. (Spain). Buyer: Meseta Energía Comercializadora S.A. (Spain), a licensed electricity trader. There is no guarantor and no parent company guarantee, and the Buyer''s obligations are supported solely by the letter of credit under section 9.2.', 'The Buyer is a licensed electricity trader and no guarantee of the Buyer''s obligations is provided by any affiliate of the Buyer.', 'Part I, Parties; section 9.6; Annex 4 (not used)', 'No rating trigger on the Buyer is stated. The only rating requirement is on the issuing bank of each credit instrument (at least A-, sections 9.1, 9.2 and 9.5). Section 9.6 also records that the Buyer''s shareholders have given no undertaking.', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Ground-mounted solar PV plant (bifacial modules on single-axis trackers) with 90 MWp DC installed capacity and 75 MW AC grid export capacity. It is at Valdeolivos, Province of Badajoz, Extremadura, Spain, connected at the 220 kV Valdeolivos substation.', 'Facility: a ground-mounted solar photovoltaic plant with an installed capacity of 90 MWp (direct current) and a grid export capacity of 75 MW (alternating current) located at Valdeolivos in the Province of Badajoz, Spain, as further described in Annex 1.', 'Part I, Facility; Annex 1, A1.1 to A1.4', 'No sentence names the bidding zone for the Facility. The document refers to day-ahead prices for "the Spanish bidding zone" in sections 7.3, 7.4 and 13.3.', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Twelve (12) years starting on the Commercial Operation Date. The start occurs when the Seller gives notice that the conditions in section 3.4 are met, including 60 MW AC exported for 72 continuous hours.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; section 1.1 (Commercial Operation Date, Contract Year); section 3.4', '', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Target Commercial Operation Date is 30 June 2027 and the Longstop Date is 31 December 2027. Delay liquidated damages are EUR 6,000 per day, capped at EUR 1,500,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 30 June 2027, the Seller shall pay the Buyer liquidated damages of EUR 6,000 for each day of delay, up to an aggregate cap of EUR 1,500,000.', 'Part I, Target Commercial Operation Date; sections 3.5, 3.6 and 3.7; section 1.1 (Longstop Date)', 'Both dates extend day for day for Force Majeure or transmission system operator delay, up to 180 days in aggregate (3.6). The delay damages are the Buyer''s sole remedy until the Longstop Date. If the Longstop Date is missed the Buyer may terminate, and no Termination Amount is payable (3.7). The milestones in 3.2 are indicative only.', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Contract Price is EUR 38.75 per MWh, fixed for the Supply Period with no indexation or escalation, so there is no indexation start date or share. The price includes Guarantees of Origin and excludes VAT. No payment is due for hours with a negative day-ahead price.', 'Contract Price: EUR 38.75 per MWh, fixed for the Supply Period without indexation.', 'Part I, Price; section 7.1; section 7.4', 'Section 7.1 allows adjustment only under sections 7.4 (negative price hours) and 17.3 (new taxes above the 3% threshold).', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output, with no minimum or maximum annual quantity. Expected Annual Production is 165,000 MWh (P50), an estimate and not a delivery obligation. The Seller guarantees 97% Availability in each Contract Year. The shortfall remedy is damages of shortfall in percentage points x 1% of Expected Annual Production x Contract Price x 50%, capped at 5% of the amount payable by the Buyer for that year, as the Buyer''s sole remedy.', 'The Buyer purchases one hundred per cent (100%) of the Metered Output during the Supply Period.', 'Part I, Contract Quantity and volume structure; sections 4.1, 4.4 and 5.6; Annex 1, A1.5 and A1.6', 'The P50 is not adjusted for module degradation (A1.5). Availability counts an hour as available at 95% or more of irradiance-adjusted capacity (section 1.1, A1.6). Planned maintenance counts as unavailability (5.4). The Buyer may have the statement verified, at the Seller''s cost if Availability was overstated by more than one percentage point.', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'The Seller sells electricity delivered at the Delivery Point together with all Guarantees of Origin for that electricity. The Guarantees of Origin are transferred at no additional cost, because they are included in the Contract Price. No capacity product, ancillary service or other attribute is sold.', 'Electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of that electricity.', 'Part I, Product; sections 7.1, 8.1 and 8.2', 'Guarantees of Origin are transferred within 30 days after issue (8.1). Negative-price hours still give rise to Guarantees of Origin (7.4).', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 0, NULL, NULL, NULL, 'The document has no curtailment provision. It does not say who may curtail the Facility, set any cap in hours or MWh, provide deemed-delivery payment for curtailed energy, or address grid-operator curtailment. Related provisions that are not curtailment clauses: under section 7.4 no payment is due for any hour with a negative day-ahead price, although the output is still delivered and gives Guarantees of Origin. Under section 10.4 no payment is due for electricity not delivered because of Force Majeure, which includes failure of the transmission grid beyond the Delivery Point (10.1). Availability excludes hours of grid-connection unavailability not caused by the Seller (section 1.1).', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Physical settlement at the 220 kV connection point at the Valdeolivos substation, where title and risk pass to the Buyer. The Buyer is the market representative and balance responsible party from the Commercial Operation Date and bears all imbalance costs.', 'The Buyer shall act as the market representative of the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; sections 4.3, 5.2 and 5.3; Annex 1, A1.4', 'No reference price is needed because settlement is physical. The Seller bears imbalance costs only where the imbalance results from its failure to notify an outage under 5.4 or 5.5 (5.3). Section 3.3 has the Buyer act as market representative for pre-COD test electricity, while 5.2 places imbalance costs on the Buyer only from the Commercial Operation Date.', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Seller: EUR 1,200,000 on-demand performance bond from a bank rated at least A-, delivered within 10 Business Days after the Signing Date and held until the Commercial Operation Date. Buyer: standby letter of credit for three months of expected payments, EUR 1,598,437.50 at signing, delivered at least 10 Business Days before the expected Commercial Operation Date and maintained until 60 days after the end of the Supply Period.', 'Seller: performance bond of EUR 1,200,000 from the Signing Date until the Commercial Operation Date (Annex 2). Buyer: letter of credit equal to three (3) months of expected payments under this Agreement (Annex 3), from the Commercial Operation Date until the end of the Supply Period.', 'Part I, Credit Support; sections 9.1 to 9.6; Annex 2; Annex 3', 'The Buyer''s letter of credit may have a one-year term with replacement at least 30 days before expiry, failing which the Seller may draw it in full (9.3). The Buyer must restore it within 10 Business Days after each drawing (9.4). The bond form in Annex 2 expires at the latest on 30 June 2028. The amount in the Annex 3 form is left blank. Part I says the Buyer''s letter of credit runs from the Commercial Operation Date, while section 9.2 requires delivery 10 Business Days before the expected date.', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'Events of Default include non-payment (10 Business Days after notice), failure to deliver or restore credit support, an Insolvency Event, uncured material breach (30 days, or up to 90 days), and party-specific events. For the Seller these are an unlawful third-party sale and permit revocation unreinstated for 90 days. For the Buyer they are loss of its trader licence or registration unreinstated for 30 days and revocation of its powers of representation. The Termination Amount is the replacement value, set by an independent expert, of the difference between the Contract Price and the forward price over the remaining Supply Period, applied to Expected Annual Production and discounted at the Interest Rate.', 'The expert shall determine, under section 20.3, the present value at the Interest Rate of the difference between the Contract Price and the forward price for the Spanish bidding zone at the early termination date, evidenced by quotations from at least two (2) market participants, applied to the Expected Annual Production over the remainder of the Supply Period.', 'Sections 12.1, 13.1 to 13.4, 20.3; section 1.1 (Interest Rate)', 'The calculation is fully set out in the document, not referenced to an unattached schedule. The Interest Rate is the ECB main refinancing rate plus 4 percentage points. A negative Termination Amount means nothing is payable by either Party (13.2). The document does not state which price is subtracted from which. The Defaulting Party bears the expert''s costs. No Termination Amount is payable on termination under 2.3, 3.7 or 10.5. A lender may suspend early termination for a Seller default for up to 120 days (16.4).', 'correct');
INSERT INTO extractions VALUES (3, 'olivos-solar-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:11:48+00:00', 1, 'The allocation sits in section 17 (Taxes, Levies and Regulatory Costs). The Seller bears any new tax, levy or charge on generation or sale unless it exceeds 3% of the Seller''s revenue in the Contract Year, in which case the Parties meet to agree an equitable adjustment, limited to the part above 3%. Either Party may terminate on 30 days'' notice if Force Majeure continues for more than 180 consecutive days.', 'Should any law, regulation or administrative decision enacted after the Signing Date impose a new tax, levy or charge on the generation or sale of electricity from the Facility, the Seller shall bear such cost unless it exceeds three per cent (3%) of the Seller''s revenue under this Agreement in the relevant Contract Year, in which case the Parties shall meet to agree an equitable adjustment.', 'Sections 17.1, 17.3 to 17.5; sections 10.1 to 10.5', 'If no adjustment is agreed within 90 days, either Party may refer the matter to the expert procedure in 20.3. Benefits of any abolished or reduced generation-side charge stay with the Seller, and new Buyer-side charges are borne by the Buyer (17.4). Corporate income tax and penalties are excluded (17.5). The document has no general change-in-law clause beyond section 17. Force Majeure termination requires the event to still be continuing at the end of the notice period, and no Termination Amount is payable (10.5).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'The Buyer is Jutland Board & Packaging A/S, which is unrated. Jutland Industri Holding A/S gives a parent guarantee for the Buyer.', 'Buyer Jutland Board & Packaging A/S, unrated; parent guarantee from Jutland Industri Holding A/S', 'Section 4.2, key terms table, row 1', 'The Seller is not named in the document. The guarantee amount, duration and any rating trigger are not stated. The table is a legal due diligence summary and model summary, not the contract itself.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'Onshore wind farm (Havrebakke Wind Farm) with 8 turbines and 48.0 MW installed capacity, in Ringkøbing-Skjern, Denmark, bidding zone DK1.', '8 turbines, 48.0 MW, Ringkøbing-Skjern, DK1', 'Section 4.2, key terms table, row 2; project header line', 'Only one capacity figure is given, with no AC/DC split. Technology (wind, onshore) comes from the project header line.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'The supply period is 10 years, starting from the commercial operation date (COD).', '10 years from COD', 'Section 4.2, key terms table, row 3', 'The summary does not say how COD is defined or achieved.', 'faithful');
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'Target COD is 1 October 2027 and the longstop date is 31 March 2028. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1.75m.', 'Target COD 1 Oct 2027; longstop 31 Mar 2028; LDs EUR 9,600/day, cap EUR 1.75m', 'Section 4.2, key terms table, row 4', 'The consequence of passing the longstop date is not stated.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'The price is EUR 54.50/MWh. 30 % of it is CPI-indexed from 2029.', 'EUR 54.50/MWh; 30 % CPI-indexed from 2029', 'Section 4.2, key terms table, row 5; modelling note below the table', 'The indexation start is given only as a year. The CPI index and base date are not stated. The modelling note says the base case runs the contract price for ten years and merchant DK1 forward prices after that.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'Pay-as-produced, covering 100 % of output. Expected annual production (P50) is 158 GWh/yr, with a minimum of 118.5 GWh/yr.', 'Pay-as-produced, 100 % of output; P50 158 GWh/yr; minimum 118.5 GWh/yr', 'Section 4.2, key terms table, row 6', 'The remedy if the 118.5 GWh/yr minimum is missed is not stated. It is also not stated whether the minimum is a production guarantee or an availability guarantee.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'The Buyer takes the electricity and all guarantees of origin (GoOs).', 'Electricity + all GoOs to buyer', 'Section 4.2, key terms table, row 7', 'No GoO price or cost is stated. Capacity or other attributes are not addressed.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'The Buyer may curtail for up to 150 hours per year and is compensated at the contract price. Curtailment ordered by the TSO is not compensated.', 'Buyer right 150 h/yr, compensated at contract price; TSO curtailment uncompensated', 'Section 4.2, key terms table, row 8', 'The document does not use the words ''deemed delivered''; it says only ''compensated at contract price''. Treatment of negative prices is not addressed.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'Physical settlement at the 60 kV Havrebakke substation. The Buyer is the balance responsible party (BRP) and bears imbalance costs.', 'Physical, 60 kV Havrebakke substation; buyer is BRP and bears imbalance', 'Section 4.2, key terms table, row 9', '', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'The Seller provides a bank guarantee of EUR 2,500,000, running to COD plus 12 months. The Buyer provides a letter of credit (LC) of 9 months of payments.', 'Seller bank guarantee EUR 2,500,000 to COD + 12 months; buyer LC 9 months of payments', 'Section 4.2, key terms table, row 10', 'The Buyer LC is given as 9 months of payments, with no EUR amount and no duration. The Buyer parent guarantee in row 1 is a separate instrument.', 'faithful');
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'The termination amount is calculated mark-to-market against the forward curve for the remaining term.', 'Mark-to-market vs forward curve for remaining term', 'Section 4.2, key terms table, row 11', 'Partial: the events of default are not listed anywhere in the document. The termination amount is described only in summary form, with no payer, discounting or curve source. The document is a summary, not the contract.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ic-key-terms', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:12:22+00:00', 1, 'Above EUR 250k per year the parties renegotiate. If renegotiation fails, either party may terminate, with no termination amount. A force majeure event lasting more than 180 days gives a termination right.', 'Renegotiation above EUR 250k/yr, then mutual termination right without termination amount; FM > 180 days termination right', 'Section 4.2, key terms table, row 12', 'Who bears change-in-law cost below the EUR 250k/yr threshold is not stated. It is also not stated what the threshold measures, or who may exercise the force majeure termination right.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'Seller is Havrebakke Vind ApS. Buyer is Jutland Board & Packaging A/S, which is unrated. The Buyer''s payment obligations are guaranteed by its parent, Jutland Industri Holding A/S, through a parent company guarantee in Annex 4. The Buyer also posts a letter of credit (see credit support).', 'Seller: Havrebakke Vind ApS. Buyer: Jutland Board & Packaging A/S, unrated. Payment obligations guaranteed by Jutland Industri Holding A/S.', 'Part I; Part II 9.2; Annex 4 (as cited in the due diligence summary, section 2)', 'This is a lawyers'' summary, not the PPA. No rating trigger is mentioned, and the Buyer is unrated. The summary says the parent guarantee is the credit the committee relies on.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'Onshore wind farm of eight turbines with 48.0 MW capacity at Havrebakke, Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'Eight onshore turbines, 48.0 MW, Havrebakke, Ringkøbing-Skjern Municipality, DK1.', 'Part I; Annex 1', 'The summary gives one capacity figure and does not say whether it is AC or DC.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'The Supply Period is ten years and starts on the Commercial Operation Date. The Target COD is 1 October 2027.', 'The Supply Period runs ten (10) years from the Commercial Operation Date.', 'Part I', '', 'faithful');
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'Target COD is 1 October 2027 and the Longstop Date is 31 March 2028. Delay damages are EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Target COD 1 October 2027. Longstop Date 31 March 2028. Delay damages EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Part II 3', 'Failure to reach COD by the Longstop Date is an Event of Default (Part II 12–13).', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'The Contract Price is EUR 54.50 per MWh, stated in the Election Sheet (Annex 2). Thirty per cent of the price is adjusted annually from 1 January 2029 by the Danish consumer price index.', 'EUR 54.50 per MWh per the Election Sheet. Thirty per cent of the price is adjusted annually from 1 January 2029 by the Danish consumer price index.', 'Part II 7.1; Annex 2 (Election Sheet)', 'The figure is taken from the lawyers'' summary of the Election Sheet. The Election Sheet itself is not attached.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'Pay-as-produced: 100 % of Metered Output. Expected Annual Production is 158,000 MWh (P50). Minimum Annual Production is 118,500 MWh, with a shortfall payment as the remedy.', '100 % of Metered Output. Expected Annual Production 158,000 MWh (P50). Minimum Annual Production 118,500 MWh with a shortfall payment.', 'Part I; Part II 4', 'The summary does not say how the shortfall payment is calculated. The summary calls the agreement a pay-as-produced physical PPA.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'The Seller sells electricity and all Guarantees of Origin, which are transferred at no additional cost. There is no capacity product.', 'Electricity and all Guarantees of Origin, transferred at no additional cost. No capacity product.', 'Part II 8', 'No GO volume is stated. The summary says all GOs are transferred.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'The Buyer may instruct reductions for up to 150 hours per Contract Year. These are paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer. The summary notes the Seller has no equivalent curtailment right.', 'Buyer may instruct reductions for up to 150 hours per Contract Year, paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer.', 'Part II 5.4–5.5', 'The cap is stated in hours only, with no MWh cap. Treatment of negative prices is not addressed in the summary. It does not say whether TSO-curtailed energy counts as deemed delivered, only that the Buyer does not compensate it.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'Physical delivery at the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Physical delivery at the metering point on the 60 kV side of the Havrebakke substation. Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Part I; Part II 4.2, 5.2', 'Settlement is physical, so no financial reference price applies.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'Seller: bank guarantee of EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Seller: bank guarantee EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Part II 9', 'The Buyer''s letter of credit is sized as nine months of expected payments, with no EUR amount given. The duration of the Buyer''s parent guarantee and letter of credit is not stated in the summary.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'Events of Default include non-payment within ten Business Days of notice, insolvency, and failure to reach COD by the Longstop Date. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Non-payment within ten Business Days of notice, insolvency and failure to reach COD by the Longstop Date are Events of Default. Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Part II 12–13', 'The formula is described in the summary. The summary does not name the forward curve source for the Reference Forward Price. It says only that the PPA names a published DK1 forward curve. The discount rate and which party pays are not stated. The list of Events of Default is not shown as complete.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-legal-dd-summary', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:12:58+00:00', 1, 'A cost impact from Change in Law above EUR 250,000 in a Contract Year triggers good-faith renegotiation. If there is no agreement within 90 days, the affected Party may terminate without a Termination Amount. Force majeure lasting more than 180 consecutive days gives either Party a termination right.', 'A cost impact above EUR 250,000 in a Contract Year triggers good-faith renegotiation; absent agreement within 90 days the affected Party may terminate without a Termination Amount.', 'Part II 11 (change in law); Part II 10 (force majeure)', 'The summary does not say which party bears change-in-law cost below the EUR 250,000 threshold. It calls the termination right mutual and says lenders are expected to ask for it to be tightened.', NULL);
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Seller is Havrebakke Vind ApS and Buyer is Jutland Board & Packaging A/S, both Danish companies. The Buyer''s payment obligations are guaranteed by Jutland Industri Holding A/S under a Parent Company Guarantee (Annex 4). The Buyer has no credit rating from a recognised agency. There is no rating trigger. The replacement trigger in section 9.5 applies if the Guarantor ceases to hold all of the Buyer''s share capital or the guarantee ceases to be in force.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; Annex 4; sections 9.2 and 9.5', 'The document is a draft, subject to contract and not binding until signed. Annex 4 is an unsigned form with the date left blank. Its liability is capped only at the Buyer''s own liability (Annex 4, para 5).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Onshore wind farm of eight turbines (6.0 MW each) with total installed capacity of 48.0 MW. It is located at Havrebakke, Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Only one capacity figure is given. There is no AC/DC split, which is not relevant for wind.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Ten years, starting on the Commercial Operation Date. The Commercial Operation Date is the date the Seller notifies the Buyer that the section 3.3 conditions are met (all eight turbines commissioned, grid connected at the Delivery Point, meters verified, registrations done).', 'Supply Period: ten (10) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; section 1.1 (Commercial Operation Date); section 3.3', 'The start is triggered by the Seller''s own notice. The Buyer is given at least 30 days'' notice of the expected date.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and Longstop Date is 31 December 2027. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1,750,000 in aggregate. Both dates extend day for day for Force Majeure or Buyer breach, up to 180 days in aggregate. If the Longstop Date passes, the Buyer may terminate with no Termination Amount. The Seller pays accrued unpaid liquidated damages.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period; section 1.1 (Longstop Date); sections 3.4 to 3.6', 'Calculated from the stated figures, not stated in the document: the window from target to longstop is 91 days, which is about EUR 873,600 of liquidated damages. The cap equals roughly 182 days of delay, so it cannot be reached before the Longstop Date. The Buyer''s termination right under 3.6 arises at the Longstop Date, as extended under 3.5.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Fixed price of EUR 58.00 per MWh, exclusive of VAT, for each MWh of Metered Output from the Commercial Operation Date. There is no indexation and the price is fixed for the whole Supply Period.', 'Contract Price: EUR 58.00 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output from the Commercial Operation Date.', 'Annex 2 (Election Sheet), referred to by Part I, Price and section 7.1', 'The price sits only in Annex 2, not in Part I or the body. The indexation statement is also in Annex 2: ''Indexation: none. The Contract Price is fixed for the Supply Period and shall not be indexed.'' Section 11.2 allows a Change in Law price adjustment by negotiation. See term 12 for how that fits with Annex 2 being the exclusive source of price adjustment.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected Annual Production is 158,000 MWh (P50). The Minimum Annual Production guarantee is 118,500 MWh (75% of P50). If output falls short in a Contract Year, the Seller pays shortfall MWh times the positive excess of the average DK1 day-ahead price over the Contract Price, capped at EUR 500,000 per Contract Year. The minimum is reduced pro rata in the first and last Contract Year and for Force Majeure, TSO-instructed reductions and Buyer breach.', 'If in any Contract Year the Metered Output is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; Annex 1; Annex 2; sections 4.1, 4.3, 4.5, 4.6', 'The remedy is a price-based payment and is nil in years when the day-ahead price is at or below EUR 58.00. The Seller gives no guarantee for any hour, day or month (4.3).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'The Seller sells electricity delivered at the Delivery Point together with all Guarantees of Origin for the Metered Output. The Guarantees of Origin are transferred at no additional cost, monthly, within 15 Business Days after issue. Certificates under a replacement scheme are also transferred at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'All Guarantees of Origin issued in respect of the Metered Output shall be transferred to the Buyer at no additional cost.', 'Part I, Product and Certificates; section 8', 'The Seller has no obligation to procure replacement Guarantees of Origin for a production shortfall (8.2).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'The only curtailment addressed is output reductions instructed by the transmission system operator. These give rise to no payment by the Buyer, so curtailed energy is not paid as deemed delivery. Any compensation paid by the TSO belongs to the Seller. TSO-instructed reductions (and Force Majeure and Buyer breach) reduce the Minimum Annual Production for the shortfall test, using the deemed quantity calculation in 5.5.', 'Reductions of output instructed by the transmission system operator shall not give rise to any payment by the Buyer.', 'Sections 5.4, 5.5 and 4.6', 'The document has no provision on curtailment by the Buyer, no cap in hours or MWh, and no treatment of negative prices (I read the full document for these). Deemed quantities are used only to adjust the minimum production test, not to pay the Seller.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Physical settlement. The Delivery Point is the metering point on the 60 kV side of the Havrebakke substation, where title and risk pass to the Buyer. The Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date. No financial reference price applies because settlement is physical.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; Annex 2; sections 4.2 and 5.2', 'The Seller must supply day-ahead and intraday forecasts to the balance responsible party, without warranty (5.1).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Seller: bank guarantee of EUR 2,000,000 from a bank rated at least A-, delivered within 10 Business Days after Financial Close and valid until 12 months after the Commercial Operation Date. Buyer: the Parent Company Guarantee plus a standby letter of credit from a bank rated at least A-, sized at six months of expected payments (six twelfths of Expected Annual Production times the Contract Price). It is delivered at least 30 days before the expected Commercial Operation Date, valid until 60 days after the end of the Supply Period, and recalculated each 1 January.', 'The Seller shall deliver a bank guarantee in the amount of EUR 2,000,000 within ten (10) Business Days after Financial Close, to remain in force until twelve (12) months after the Commercial Operation Date.', 'Part I, Credit Support; section 9; Annexes 3 and 4', 'The Buyer letter of credit has no stated figure. Calculated from the formula at EUR 58.00 and 158,000 MWh, it is about EUR 4.58 million. Section 9.5 requires a replacement guarantee or double the letter of credit if the Guarantor ceases to own the Buyer or the guarantee lapses.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Events of default: non-payment (10 Business Days after notice); failure to deliver, restore or replace credit support (10 Business Days); insolvency; uncured material breach (30 days); breach of the assignment rules; for the Seller, no Commercial Operation Date by the Longstop Date or sale to a third party; for the Buyer, Guarantor insolvency or the guarantee ceasing to be valid. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remainder of the Supply Period for Expected Annual Production. It is discounted at the central bank reference rate plus 2 percentage points and determined by the Non-Defaulting Party. It is payable only if it is a loss for the Non-Defaulting Party.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Sections 12.1, 13.2 to 13.6; Reference Forward Price in section 1.1; production profile factor 0.88 in Annex 2', 'The calculation is fully defined in the attached document. The Reference Forward Price uses quotes from at least three market participants chosen by the Non-Defaulting Party, scaled by the 0.88 factor. The Termination Amount is excluded from the EUR 2,000,000 annual liability cap (14.2) and is covered by the Parent Company Guarantee.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v1-draft', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:14:00+00:00', 1, 'Change in Law is cost-neutral to neither party by default. Taxes and charges on generation and injection are borne by the Seller, and those on offtake and resale by the Buyer; a new levy follows this split and is subject to section 11 above the threshold. If a Change in Law raises a Party''s cost by more than EUR 250,000 in a Contract Year, the Parties negotiate in good faith an adjustment, which may include the Contract Price. If no adjustment is agreed within 90 days of notice, the affected Party may terminate with 60 days'' effect and no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate with 30 days'' effect and no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Sections 11.1 to 11.3, 17.2, 17.3 and 10.4', 'Allocation of tax costs sits in section 17, not under the Change in Law heading. Possible conflict in the draft: Part I (Price) and section 7.1 say any price adjustment is governed exclusively by Annex 2, and Annex 2 prevails but contains no Change in Law mechanism, while 11.2 contemplates a price adjustment.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'Seller is Havrebakke Vind ApS and Buyer is Jutland Board & Packaging A/S, both Danish companies. The Buyer''s payment obligations are guaranteed by its parent Jutland Industri Holding A/S under the Parent Company Guarantee in Annex 4.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; section 9.2; Annex 4', 'Part I states that the Buyer holds no credit rating from a recognised rating agency, so its credit standing rests on the guarantee and the Buyer letter of credit (section 9.2). The only trigger is a change-of-control and guarantee-lapse trigger in section 9.5: the Buyer must deliver a replacement guarantee or double the letter of credit within 20 Business Days. There is no rating trigger, and no rating or financial data for the Guarantor is given. Annex 4 para 5 caps the Guarantor''s liability at the Buyer''s own liability under the Agreement.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'Onshore wind farm of eight turbine generators (6.0 MW each) with a total installed capacity of 48.0 MW. It is at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Only one capacity figure (48.0 MW) is given; no AC/DC distinction is stated.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'The Supply Period is twelve years, starting on the Commercial Operation Date. Commercial Operation Date is the date the Seller notifies that the section 3.3 conditions are met.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; section 1.1 (Commercial Operation Date); section 3.3', 'The start is an event (Seller notice that all eight turbines have passed commissioning tests, grid connection and metering are in place, and registrations are complete), not a fixed calendar date. The Target Commercial Operation Date is 1 October 2027.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and the Longstop Date is 31 March 2028. Delay liquidated damages are EUR 9,600 per day of delay, capped at EUR 1,750,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period; sections 3.4, 3.5, 3.6; section 1.1', 'Both dates are extended day for day for Force Majeure or Buyer breach, up to 180 days in aggregate (section 3.5). Liquidated damages are the Buyer''s sole remedy for delay except the right to terminate after the Longstop Date, with no Termination Amount (sections 3.4, 3.6). Section 12.1(f) also lists failure to reach the Commercial Operation Date by the Longstop Date as a Seller Event of Default, and the document does not say how this interacts with the no-Termination-Amount wording of sections 3.6 and 13.6.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'The Contract Price is EUR 54.50 per MWh, exclusive of VAT, from the Commercial Operation Date. 30% of the price is adjusted each 1 January from 2029 by the change in the Danish consumer price index, and the other 70% is fixed for the Supply Period.', 'Contract Price: EUR 54.50 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output and of Deemed Delivered Electricity from the Commercial Operation Date.', 'Annex 2 (Election Sheet); referenced from Part I, Price and section 7.1', 'The price is not in the Part I body, which refers to Annex 2; Annex 2 prevails on the matters it addresses. Indexation sentence in Annex 2: "Thirty per cent (30%) of the Contract Price shall be adjusted on 1 January of each Contract Year from 2029 by the percentage change in the Danish consumer price index over the preceding calendar year." The Seller notifies the adjusted price within 10 Business Days after the December index is published.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected Annual Production is 158,000 MWh (P50) and Minimum Annual Production is 118,500 MWh. If a Contract Year falls short, the Seller pays the shortfall in MWh times the amount by which the average DK1 day-ahead price exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the sum of the Metered Output and the Deemed Delivered Electricity is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; sections 4.1, 4.3, 4.5, 4.6; Annex 1', 'The Minimum Annual Production corresponds to 75% of the P50 (Annex 1). It is reduced pro rata in the first and last Contract Year (section 4.5) and further reduced for Force Majeure, Transmission System Operator-instructed reductions and Buyer breach (section 4.6). The shortfall payment is zero when the day-ahead price does not exceed the Contract Price. The Seller does not guarantee any quantity in any hour, day or month (section 4.3).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'The Seller sells electricity delivered at the Delivery Point together with all Guarantees of Origin for the Metered Output, transferred to the Buyer at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'Product: electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of the Metered Output.', 'Part I, Product and Certificates; sections 8.1 to 8.3', 'Guarantees of Origin are transferred monthly within 15 Business Days after issue. None are issued for Deemed Delivered Electricity, and the Seller need not procure replacement certificates for any shortfall (section 8.2). If the scheme is replaced, certificates under the replacement scheme go to the Buyer at no additional cost (section 8.3).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'The Buyer may instruct output reductions for up to 150 hours per Contract Year, paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator carry no payment from the Buyer, and any compensation from the operator belongs to the Seller.', 'The Buyer may instruct the Seller to reduce the output of the Facility for up to one hundred and fifty (150) hours per Contract Year, and the electricity that would otherwise have been generated during such hours shall be treated as Deemed Delivered Electricity and paid at the Contract Price.', 'Part II, sections 5.4, 5.5, 5.6; Annex 2', 'Buyer instructions need at least two hours'' notice and the Seller may refuse any instruction beyond the 150-hour limit (section 5.4). Deemed quantities are calculated from mast wind data, the turbine power curve, turbine availability and electrical losses (section 5.6). Transmission System Operator-instructed reductions also reduce the Minimum Annual Production (section 4.6). Negative prices are not addressed anywhere in the document (searched for "negative" and for any price-based curtailment rule).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'Settlement is physical. The Delivery Point is the metering point on the 60 kV side of the Havrebakke substation, and the Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; section 5.2; Annex 2', 'Because settlement is physical, no financial reference price applies. Title and risk pass to the Buyer at the Delivery Point (section 4.2). The Seller provides day-ahead and intraday production forecasts to the balance responsible party, without warranty (section 5.1).', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'Seller: bank guarantee of EUR 2,000,000, due within 10 Business Days after Financial Close and held until 12 months after the Commercial Operation Date, from a bank rated at least A-. Buyer: the Parent Company Guarantee (Annex 4) plus a letter of credit for nine months of expected payments, due 30 days before the expected Commercial Operation Date and held until 60 days after the end of the Supply Period.', 'The Seller shall deliver a bank guarantee in the amount of EUR 2,000,000 within ten (10) Business Days after Financial Close, to remain in force until twelve (12) months after the Commercial Operation Date.', 'Part I, Credit Support; sections 9.1 to 9.5; Annex 2; Annex 3; Annex 4', 'The Buyer letter of credit is nine twelfths of the Expected Annual Production times the Contract Price in force, from an A- bank, recalculated each 1 January (section 9.2). The document gives the formula but no euro amount; at EUR 54.50 and 158,000 MWh it gives about EUR 6.46 million (computed here, not stated in the document). The Buyer may draw the Seller guarantee for unpaid amounts under sections 3.4, 3.6 or 4.5 (section 9.1). After the Seller guarantee expires 12 months after the Commercial Operation Date, the document states no further Seller credit support.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'Events of Default (section 12.1) include non-payment after 10 Business Days'' notice, failure to deliver, restore or replace credit support, insolvency, unremedied material breach after 30 days, and Seller failure to reach the Commercial Operation Date by the Longstop Date. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period, discounted at the Danish central bank reference rate plus 2 percentage points.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Part II, sections 12.1, 13.2 to 13.6; section 1.1 (Reference Forward Price); Annex 2', 'The calculation is fully specified in attached provisions: the Reference Forward Price is defined in section 1.1 and its production profile factor of 0.88 is in Annex 2. Payment runs only one way: if the amount is a gain for the Non-Defaulting Party, no Termination Amount is payable by either Party (section 13.4). Termination under sections 2.3, 3.6, 10.4 or 11.3 carries no Termination Amount (section 13.6). The overlap between section 12.1(f) and section 3.6 on a Longstop Date failure is not resolved in the document.', 'correct');
INSERT INTO extractions VALUES (4, 'havrebakke-ppa-v2-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:15:24+00:00', 1, 'If a Change in Law raises a Party''s cost by more than EUR 250,000 in a Contract Year, the Parties negotiate an adjustment that may include the Contract Price. If none is agreed within 90 days, the affected Party may terminate on 60 days'' notice with no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice, also with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Part II, sections 11.1 to 11.3; section 17.2 and 17.3 (taxes and regulatory costs); section 10.4 (force majeure termination)', 'The threshold applies to either Party, so the right is symmetric. Change in Law excludes general corporate income tax changes and changes published in final form before the Signing Date (section 11.1). Cost allocation sits in section 17: the Seller bears taxes and charges on generation and injection into the grid, the Buyer bears those on offtake, transport, consumption or resale, and new taxes are allocated the same way and are subject to section 11 where the EUR 250,000 threshold is met (sections 17.2, 17.3). Force Majeure excludes lack of funds, market price changes and insufficient wind (section 10.1).', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'Seller is Lichtung Offshore Wind GmbH & Co. KG (Emden, Germany), a single-purpose project company. Buyer is Rheintal Spezialchemie AG (Worms, Germany), rated BBB+ on the Signing Date. No guarantor of the Buyer is named; its credit standing is covered by a rating trigger that requires a EUR 20,000,000 letter of credit if its rating falls below BBB-.', 'On the Signing Date the Buyer holds a long-term credit rating of BBB+ from a recognised rating agency.', 'Part I, Parties and Credit Support; Part II s. 9.3', 'The only guarantor named in the document is the Seller''s (Lichtung Energie Holding GmbH). The rating trigger instrument is the Buyer Letter of Credit in s. 9.3.', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'Offshore wind farm with 300 MW installed capacity, made up of 20 turbines of 15 MW each on monopile foundations. It lies in the German North Sea about 60 km north-west of Borkum and is connected through the transmission system operator''s offshore grid connection system.', 'The Facility is an offshore wind farm with an installed capacity of 300 MW located in the German North Sea approximately 60 km north-west of Borkum, consisting of twenty (20) wind turbine generators of 15 MW each on monopile foundations, one offshore substation and the inter-array cables, connected to the onshore transmission grid through the offshore grid connection system of the transmission system operator.', 'Part I, Facility; Part II s. 1.1 (Installed Capacity); Annex 1 items 2-4', 'Only one capacity figure (300 MW) is given; there is no AC/DC split. The Facility''s own bidding zone is not stated. DE-LU is named only as the zone of the Reference Price and of the Buyer''s production sites. Annex 1 places the site in the German Exclusive Economic Zone, so no municipality applies.', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'Fifteen years from the Start Date of 1 January 2029, ending 31 December 2043. The period is fixed to the calendar and does not move if commissioning is late.', 'Supply Period: fifteen (15) years commencing on the Start Date of 1 January 2029.', 'Part I, Supply Period; Part II s. 1.1 (Contract Year, Start Date), s. 4.1', 'Settlement starts at the later of the Start Date and 00:00 on the day after the Commissioning Date (s. 4.1). A late start therefore shortens the settled period but not the Supply Period.', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'Target commissioning is on or before the Start Date, 1 January 2029, and the Longstop Commissioning Date is 1 July 2029. Delay compensation is EUR 40,000 per day from the Start Date, capped at EUR 6,000,000 in aggregate.', 'If the Facility has not been commissioned by the Start Date, the Seller shall pay the Buyer delay compensation of EUR 40,000 for each day from the Start Date until the Facility is commissioned, up to an aggregate cap of EUR 6,000,000 (Delay Compensation).', 'Part II s. 3.1(d), 3.2, 3.3, 3.4; s. 1.1 (Longstop Commissioning Date)', 'The target date is a reasonable-endeavours milestone (s. 3.1). Commissioning means at least 240 MW (80% of 300 MW) has passed take-over tests and can export (s. 3.2). Delay compensation is the Buyer''s sole financial remedy for lateness. It is suspended during Force Majeure, but the longstop is not extended. After the longstop the Buyer may terminate with no Termination Amount (s. 3.4). By simple arithmetic, which the document does not state, the EUR 6,000,000 cap is reached after 150 days, about a month before the 181 days to the longstop.', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'The Strike Price is EUR 72.00 per MWh in the first Contract Year (2029). From 1 January 2030 it rises 2% each year on the previous year''s price, for example EUR 73.44 in 2030 and EUR 74.91 in 2031.', 'Strike Price: EUR 72.00 per MWh, increased by two per cent (2%) on 1 January of each Contract Year from the second Contract Year onwards.', 'Part I, Price; Part II s. 7.1', 'The price is stated in the body (Part I and s. 7.1), not in an annex or election sheet. The 2% applies to the whole Strike Price and compounds, with rounding to two decimals. The Strike Price includes the consideration for the Guarantees of Origin (s. 7.1). Because settlement is financial, the cash flow is Strike Price minus Reference Price, not a payment of the Strike Price itself.', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'Fixed baseload volume of 1,000,000 MWh per Contract Year, settled in equal hourly quantities regardless of actual output. The Seller''s P50 estimate is about 1,280,000 MWh a year, so the Contract Quantity is roughly 78% of it. There is no availability or production guarantee and so no remedy for underproduction.', 'Contract Quantity: 1,000,000 MWh per Contract Year, delivered as a baseload profile in equal hourly quantities.', 'Part I, Contract Quantity; Part II s. 4.1, 5.3, 5.5, 10.4; Annex 1 item 5', 'Section 5.5 states: ''The Seller gives no guarantee of availability or production.'' The P50 estimate ''is not a warranty'' (Annex 1). Outages do not reduce the Contract Quantity (s. 5.3). The Contract Quantity is reduced only for the first Contract Year if commissioning is late (s. 4.5) and pro rata for Force Majeure-unavailable capacity (s. 10.4). A shortfall in generation affects only the Guarantees of Origin, which the Seller covers by buying replacements (s. 8.2).', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'The product is the financial settlement of the Contract Quantity against the Reference Price, plus the transfer of Guarantees of Origin equal to the Contract Quantity (1,000,000 per Contract Year). No electricity is sold or delivered. The cost of the Guarantees of Origin is included in the Strike Price.', 'Product: (a) the financial settlement of the Contract Quantity against the Reference Price under section 4, and (b) the transfer to the Buyer of Guarantees of Origin in a quantity equal to the Contract Quantity under section 8.', 'Part I, Product and Certificates; Part II s. 4.6, 7.1, 8.1-8.4', 'The Guarantees of Origin carry the ''offshore wind'' technology attribute. The Seller buys replacements for any generation shortfall at its own cost (s. 8.2). The Seller bears issuing fees and the Buyer bears cancellation fees (s. 8.4). The Seller must sell the physical output without a statutory market premium so that the certificates can be issued (s. 4.6). No capacity product or other attribute is sold.', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'Curtailment is addressed only for the transmission system operator: it does not reduce the Contract Quantity unless it is Force Majeure, and curtailment for congestion management, redispatch, system security or market reasons is expressly not Force Majeure. The operator''s compensation belongs to the Seller. In hours with a negative Reference Price no Settlement Amount is payable by either Party.', 'The Seller''s obligations in respect of the Contract Quantity shall not be reduced by any curtailment of the Facility''s output instructed by the transmission system operator, save where such curtailment constitutes Force Majeure.', 'Part II s. 5.4, 4.4, 4.1, 10.1, 10.2, 10.4', 'The term ''deemed delivered'' is not used. The same effect comes from settling the fixed Contract Quantity regardless of generation (s. 4.1). Hours of Force Majeure-caused unavailability reduce the Hourly Quantity pro rata (s. 10.4). There is no cap in hours or MWh. The document gives the Buyer no right to curtail and does not address Seller-initiated curtailment at negative prices. Negative Price Hours do not reduce the Guarantees of Origin due (s. 4.4).', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'Financial settlement with no physical delivery and no Delivery Point. Settlement is against the hourly day-ahead price for the DE-LU bidding zone. The Seller remains balance responsible for the Facility and bears all imbalance costs, and the Buyer balances its own consumption.', 'The Seller shall remain responsible for the balancing of the Facility and shall bear all imbalance costs.', 'Part I, Settlement and Delivery Point and Balancing; Part II s. 1.1 (Reference Price), 4.2, 5.2, 11.4-11.6', 'Part I states ''Delivery Point: not applicable''. If the reference price source changes, a Replacement Reference Price is negotiated or set by an independent expert (s. 11.5). There is no termination right or Strike Price adjustment for that event (s. 11.7).', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'Seller: a EUR 25,000,000 parent company guarantee from Lichtung Energie Holding GmbH, delivered within 10 Business Days of signing and in force until 12 months after the end of the Supply Period or earlier discharge. Buyer: none at signing. A EUR 20,000,000 letter of credit is due within 20 Business Days if its rating falls below BBB-, and is returned after six consecutive months at BBB- or better.', 'The Seller shall deliver a parent company guarantee from Lichtung Energie Holding GmbH in the amount of EUR 25,000,000 within ten (10) Business Days after the Signing Date, in the form set out in Annex 4 (the Parent Company Guarantee).', 'Part I, Credit Support; Part II s. 9.1-9.4; Annex 3; Annex 4', 'If the guarantor becomes insolvent, stops being an affiliate or disputes the guarantee, the Seller must replace it with a EUR 25,000,000 letter of credit from an A- bank (s. 9.2). Annex 4 caps the guarantor''s liability at EUR 25,000,000. Delivery of the guarantee is also a condition precedent (s. 2.1(c)). Credit support may be drawn on after five Business Days'' notice and must be restored within ten (s. 9.4). Annex 3 sets the letter of credit expiry at not earlier than 12 months after issue, auto-extended.', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 0, NULL, NULL, 'Part II s. 12.1, 13.1-13.5, 1.1 (Termination Amount), 1.2; Part I Annexes list; Annex 5', 'The termination amount cannot be determined because its calculation is referenced only to an annex that is not attached. Section 13.3 says: ''The Termination Amount shall be calculated in accordance with Annex 5 (Termination Amount Methodology).'' The annex heading reads: ''Annex 5 — Termination Amount Methodology [to be agreed prior to Financial Close]'', and the Annex 5 slot at the end of the document is empty. Even the direction of payment is left to Annex 5 (s. 13.3), and Annex 5 governs over the rest of the agreement (s. 1.2). Agreeing Annex 5 is a condition precedent (s. 2.1(d)). The events of default are stated in s. 12.1: non-payment (10 Business Days after notice), failure to maintain credit support (10 Business Days after notice), insolvency of the Party or its credit support provider, other material breach (30 days after notice), repudiation, Seller abandonment for 90 days, Seller failure to deliver Guarantees of Origin within 120 days after the Contract Year ends, and breach of the assignment or change-of-control rules. No Termination Amount is payable on termination under s. 2.2, 3.4, 10.5 or 11.2 (s. 13.5).', 'correct');
INSERT INTO extractions VALUES (4, 'lichtung-offshore-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:16:41+00:00', 1, 'A Change in Law other than one that makes the Product impossible is borne by the Party on whom the cost or benefit falls, with no adjustment to the Strike Price or Contract Quantity. If the Product ceases to exist, the Parties negotiate for 90 days and then either may terminate with no Termination Amount. Force Majeure lasting more than 180 consecutive days gives either Party a termination right, also with no Termination Amount.', 'Any other Change in Law, including one that changes the cost of Guarantees of Origin, grid charges or levies, is borne by the Party on whom the cost or benefit falls.', 'Part II s. 11.1-11.3, 10.5, 17.3', 'There is no cost threshold; the renegotiation right applies only when the Product no longer exists (s. 11.2). Changes in taxes on income are excluded from Change in Law (s. 11.1). Levies or revenue caps imposed on a Party stay with that Party (s. 17.3). The Force Majeure termination right is s. 10.5: ''If an event of Force Majeure continues for more than one hundred and eighty (180) consecutive days, either Party may terminate this Agreement by written notice with effect from a date not less than ten (10) Business Days after the notice.'' Force Majeure otherwise only reduces the Hourly Quantity pro rata for unavailable capacity (s. 10.4).', 'wrong_value');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Seller is Olivos Solar Proyecto Dos S.L. (Spain), a special purpose company owning the Facility. Buyer is Meseta Energía Comercializadora S.A. (Spain), a licensed electricity trader. Nobody guarantees the Buyer: there is no parent company guarantee and no shareholder support. The Buyer''s obligations are backed only by the letter of credit in section 9.2.', 'The Buyer is a licensed electricity trader and no guarantee of the Buyer''s obligations is provided by any affiliate of the Buyer.', 'Part I, Parties; Part II, sections 9.2 and 9.6; Annex 4 (not used)', 'No rating trigger on the Buyer is stated. The only rating requirement (A- or better) applies to the banks issuing the performance bond and the letter of credit (sections 9.1, 9.2, 9.5).', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Ground-mounted solar PV plant (bifacial modules on single-axis trackers) with 90 MWp DC installed capacity and 75 MW AC grid export capacity. It is at Valdeolivos, Province of Badajoz, Extremadura, Spain.', 'Facility: a ground-mounted solar photovoltaic plant with an installed capacity of 90 MWp (direct current) and a grid export capacity of 75 MW (alternating current) located at Valdeolivos in the Province of Badajoz, Spain, as further described in Annex 1.', 'Part I, Facility; Annex 1, A1.1 to A1.4', 'The document does not name the Facility''s bidding zone separately. It refers to the ''Spanish bidding zone'' for day-ahead prices and the forward price (sections 7.3, 7.4, 13.3).', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Twelve years, starting on the Commercial Operation Date.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; Part II, sections 1.1 and 3.4', 'The start is an event, not a fixed date. Section 3.4 sets the Commercial Operation Date when the Seller gives notice that the operating authorisation, TSO export confirmation, verified metering and a 72-hour test at 60 MW or more are in place.', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Target Commercial Operation Date is 30 June 2027 and the Longstop Date is 31 December 2027. Delay damages are EUR 6,000 per day, capped at EUR 1,500,000 in aggregate, and are the Buyer''s sole remedy for delay until the Longstop Date.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 30 June 2027, the Seller shall pay the Buyer liquidated damages of EUR 6,000 for each day of delay, up to an aggregate cap of EUR 1,500,000.', 'Part I, Target Commercial Operation Date; Part II, sections 3.5, 3.6, 3.7', 'Both dates are extended day for day for Force Majeure or a TSO delay, up to 180 days in total (section 3.6). After the Longstop Date, as extended, the Buyer may terminate and no Termination Amount is payable (section 3.7).', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Contract Price is EUR 38.75 per MWh, fixed for the whole Supply Period with no indexation or escalation. No indexation start date or share applies.', 'Contract Price: EUR 38.75 per MWh, fixed for the Supply Period without indexation.', 'Part I, Price; Part II, section 7.1', 'The price includes Guarantees of Origin and excludes VAT (7.1). No payment is due for hours with a negative day-ahead price (7.4). The only adjustment route is the new-tax mechanism in section 17.3.', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output, with no minimum or maximum annual quantity. Expected Annual Production is 165,000 MWh (P50), an estimate and not a delivery obligation. The Seller guarantees 97% Availability per Contract Year. The remedy for a shortfall is damages equal to the shortfall in percentage points x 1% of Expected Annual Production x Contract Price x 50%, capped at 5% of that year''s amount payable by the Buyer, and this is the sole remedy.', 'The Buyer purchases one hundred per cent (100%) of the Metered Output during the Supply Period.', 'Part I, Contract Quantity and volume structure; Part II, sections 4.1, 4.4, 5.6; Annex 1, A1.5 and A1.6', 'The P50 figure is not adjusted for module degradation (A1.5). The Availability definition (95% of irradiance-adjusted capacity in Daylight Hours) is in section 1.1 and A1.6.', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'The Buyer buys electricity delivered at the Delivery Point together with all Guarantees of Origin issued for that electricity. The Guarantees of Origin are transferred at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'Electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of that electricity.', 'Part I, Product; Part II, sections 7.1, 8.1, 8.2', 'Guarantees of Origin also arise for electricity delivered in negative-price hours, for which no payment is due (section 7.4). If a successor certificate replaces them, the Seller transfers it without a price adjustment (8.2).', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 0, NULL, NULL, NULL, 'Searched the whole document for curtailment, deemed delivery and any right to reduce or stop output. It does not say who may curtail the Facility, set any cap in hours or MWh, or treat curtailed energy as deemed delivered. Only related provisions: no payment is due in hours with a negative day-ahead price (section 7.4); no payment is due for electricity not delivered because of Force Majeure, which includes grid failure beyond the Delivery Point (sections 10.1, 10.4); the Buyer must accept all electricity generated and may not refuse delivery because the market price is below the Contract Price (section 4.5).', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Settlement is physical at the Delivery Point, the 220 kV connection point at the Valdeolivos substation, where title and risk pass to the Buyer. The Buyer is market representative and balance responsible party from the Commercial Operation Date and bears all imbalance costs.', 'The Buyer shall act as the market representative of the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; Part II, sections 4.3, 5.2, 5.3; Annex 1, A1.4', 'The Seller bears imbalance cost only where the imbalance results from its failure to notify an outage under sections 5.4 or 5.5 (section 5.3). Settlement is physical, so no financial reference price is stated.', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Seller: performance bond of EUR 1,200,000 from the Signing Date until the Commercial Operation Date. Buyer: standby letter of credit for three months of expected payments, EUR 1,598,437.50 at the Signing Date, from the Commercial Operation Date until the end of the Supply Period.', 'Seller: performance bond of EUR 1,200,000 from the Signing Date until the Commercial Operation Date (Annex 2). Buyer: letter of credit equal to three (3) months of expected payments under this Agreement (Annex 3), from the Commercial Operation Date until the end of the Supply Period.', 'Part I, Credit Support; Part II, sections 9.1 to 9.6; Annex 2; Annex 3', 'Part I and section 9.2 differ in timing, and Part I prevails on conflict. Section 9.2 requires the Buyer''s letter of credit at least 10 Business Days before the expected Commercial Operation Date and keeps it until 60 days after the Supply Period ends. The Seller''s bond is delivered within 10 Business Days after the Signing Date (9.1). Annex 2 expires at the latest on 30 June 2028 (A2.3). The letter of credit may run for one year and be renewed (9.3). The amount in the Annex 3 form is a blank placeholder; the figure comes from section 9.2. The Seller has no credit support after the Commercial Operation Date.', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'Events of Default are: non-payment within 10 Business Days after notice; failure to deliver, maintain or restore credit support within 10 Business Days after notice; an Insolvency Event; an unremedied material breach (30 days, or up to 90 days where a cure is not possible); a materially incorrect representation; for the Seller, a breach of exclusivity or Permits revoked and not reinstated within 90 days; for the Buyer, a trader licence or registration not reinstated within 30 days or revoked powers of representation. The Termination Amount is the present value, at the Interest Rate, of the difference between the Contract Price and the forward price for the Spanish bidding zone, based on at least two quotations and applied to Expected Annual Production for the rest of the Supply Period, determined by an independent expert.', 'The expert shall determine, under section 20.3, the present value at the Interest Rate of the difference between the Contract Price and the forward price for the Spanish bidding zone at the early termination date, evidenced by quotations from at least two (2) market participants, applied to the Expected Annual Production over the remainder of the Supply Period.', 'Part II, sections 12.1, 13.1 to 13.4, 1.1 (Interest Rate), 16.4, 20.3', 'The calculation is set out in the document and does not depend on a missing annex. The Interest Rate is the ECB main refinancing rate plus 4 percentage points. If the Termination Amount is negative, nothing is payable by either Party (13.2). The Defaulting Party bears the expert''s costs (13.3). No Termination Amount is payable on termination under sections 2.3, 3.7 or 10.5 (13.5). Lender cure and step-in rights can suspend termination for a Seller default for up to 120 days (16.4).', 'correct');
INSERT INTO extractions VALUES (4, 'olivos-solar-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:17:54+00:00', 1, 'A new tax, levy or charge on generation or sale from the Facility is borne by the Seller unless it exceeds 3% of the Seller''s revenue under the Agreement in the Contract Year. Above that threshold the Parties meet to agree an equitable adjustment, limited to the excess, with expert referral if no agreement within 90 days. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice if the event is still continuing, with no Termination Amount.', 'Should any law, regulation or administrative decision enacted after the Signing Date impose a new tax, levy or charge on the generation or sale of electricity from the Facility, the Seller shall bear such cost unless it exceeds three per cent (3%) of the Seller''s revenue under this Agreement in the relevant Contract Year, in which case the Parties shall meet to agree an equitable adjustment.', 'Part II, sections 17.3 to 17.5 (change in law); section 10.5 (force majeure termination)', 'The allocation sits under ''Taxes, Levies and Regulatory Costs'', not under a change-in-law heading. Its scope is limited to new taxes, levies and charges; the document has no general change-in-law clause for other legal changes. New charges on the Buyer''s purchase, trading or supply fall on the Buyer in full, and benefits of abolished or reduced generation charges stay with the Seller (17.4). No adjustment applies for corporate income tax or penalties from Seller non-compliance (17.5). Force Majeure notice is due within 5 Business Days (10.3).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'The Buyer is Jutland Board & Packaging A/S, which is unrated. Its credit is supported by a parent guarantee from Jutland Industri Holding A/S.', 'Buyer Jutland Board & Packaging A/S, unrated; parent guarantee from Jutland Industri Holding A/S', 'Section 4.2, key terms table, row 1', 'The Seller is not named by legal entity; only the project name (Havrebakke Wind Farm) appears. The guarantee amount and any rating trigger are not stated. The table is a summary of a legal due diligence report and the financial model, not the contract.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'Onshore wind farm of 8 turbines and 48.0 MW in Ringkøbing-Skjern, Denmark, in bidding zone DK1.', '8 turbines, 48.0 MW, Ringkøbing-Skjern, DK1', 'Section 4.2, key terms table, row 2; project line in the header', 'A single MW figure is given and AC/DC is not distinguished. No site address or parcel is given beyond the municipality.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'The supply period is 10 years, starting from COD (commercial operation date).', '10 years from COD', 'Section 4.2, key terms table, row 3', 'The modelling note says the base case runs the contract price for ten years and merchant DK1 forward prices after that.', 'faithful');
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'Target COD is 1 October 2027 and the longstop date is 31 March 2028. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1.75m.', 'Target COD 1 Oct 2027; longstop 31 Mar 2028; LDs EUR 9,600/day, cap EUR 1.75m', 'Section 4.2, key terms table, row 4', 'The consequence of reaching the longstop date (for example a termination right) is not stated.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'The contract price is EUR 54.50/MWh. 30 % of the price is CPI-indexed, with indexation starting in 2029.', 'EUR 54.50/MWh; 30 % CPI-indexed from 2029', 'Section 4.2, key terms table, row 5', 'The price is stated in the IC paper summary table ("key terms as modelled"), not in a contract clause. No contract price clause is cited.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'The Buyer takes 100 % of output on a pay-as-produced basis. Expected annual production (P50) is 158 GWh/yr, and a minimum of 118.5 GWh/yr is given.', 'Pay-as-produced, 100 % of output; P50 158 GWh/yr; minimum 118.5 GWh/yr', 'Section 4.2, key terms table, row 6', 'The remedy if production falls below the minimum is not stated. It is also not stated whether the minimum is a guarantee, a modelling floor or an availability measure.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'The product sold is electricity together with all guarantees of origin (GoOs), which go to the Buyer.', 'Electricity + all GoOs to buyer', 'Section 4.2, key terms table, row 7', 'The GoO amount and any GoO cost are not stated. Capacity or other attributes are not addressed.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'The Buyer may curtail for up to 150 hours per year, compensated at the contract price. Curtailment by the TSO is not compensated.', 'Buyer right 150 h/yr, compensated at contract price; TSO curtailment uncompensated', 'Section 4.2, key terms table, row 8', 'Treatment of negative prices is not addressed. The wording does not say "deemed delivered", only "compensated at contract price". There is no MWh cap, only the hours cap.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'Settlement is physical, with delivery at the 60 kV Havrebakke substation. The Buyer is balance responsible (BRP) and bears imbalance costs.', 'Physical, 60 kV Havrebakke substation; buyer is BRP and bears imbalance', 'Section 4.2, key terms table, row 9', '', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'The Seller provides a bank guarantee of EUR 2,500,000 running to COD plus 12 months. The Buyer provides a letter of credit (LC) equal to 9 months of payments.', 'Seller bank guarantee EUR 2,500,000 to COD + 12 months; buyer LC 9 months of payments', 'Section 4.2, key terms table, row 10', 'The Buyer LC is stated as a number of months of payments, not as an amount, and its duration is not stated.', 'faithful');
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'The termination amount is calculated as mark-to-market against the forward curve for the remaining term.', 'Mark-to-market vs forward curve for remaining term', 'Section 4.2, key terms table, row 11', 'Partial. The main events of default are not listed anywhere in the document. The termination calculation is given only at summary level, with no detail on the valuation method, the settlement direction or any cap. The underlying contract is not attached.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ic-key-terms', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:18:29+00:00', 1, 'Above EUR 250k per year the parties renegotiate, and if that fails either may terminate without a termination amount (a mutual termination right). A force majeure event lasting more than 180 days gives a termination right.', 'Renegotiation above EUR 250k/yr, then mutual termination right without termination amount; FM > 180 days termination right', 'Section 4.2, key terms table, row 12', 'The row does not say which party bears the cost of a change in law below the EUR 250k/yr threshold, or whether the threshold is measured on one party''s costs or on both. The row does not name the party that holds the force majeure termination right.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'Seller is Havrebakke Vind ApS. Buyer is Jutland Board & Packaging A/S, which is unrated. The Buyer''s payment obligations are guaranteed by its parent, Jutland Industri Holding A/S, through a parent company guarantee (Annex 4). No rating trigger is mentioned.', 'Payment obligations guaranteed by Jutland Industri Holding A/S.', 'Part I; Part II 9.2; Annex 4 (as cited in the summary''s Key terms table)', 'This document is counsel''s due diligence summary, not the PPA. Clause references are the summary''s own. The summary says the parent guarantee is the credit the committee relies on and recommends reviewing the guarantor''s last three years of accounts. The guarantee wording itself (Annex 4) is not reproduced.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'Eight onshore wind turbines with 48.0 MW capacity at Havrebakke, Ringkøbing-Skjern Municipality, in bidding zone DK1. The country is Denmark (the summary describes Danish law and Danish onshore wind).', 'Eight onshore turbines, 48.0 MW, Havrebakke, Ringkøbing-Skjern Municipality, DK1.', 'Part I; Annex 1', 'The summary gives a single 48.0 MW figure and does not say whether it is AC or DC.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'The Supply Period is ten years and starts on the Commercial Operation Date.', 'The Supply Period runs ten (10) years from the Commercial Operation Date.', 'Part I', '', 'faithful');
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'Target COD is 1 October 2027 and the Longstop Date is 31 March 2028. Delay damages are EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Target COD 1 October 2027. Longstop Date 31 March 2028. Delay damages EUR 9,600 per day after the Target COD, capped at EUR 1,750,000.', 'Part II 3', 'Failure to reach COD by the Longstop Date is also listed as an Event of Default (Part II 12–13).', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'The price is EUR 54.50 per MWh, stated in the Election Sheet. Thirty per cent of the price is adjusted annually by the Danish consumer price index, starting 1 January 2029.', 'EUR 54.50 per MWh per the Election Sheet. Thirty per cent of the price is adjusted annually from 1 January 2029 by the Danish consumer price index.', 'Part II 7.1; Annex 2 (price taken from the Election Sheet)', 'The summary lists Annex 2 as a reference for this term but does not say in terms that Annex 2 is the Election Sheet.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'Pay-as-produced: the Buyer takes 100 % of Metered Output. Expected Annual Production is 158,000 MWh (P50). Minimum Annual Production is 118,500 MWh, with a shortfall payment as the remedy.', '100 % of Metered Output. Expected Annual Production 158,000 MWh (P50). Minimum Annual Production 118,500 MWh with a shortfall payment.', 'Part I; Part II 4', 'How the shortfall payment is calculated is not stated in the summary. The pay-as-produced characterisation comes from Section 1 of the summary.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'The Seller sells electricity and all Guarantees of Origin, which are transferred at no additional cost. No capacity product is sold.', 'Electricity and all Guarantees of Origin, transferred at no additional cost.', 'Part II 8', 'No volume or price is given for the Guarantees of Origin, only that they pass at no additional cost.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'The Buyer may instruct reductions for up to 150 hours per Contract Year, paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer.', 'Buyer may instruct reductions for up to 150 hours per Contract Year, paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the transmission system operator are not compensated by the Buyer.', 'Part II 5.4–5.5', 'The cap is stated in hours only, with no MWh cap. The summary says the Seller has no equivalent curtailment right and that 150 hours is at the upper end of market practice. The summary does not mention treatment of negative prices.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'Physical delivery at the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears imbalance costs from COD. No financial reference price applies because settlement is physical.', 'Physical delivery at the metering point on the 60 kV side of the Havrebakke substation. Buyer appoints the balance responsible party and bears imbalance costs from COD.', 'Part I; Part II 4.2, 5.2', '', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'Seller: bank guarantee of EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: a parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Seller: bank guarantee EUR 2,000,000 from Financial Close until twelve months after COD. Buyer: parent company guarantee plus a letter of credit equal to nine months of expected payments.', 'Part II 9; Annex 4 (parent company guarantee)', 'The Buyer''s letter of credit is sized as nine months of expected payments, with no EUR amount given. The duration of the Buyer''s credit support is not stated.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'Events of Default include non-payment within ten Business Days of notice, insolvency, and failure to reach COD by the Longstop Date. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Non-payment within ten Business Days of notice, insolvency and failure to reach COD by the Longstop Date are Events of Default. Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period.', 'Part II 12–13', 'The calculation method is stated, but this document does not name the source of the Reference Forward Price. Counsel says the agreement names it and that it is a published DK1 forward curve (Section 3, point 4). The discount rate is not stated. The list of Events of Default may not be exhaustive.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-legal-dd-summary', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:19:12+00:00', 1, 'A cost impact from Change in Law above EUR 250,000 in a Contract Year triggers good-faith renegotiation. If there is no agreement within 90 days, the affected Party may terminate without a Termination Amount. Force majeure lasting more than 180 consecutive days gives either Party a termination right.', 'Change in Law is a defined term. A cost impact above EUR 250,000 in a Contract Year triggers good-faith renegotiation; absent agreement within 90 days the affected Party may terminate without a Termination Amount. Force majeure beyond 180 consecutive days gives either Party a termination right.', 'Part II 11 (change in law), Part II 10 (force majeure)', 'The summary does not say which Party bears the cost of a change in law beyond the renegotiation and termination mechanism. Counsel notes the termination right is mutual and that lenders are expected to ask for it to be tightened, with a lender consent letter likely required at Financial Close.', NULL);
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Seller is Havrebakke Vind ApS and Buyer is Jutland Board & Packaging A/S, both Danish companies. The Buyer''s payment obligations are guaranteed by Jutland Industri Holding A/S under a Parent Company Guarantee (Annex 4). The Buyer has no rating from a recognised rating agency.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; section 9.2; section 9.5; Annex 4', 'The document is an unsigned draft of 12 March 2026 and the guarantee is dated [date of signing]. The guarantee has no cap of its own: its liability is limited to the Buyer''s liability under the Agreement (Annex 4, para 5). The Guarantor''s own credit standing or rating is not stated. The only trigger is section 9.5: if the Guarantor stops holding the Buyer''s entire share capital, or the guarantee lapses, the Buyer must replace it or double the Letter of Credit within 20 Business Days.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Onshore wind farm with eight turbine generators and a total installed capacity of 48.0 MW, at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Annex 1 gives 6.0 MW per turbine, a 125 m hub height and a 162 m rotor diameter. Only one capacity figure is given and it is not labelled AC or DC.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Ten years, starting on the Commercial Operation Date.', 'Supply Period: ten (10) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; section 1.1 (Commercial Operation Date); section 3.3', 'The Commercial Operation Date is the date the Seller notifies the Buyer that the section 3.3 conditions are met: all eight turbines commissioned, grid connection and meters verified, and registrations done. It is not a fixed calendar date.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and the Longstop Date is 31 December 2027. Delay liquidated damages are EUR 9,600 per day, capped at EUR 1,750,000 in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Part I, Supply Period; section 3.4; section 3.5; section 3.6; Annex 1 (construction schedule)', 'Both dates are extended day for day for Force Majeure or Buyer breach, up to 180 days in aggregate (3.5). The liquidated damages are the Buyer''s sole remedy for delay apart from the right to terminate if the Longstop Date, as extended, is missed (3.4, 3.6).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'EUR 58.00 per MWh, exclusive of VAT, applied to each MWh of Metered Output from the Commercial Operation Date. Indexation: none, the price is fixed for the Supply Period.', 'Contract Price: EUR 58.00 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output from the Commercial Operation Date.', 'Annex 2 (Election Sheet); referenced from Part I, Price and section 7.1', 'The price is stated only in Annex 2, not in the body. There is no indexation start date or share because Annex 2 says indexation is none. Part I and section 7.1 say the price can be adjusted only as provided in Annex 2, but section 11.2 allows a Change in Law adjustment of the Contract Price by negotiation. The document does not reconcile the two.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected Annual Production is 158,000 MWh (P50) and Minimum Annual Production is 118,500 MWh (75% of P50). If Metered Output falls short in a Contract Year, the Seller pays the shortfall in MWh times any excess of the average DK1 day-ahead price over the Contract Price, capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the Metered Output is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; sections 4.1, 4.3, 4.5, 4.6; Annex 1; Annex 2', 'The minimum is reduced pro rata in the first and last Contract Year. It is also reduced by output lost to Force Majeure, grid-operator output reductions or Buyer breach, calculated under 5.5. The shortfall payment is zero when the DK1 day-ahead price is at or below EUR 58.00. There is no separate availability guarantee: the 97% availability in Annex 1 is an input to the P50 estimate. Section 4.3 says the P50 is used only for sections 9.2 and 13.3.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Electricity delivered at the Delivery Point plus all Guarantees of Origin issued for the Metered Output, transferred to the Buyer at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'Product: electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of the Metered Output.', 'Part I, Product and Certificates; sections 8.1–8.3', 'The Seller transfers the certificates monthly, within 15 Business Days of issue. It need not procure replacement certificates for any production shortfall (8.2). Certificates under a replacement scheme are also transferred at no additional cost (8.3).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Grid-operator (TSO) instructed output reductions give rise to no payment by the Buyer, so they are not paid as deemed delivery, and any TSO compensation belongs to the Seller. Such reductions only lower the Minimum Annual Production used in the shortfall test.', 'Reductions of output instructed by the transmission system operator shall not give rise to any payment by the Buyer.', 'Section 5.4; section 4.6; section 5.5', 'The lost quantity is calculated from met-mast wind, the turbine power curve, turbine availability and losses (5.5). The document gives the Buyer no right to curtail and states no cap in hours or MWh. It does not address negative prices. The Buyer must take 100% of Metered Output (4.1).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Physical settlement. The Delivery Point is the metering point on the 60 kV side of the Havrebakke substation, where title and risk pass to the Buyer. The Buyer appoints the balance responsible party and bears all imbalance costs from the Commercial Operation Date.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement; Part I, Delivery Point and Balancing; sections 4.2, 5.2; Annex 2', 'No reference price applies because settlement is physical, not financial. The Seller supplies day-ahead and intraday production forecasts without warranty (5.1).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Seller: a bank guarantee of EUR 2,000,000 delivered within 10 Business Days after Financial Close, in force until 12 months after the Commercial Operation Date. Buyer: the Parent Company Guarantee, plus a letter of credit for six months of expected payments (six twelfths of Expected Annual Production times the Contract Price), delivered at least 30 days before the expected Commercial Operation Date and in force until 60 days after the Supply Period ends.', 'The Buyer shall deliver a letter of credit in an amount equal to six (6) months of expected payments under this Agreement, calculated as six twelfths of the Expected Annual Production multiplied by the Contract Price in force at the time of calculation, no later than thirty (30) days before the expected Commercial Operation Date, to remain in force until sixty (60) days after the end of the Supply Period.', 'Part I, Credit Support; sections 9.1–9.5; Annex 2; Annex 3; Annex 4', 'The letter of credit amount is recalculated each 1 January. At EUR 58.00 and 158,000 MWh it is about EUR 4.58 million; this figure is computed here and not stated in the document. Both banks must be rated at least A-. A lost rating or missing renewal must be fixed within 20 Business Days, failing which the full amount can be drawn as cash security (9.4). The Parent Company Guarantee stays in force until all Buyer payments are made (Annex 4, para 6).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'Events of Default include non-payment (10 Business Days after notice), failure to deliver, restore or replace credit support (10 Business Days), insolvency, an uncured material breach (30 days) and assignment in breach. For the Seller they also include missing the Longstop Date or selling to a third party; for the Buyer, Guarantor insolvency or lapse of the guarantee. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remainder of the Supply Period for the Expected Annual Production, discounted at the Danish central bank rate plus 2 percentage points. The Non-Defaulting Party determines it, and it is payable only if it is a loss for that party.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Section 12.1; section 13.2–13.6; section 1.1 (Reference Forward Price); Annex 2 (production profile factor 0.88)', 'The calculation is fully specified in the attached document. The Reference Forward Price uses quotes from at least three market participants chosen by the Non-Defaulting Party, adjusted by the 0.88 factor in Annex 2. Section 12.1(f) makes missing the Longstop Date an Event of Default, but 3.6 and 13.6 say no Termination Amount is payable on a longstop termination. The document does not reconcile the two; 13.6 appears to govern. The Termination Amount is the exclusive remedy for loss of bargain (13.5).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v1-draft', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:20:30+00:00', 1, 'If a Change in Law raises a Party''s cost of performance by more than EUR 250,000 in a Contract Year, the Parties negotiate an adjustment in good faith, which may include the Contract Price. If none is agreed within 90 days, the affected Party may terminate on 60 days'' notice with no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice, also with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Section 11.1–11.3; section 10.4; section 17.2–17.3', 'No single party bears Change in Law cost. Below the threshold it stays with the party that bears the relevant tax or charge under 17.2: the Seller for generation and injection, the Buyer for offtake, transport, consumption and resale. 17.3 applies section 11 to new taxes above the threshold. Excluded from Change in Law: corporate income tax of general application and changes published in final form before signing. The 11.2 price adjustment sits uneasily with Annex 2, which fixes the price and excludes indexation; the document does not reconcile them.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'Seller is Havrebakke Vind ApS and Buyer is Jutland Board & Packaging A/S, which holds no credit rating from a recognised agency. The Buyer''s payment obligations are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee in Annex 4, and the Buyer also posts a letter of credit.', 'The Buyer''s payment obligations under this Agreement are guaranteed by Jutland Industri Holding A/S under the Parent Company Guarantee set out in Annex 4.', 'Part I, Parties; section 9.2; Annex 4', 'No rating trigger on the Buyer or the Guarantor was found. The A- rating requirement applies only to the banks issuing the bank guarantee and the letter of credit (9.1, 9.2). Section 9.5 requires a replacement guarantee or a doubled letter of credit if the Guarantor ceases to hold the entire share capital of the Buyer or the guarantee ceases to be in force. Annex 4 clause 5 caps the Guarantor''s liability at the Buyer''s liability under the Agreement.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'Havrebakke Wind Farm: eight onshore wind turbine generators of 6.0 MW each, 48.0 MW total installed capacity. Located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1.', 'The Facility is the Havrebakke Wind Farm, consisting of eight onshore wind turbine generators with a total installed capacity of 48.0 MW located at Havrebakke in Ringkøbing-Skjern Municipality, Denmark, in bidding zone DK1, together with the internal cabling, the Havrebakke substation and the ancillary installations described in Annex 1.', 'Part I, Facility; Annex 1', 'Capacity is given as a single figure; no separate AC and DC capacities are stated.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'The Supply Period is twelve (12) years, starting on the Commercial Operation Date (targeted for 1 October 2027).', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I, Supply Period; sections 1.1 and 3.3', 'The start is the date the Seller notifies the Buyer that the section 3.3 conditions are met (all eight turbines commissioned, grid connection and verified meters, registrations with the Transmission System Operator and the Guarantee of Origin body). The end date therefore moves with the actual Commercial Operation Date.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'Target Commercial Operation Date is 1 October 2027 and the Longstop Date is 31 March 2028. Delay liquidated damages are EUR 9,600 per day of delay, capped at EUR 1,750,000 in aggregate; both dates extend day for day for Force Majeure or Buyer breach, up to 180 days in aggregate.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 1 October 2027, the Seller shall pay the Buyer liquidated damages of EUR 9,600 for each day of delay, up to an aggregate cap of EUR 1,750,000.', 'Section 3.4; Part I, Supply Period; sections 3.5 and 3.6', 'Liquidated damages are the Buyer''s sole remedy for delay except the right to terminate after the Longstop Date under 3.6, where the Seller pays accrued liquidated damages and no Termination Amount is payable. Section 12.1(f) separately lists failure to reach COD by the Longstop Date as a Seller Event of Default, and 13.3 contemplates termination before COD with a Termination Amount. The document does not say which route prevails.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'Contract Price is EUR 54.50 per MWh excluding VAT, stated in Annex 2, and applies to Metered Output and Deemed Delivered Electricity from COD. 30% of the price is adjusted each 1 January from 2029 by the change in the Danish consumer price index over the preceding calendar year; the other 70% is fixed for the Supply Period.', 'Contract Price: EUR 54.50 per MWh, exclusive of value added tax, applicable to each MWh of Metered Output and of Deemed Delivered Electricity from the Commercial Operation Date.', 'Annex 2 (Election Sheet), Contract Price and Indexation; referenced in Part I, Price and section 7.1', 'The body of the Agreement does not state the price; it points to Annex 2, which prevails. The indexation sentence is in the same annex: "Thirty per cent (30%) of the Contract Price shall be adjusted on 1 January of each Contract Year from 2029 by the percentage change in the Danish consumer price index over the preceding calendar year."', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output. Expected Annual Production is 158,000 MWh (P50) and Minimum Annual Production is 118,500 MWh (75% of P50); a shortfall is paid as shortfall MWh times the positive excess of the average DK1 day-ahead price over the Contract Price, capped at EUR 500,000 per Contract Year.', 'If in any Contract Year the sum of the Metered Output and the Deemed Delivered Electricity is less than the Minimum Annual Production, the Seller shall pay the Buyer a shortfall payment equal to the shortfall in MWh multiplied by the amount, if positive, by which the average day-ahead price for bidding zone DK1 for that Contract Year exceeds the Contract Price, capped at EUR 500,000 per Contract Year.', 'Part I, Contract Quantity and Volume Structure; sections 4.1, 4.3, 4.5, 4.6; Annex 1; Annex 2', 'Minimum Annual Production is reduced pro rata in the first and last Contract Year and reduced for Force Majeure, Transmission System Operator-instructed reductions and Buyer breach (4.5, 4.6). Section 4.3 says the Seller guarantees no quantity in any hour, day or month. No separate availability guarantee was found; the 97 per cent availability in Annex 1 is an assumption behind the P50 estimate.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'The Seller sells electricity delivered at the Delivery Point together with all Guarantees of Origin issued for the Metered Output; the certificates are transferred at no additional cost. No capacity product, ancillary service or other attribute is sold.', 'Product: electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of the Metered Output.', 'Part I, Product and Certificates; section 8', 'Guarantees of Origin are transferred monthly within 15 Business Days of issue (8.1). None are issued for Deemed Delivered Electricity, the Seller need not procure replacements for any shortfall (8.2), and certificates under a replacement scheme pass to the Buyer at no additional cost (8.3). The certificate cost is not priced separately from the Contract Price.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'The Buyer may instruct output reductions for up to 150 hours per Contract Year on at least two hours'' notice, and the energy not generated is paid as Deemed Delivered Electricity at the Contract Price. Reductions instructed by the Transmission System Operator give rise to no Buyer payment, and any compensation from the Transmission System Operator belongs to the Seller.', 'The Buyer may instruct the Seller to reduce the output of the Facility for up to one hundred and fifty (150) hours per Contract Year, and the electricity that would otherwise have been generated during such hours shall be treated as Deemed Delivered Electricity and paid at the Contract Price.', 'Sections 5.4, 5.5, 5.6; Annex 2 (Buyer reduction of output); section 4.6', 'The Seller may refuse Buyer instructions beyond the 150-hour limit. No cap in hours or MWh was found for Transmission System Operator reductions, which only reduce the Minimum Annual Production for shortfall purposes (4.6). The document contains no provision on negative prices.', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'Settlement is physical, with title and risk passing at the Delivery Point, the metering point on the 60 kV side of the Havrebakke substation. The Buyer appoints the balance responsible party and bears all imbalance costs from COD.', 'The Buyer shall appoint the balance responsible party for the Facility and shall bear all imbalance costs from the Commercial Operation Date.', 'Part I, Settlement and Delivery Point and Balancing; sections 4.2, 5.1, 5.2; Annex 2', 'No financial reference price applies because settlement is physical. The Seller provides day-ahead and intraday production forecasts to the balance responsible party, given without warranty (5.1).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'Seller: a bank guarantee of EUR 2,000,000 delivered within 10 Business Days after Financial Close and kept in force until 12 months after COD. Buyer: the Parent Company Guarantee plus a letter of credit equal to nine months of expected payments, delivered at least 30 days before expected COD and kept in force until 60 days after the end of the Supply Period.', 'The Buyer shall deliver a letter of credit in an amount equal to nine (9) months of expected payments under this Agreement, calculated as nine twelfths of the Expected Annual Production multiplied by the Contract Price in force at the time of calculation, no later than thirty (30) days before the expected Commercial Operation Date, to remain in force until sixty (60) days after the end of the Supply Period.', 'Part I, Credit Support; sections 9.1 to 9.5; Annex 2; Annex 3; Annex 4', 'Both bank instruments must come from a bank rated at least A-. The Buyer''s letter of credit amount is recalculated each 1 January for the Contract Price then in force; at the initial price it would be about EUR 6.46 million (118,500 MWh x EUR 54.50, my calculation, not stated in the document). The Buyer may draw the Seller''s guarantee only for unpaid amounts under 3.4, 3.6 or 4.5 (9.1). A downgraded or unextended instrument must be replaced within 20 Business Days or the other party may draw it as cash (9.4).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'Events of Default include non-payment uncured 10 Business Days after notice, failure to deliver or restore credit support, insolvency, uncured material breach (30 days), assignment in breach, Seller failure to reach COD by the Longstop Date or sale to a third party, and Buyer Guarantor insolvency or loss of the Parent Company Guarantee. The Termination Amount is the present value of the difference between the Contract Price and the Reference Forward Price over the remaining Supply Period on Expected Annual Production, discounted at the Danish central bank reference rate plus 2 percentage points and set by the Non-Defaulting Party.', 'The Termination Amount shall be the present value of the difference between the Contract Price and the Reference Forward Price for the Expected Annual Production over the remainder of the Supply Period, discounted at the reference rate of the Danish central bank plus two (2) percentage points, and determined by the Non-Defaulting Party as at the early termination date, acting in good faith and in a commercially reasonable manner.', 'Sections 12.1, 13.2 to 13.6; definition of Reference Forward Price in section 1.1; Annex 2 (production profile factor)', 'The calculation is fully defined in the attached document. Reference Forward Price is the average of DK1 baseload forward quotes from at least three market participants chosen by the Non-Defaulting Party, adjusted for production profile by the factor 0.88 in Annex 2. The amount is payable only if it is a loss to the Non-Defaulting Party; if it is a gain, nothing is payable (13.4). It is the exclusive remedy for loss of the bargain (13.5), and no Termination Amount applies on termination under 2.3, 3.6, 10.4 or 11.3 (13.6).', 'correct');
INSERT INTO extractions VALUES (5, 'havrebakke-ppa-v2-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:22:08+00:00', 1, 'If a Change in Law raises a Party''s cost by more than EUR 250,000 in any Contract Year, the Parties negotiate in good faith an adjustment, which may include the Contract Price; failing agreement within 90 days of notice, the affected Party may terminate on 60 days'' notice with no Termination Amount. Force Majeure lasting more than 180 consecutive days lets either Party terminate on 30 days'' notice, also with no Termination Amount.', 'If a Change in Law increases the cost to a Party of performing this Agreement by more than EUR 250,000 in any Contract Year, the Parties shall negotiate in good faith an adjustment to restore the economic balance of this Agreement, which may include an adjustment to the Contract Price.', 'Sections 11.1 to 11.3; 17.2 and 17.3; 10.4', 'The threshold works in either direction, since it refers to the cost to "a Party"; no adjustment right is stated below it. Change in Law excludes general corporate income tax changes and changes published in final form before the Signing Date (11.1). Under section 17 the Seller bears taxes on generation and injection and the Buyer bears those on offtake, transport, consumption or resale; new taxes follow that split and fall under section 11 only if they meet the EUR 250,000 threshold (17.3).', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'Seller: Lichtung Offshore Wind GmbH & Co. KG (Emden, Germany), a single-purpose project company. Buyer: Rheintal Spezialchemie AG (Worms, Germany), rated BBB+ at signing. The Buyer has no guarantor; its credit protection is a rating trigger (rating below BBB-) that requires a EUR 20,000,000 letter of credit within 20 Business Days.', 'On the Signing Date the Buyer holds a long-term credit rating of BBB+ from a recognised rating agency.', 'Part I, Parties; Part II section 9.3', 'No Buyer guarantor appears in Part I, section 9, section 16 or the Annexes. The only guarantor named, Lichtung Energie Holding GmbH, supports the Seller, not the Buyer.', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'Offshore wind farm of 300 MW installed capacity (20 turbines of 15 MW each on monopile foundations), about 60 km north-west of Borkum in the German North Sea, Germany. The Reference Price is the DE-LU bidding zone price.', 'The Facility is an offshore wind farm with an installed capacity of 300 MW located in the German North Sea approximately 60 km north-west of Borkum, consisting of twenty (20) wind turbine generators of 15 MW each on monopile foundations, one offshore substation and the inter-array cables, connected to the onshore transmission grid through the offshore grid connection system of the transmission system operator.', 'Part I, Facility; Annex 1; section 1.1 (Installed Capacity, Reference Price)', 'Only one capacity figure (300 MW) is given; no separate AC and DC figures. The Facility''s own bidding zone is not stated in terms. DE-LU is stated for the Buyer''s production sites (Part I, Parties) and for the Reference Price (section 1.1); section 11.4(b) refers to the area in which the Facility and the Buyer''s sites are located.', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'Fifteen years from the Start Date of 1 January 2029, ending 31 December 2043. The period is not extended by any delay in commissioning.', 'Supply Period: fifteen (15) years commencing on the Start Date of 1 January 2029.', 'Part I, Supply Period; section 1.1 (Start Date, Contract Year)', 'Settlement of hours starts at the later of the Start Date and the day after the Commissioning Date (section 4.1). Sections 4, 7 and 8 take effect only when the Conditions Precedent in section 2.1 are met, including Financial Close and the agreed Annex 5.', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'Target commissioning is on or before the Start Date, 1 January 2029; the Longstop Commissioning Date is 1 July 2029. Delay compensation is EUR 40,000 per day from the Start Date, capped at EUR 6,000,000 in aggregate.', 'If the Facility has not been commissioned by the Start Date, the Seller shall pay the Buyer delay compensation of EUR 40,000 for each day from the Start Date until the Facility is commissioned, up to an aggregate cap of EUR 6,000,000 (Delay Compensation).', 'Section 3.1(d), 3.3 and 3.4; section 1.1 (Longstop Commissioning Date)', 'After the longstop the Buyer may terminate without any Termination Amount. The cap equals 150 days of delay and is reached around 30 May 2029, before the longstop. Accrual is suspended during Force Majeure, but the longstop is not extended. Commissioning requires 240 MW (80%) of capacity to have passed take-over tests (section 3.2). Delay compensation is the Buyer''s sole financial remedy for late commissioning.', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'Strike Price of EUR 72.00 per MWh for 2029, increased by 2% on 1 January of each Contract Year from the second (2030), compounded and rounded to two decimals (EUR 73.44 in 2030, EUR 74.91 in 2031). The price is a strike settled against the hourly DE-LU day-ahead Reference Price, not a price paid per MWh delivered.', 'The Strike Price for the first Contract Year (2029) is EUR 72.00 per MWh.', 'Part I, Price; section 7.1; settlement in section 4.2', 'The escalator is a fixed 2% per year, not tied to an inflation index. The Strike Price includes the consideration for the Guarantees of Origin (section 7.1). The price is stated in Part I and section 7.1, not in an annex.', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'Fixed baseload volume of 1,000,000 MWh per Contract Year (114.155 MWh per hour in an 8,760-hour year), independent of actual output. The Seller''s P50 estimate is about 1,280,000 MWh a year, and the Seller gives no availability or production guarantee.', 'The Contract Quantity does not vary with the actual output of the Facility.', 'Part I, Contract Quantity; section 5.5; Annex 1 item 5', 'This is not pay-as-produced. The Contract Quantity is about 78% of P50, and the P50 is not a warranty (Annex 1). Outages do not reduce the Contract Quantity (section 5.3). It is reduced for the first Contract Year if commissioning is after the Start Date (section 4.5) and proportionally for Force Majeure capacity loss (section 10.4). The only shortfall remedy is for Guarantees of Origin (sections 8.2 and 8.3).', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'The product is financial settlement of the Contract Quantity against the Reference Price plus Guarantees of Origin equal to the Contract Quantity each year. No electricity is sold or delivered.', 'Product: (a) the financial settlement of the Contract Quantity against the Reference Price under section 4, and (b) the transfer to the Buyer of Guarantees of Origin in a quantity equal to the Contract Quantity under section 8.', 'Part I, Product and Certificates; section 8; section 7.1', 'There is no separate certificate price; it is included in the Strike Price. Certificates carry the attribute offshore wind and are transferred quarterly. If generation falls short, the Seller procures replacement certificates from other German offshore wind facilities at its own cost (section 8.2). The Seller bears issuing fees and the Buyer bears cancellation fees (section 8.4). No capacity or other attributes are sold.', 'wrong_value');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'The Seller''s obligations for the Contract Quantity are not reduced by curtailment instructed by the transmission system operator unless it is Force Majeure, so the Contract Quantity stays settled whether or not the Facility generates. Hours with a negative Reference Price are Negative Price Hours with no settlement amount payable.', 'The Seller''s obligations in respect of the Contract Quantity shall not be reduced by any curtailment of the Facility''s output instructed by the transmission system operator, save where such curtailment constitutes Force Majeure.', 'Section 5.4; section 4.1 and 4.4; section 10.1 and 10.2', 'Only the transmission system operator is described as curtailing; the Buyer has no curtailment right. No cap in hours or MWh is stated. There is no deemed-delivery clause, but the same result follows from the fixed financial volume. Curtailment for congestion management, redispatch, system security or market reasons is not Force Majeure, and compensation from the transmission system operator belongs to the Seller. Negative Price Hours do not reduce the Guarantees of Origin due (section 4.4).', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'Financial settlement with no Delivery Point (stated as not applicable), settled hourly against the DE-LU day-ahead Reference Price. The Seller is balance responsible for the Facility and bears all imbalance costs; the Buyer balances its own consumption.', 'The Seller shall remain responsible for the balancing of the Facility and shall bear all imbalance costs.', 'Part I, Settlement and Delivery Point and Balancing; section 5.2; section 1.1 (Reference Price)', 'Hourly Reference Prices are averaged if the market publishes shorter time units. The Seller sells the physical output on the market for its own account (section 4.6). A change of Reference Price source is handled in sections 11.4 to 11.7.', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'Seller: parent company guarantee of EUR 25,000,000 from Lichtung Energie Holding GmbH, delivered within 10 Business Days of signing and in force until 12 months after the Supply Period ends. Buyer: none at signing; a EUR 20,000,000 letter of credit if its rating falls below BBB-, returnable after six consecutive months at BBB- or better.', 'The Seller shall deliver a parent company guarantee from Lichtung Energie Holding GmbH in the amount of EUR 25,000,000 within ten (10) Business Days after the Signing Date, in the form set out in Annex 4 (the Parent Company Guarantee).', 'Part I, Credit Support; section 9.1 to 9.4; Annexes 3 and 4', 'The Seller must replace the guarantee with a EUR 25,000,000 letter of credit from a bank rated at least A- if the guarantor becomes insolvent, ceases to be an affiliate or disputes the guarantee (section 9.2). The Buyer''s trigger is below BBB-, and a withdrawn rating also triggers it (section 9.3). Delivery of the guarantee is a condition precedent (section 2.1(c)). Credit support is returned within 20 Business Days after the later of the end of the Supply Period and payment of all amounts due (section 9.4).', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 0, NULL, NULL, 'Section 12 (Events of Default); section 13.3; Annex 5', 'The Termination Amount is defined only by reference to Annex 5, which is not attached. The Annex 5 heading reads: Annex 5 — Termination Amount Methodology [to be agreed prior to Financial Close]. Section 13.3 states: The Termination Amount shall be calculated in accordance with Annex 5 (Termination Amount Methodology). Annex 5 is also a condition precedent (section 2.1(d)), yet sections 12 and 13 take effect from signing (section 2.3), so the amount cannot be calculated on the current document. The events of default are stated: non-payment (10 Business Days after notice), failure to maintain credit support (10 Business Days), insolvency (application not dismissed within 30 days), other material breach (30-day cure), repudiation, Seller abandonment for 90 days, Guarantees of Origin not transferred within 120 days of year end, and breach of assignment or change-of-control rules. No Termination Amount is payable on termination under sections 2.2, 3.4, 10.5 or 11.2 (section 13.5).', 'correct');
INSERT INTO extractions VALUES (5, 'lichtung-offshore-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:23:30+00:00', 1, 'A Change in Law is borne by the Party on whom the cost or benefit falls, with no adjustment of the Strike Price or Contract Quantity and no cost threshold. If the Product can no longer exist, either Party may terminate after 90 days of good-faith renegotiation, with no Termination Amount. Force Majeure lasting more than 180 consecutive days gives either Party a termination right, also with no Termination Amount.', 'Any other Change in Law, including one that changes the cost of Guarantees of Origin, grid charges or levies, is borne by the Party on whom the cost or benefit falls.', 'Section 11.1 to 11.3; section 10.5; section 17.3', 'Levies or revenue caps imposed on a Party are borne by that Party (section 17.3). A change in the Reference Price source gives no termination right or price adjustment (section 11.7). It is handled by a replacement price agreed within 60 days or set by an independent expert (sections 11.4 to 11.6).', 'wrong_value');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '1_parties_and_buyer_credit', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Seller is Olivos Solar Proyecto Dos S.L. (Spain), a special purpose company owning the Facility. Buyer is Meseta Energía Comercializadora S.A. (Spain), a licensed electricity trader. No guarantor, parent company guarantee or rating trigger exists for the Buyer. Its obligations are supported solely by a bank letter of credit.', 'The Buyer is a licensed electricity trader and no guarantee of the Buyer''s obligations is provided by any affiliate of the Buyer.', 'Part I (Parties); Part II sections 9.2 and 9.6; Annex 4 (not used)', 'Section 9.6 confirms the Buyer contracts as a stand-alone trader and its shareholders have given no undertaking. The only Buyer credit protection is the letter of credit (see term 10). The bank issuing it must be rated at least A- (9.2), and a downgrade requires replacement within 20 Business Days (9.5).', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '2_facility', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Ground-mounted solar PV plant (bifacial modules on single-axis trackers) with 90 MWp DC installed capacity and 75 MW AC grid export capacity. Located at Valdeolivos, Province of Badajoz (Extremadura), Spain. Prices and the Termination Amount refer to the Spanish bidding zone.', 'Facility: a ground-mounted solar photovoltaic plant with an installed capacity of 90 MWp (direct current) and a grid export capacity of 75 MW (alternating current) located at Valdeolivos in the Province of Badajoz, Spain, as further described in Annex 1.', 'Part I (Facility); Annex 1, A1.1 to A1.4', 'The bidding zone is not named in the Facility description. It appears as ''the Spanish bidding zone'' in sections 7.3, 7.4 and 13.3.', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '3_supply_period', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Twelve (12) years, starting on the Commercial Operation Date. That date occurs when the Seller gives notice that the conditions in section 3.4 are met, including 60 MW AC exporting for 72 continuous hours.', 'Supply Period: twelve (12) years commencing on the Commercial Operation Date.', 'Part I (Supply Period); Part II sections 1.1 and 3.4', 'No calendar end date is stated, so the end depends on when the Commercial Operation Date actually occurs. The Contract Year runs from that date.', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '4_cod_and_delay', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Target Commercial Operation Date is 30 June 2027 and Longstop Date is 31 December 2027. Delay liquidated damages are EUR 6,000 per day after the target date, capped at EUR 1,500,000 in aggregate. They are the Buyer''s sole remedy for delay until the Longstop Date. If COD has not occurred by the Longstop Date, as extended, the Buyer may terminate and no Termination Amount is payable.', 'If the Commercial Operation Date has not occurred by the Target Commercial Operation Date of 30 June 2027, the Seller shall pay the Buyer liquidated damages of EUR 6,000 for each day of delay, up to an aggregate cap of EUR 1,500,000.', 'Part I (Target Commercial Operation Date); Part II sections 3.5, 3.6, 3.7 and 1.1', 'Both dates are extended day for day for Force Majeure or a transmission system operator delay, up to 180 days in aggregate (3.6). The Seller must notify the Buyer within 5 Business Days of the event. The Seller''s performance bond of EUR 1,200,000 can be drawn for unpaid delay damages (9.1).', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '5_price_and_indexation', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Contract Price is EUR 38.75 per MWh, fixed for the whole Supply Period with no indexation or escalation. It includes Guarantees of Origin and excludes VAT. The price does not apply in hours when the day-ahead price is negative.', 'Contract Price: EUR 38.75 per MWh, fixed for the Supply Period without indexation.', 'Part I (Price); Part II sections 7.1 and 7.4', 'Section 7.1 allows adjustment only under sections 7.4 (negative prices) and 17.3 (new taxes above a threshold). Under 7.4, no payment is due for electricity delivered in negative-price hours.', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '6_volume_and_performance', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Pay-as-produced: the Buyer takes 100% of Metered Output, with no minimum or maximum annual quantity. Expected Annual Production is 165,000 MWh (P50), an estimate and not a delivery obligation. The Seller guarantees 97% Availability per Contract Year. If it falls short, availability damages equal shortfall in percentage points x 1% of Expected Annual Production x Contract Price x 50%. They are capped at 5% of the annual amount payable by the Buyer and are the Buyer''s sole remedy.', 'Pay-as-produced. The Buyer purchases one hundred per cent (100%) of the Metered Output during the Supply Period.', 'Part I (Contract Quantity and volume structure); Part II sections 4.1, 4.4, 5.6 and 1.1 (Availability); Annex 1, A1.5 and A1.6', 'Availability counts a Daylight Hour as available only if the Facility could export at least 95% of its irradiance-adjusted capacity. Planned maintenance counts as unavailability (5.4). Force Majeure hours and grid-connection unavailability not caused by the Seller are excluded. The P50 figure is not adjusted for module degradation (A1.5).', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '7_product_and_certificates', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'The Buyer buys electricity delivered at the Delivery Point together with all Guarantees of Origin issued for it. The Guarantees of Origin are transferred at no additional cost and are included in the Contract Price. No capacity product, ancillary service or other attribute is sold.', 'Electricity generated by the Facility and delivered at the Delivery Point, together with all Guarantees of Origin issued in respect of that electricity.', 'Part I (Product); Part II sections 7.1, 8.1, 8.2 and 8.3', 'The Seller must transfer Guarantees of Origin to the Buyer''s register account within 30 days of issue (8.1). If they are replaced by another scheme, the Seller transfers the successor certificate without a price adjustment (8.2).', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '8_curtailment', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 0, NULL, NULL, NULL, 'The document has no curtailment clause. I read the whole document (Part I, sections 1 to 21, Annexes 1 to 4) and found nothing on who may curtail the Facility, a cap in hours or MWh, or deemed-delivery payment for curtailed energy. Related provisions: (a) Section 7.4 sets no payment for any hour with a negative day-ahead price, while the output is still delivered and generates Guarantees of Origin. (b) Section 4.5 requires the Buyer to accept all electricity generated. (c) Grid failure beyond the Delivery Point is Force Majeure (10.1), and no payment is due for electricity not delivered because of Force Majeure (10.4). (d) Availability excludes grid-connection unavailability not caused by the Seller (1.1). Whether grid-operator curtailment is paid is therefore not stated.', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '9_delivery_point_and_balancing', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Physical settlement at the Delivery Point, the 220 kV connection point at the Valdeolivos substation. No financial reference price applies. From COD the Buyer is market representative and balance responsible party, and bears all imbalance costs. The Seller is liable for imbalance only where it results from failing to notify an outage under sections 5.4 or 5.5.', 'The Buyer is the market representative of the Facility and the balance responsible party for the Metered Output from the Commercial Operation Date (section 5.2 of Part II).', 'Part I (Settlement; Delivery Point and Balancing); Part II sections 4.2, 4.3, 5.2 and 5.3; Annex 1, A1.4', 'Section 3.3 also has the Buyer act as market representative for test electricity delivered before COD. Title and risk pass at the Delivery Point (4.3).', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '10_credit_support', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Seller: performance bond of EUR 1,200,000, delivered within 10 Business Days after the Signing Date and held until COD, from a bank rated at least A-, payable on first demand (Annex 2). Buyer: standby letter of credit equal to three months of expected payments, stated as EUR 1,598,437.50 on the Signing Date, payable on first demand (Annex 3). It is delivered at least 10 Business Days before the expected COD and maintained until 60 days after the end of the Supply Period. No parent company guarantee is given by either Party.', 'Seller: performance bond of EUR 1,200,000 from the Signing Date until the Commercial Operation Date (Annex 2). Buyer: letter of credit equal to three (3) months of expected payments under this Agreement (Annex 3), from the Commercial Operation Date until the end of the Supply Period.', 'Part I (Credit Support); Part II sections 9.1 to 9.6; Annexes 2 and 3', 'Part I says the Buyer''s letter of credit runs from COD to the end of the Supply Period. Section 9.2 adds that it is delivered 10 Business Days before expected COD and kept until 60 days after the Supply Period ends. Part I prevails where they conflict. The letter of credit may have a one-year term with a replacement due 30 days before expiry, failing which the Seller may draw it in full (9.3). The Buyer must restore it within 10 Business Days after each drawing (9.4). The form in Annex 3 leaves the amount and expiry date blank; the EUR figure comes from section 9.2.', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '11_default_and_termination', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Events of Default include non-payment (10 Business Days after notice), failure to deliver or restore credit support, an Insolvency Event, uncured material breach (30 days, or up to 90), and a materially incorrect representation. Seller-only events are third-party sales and Permit revocation not reinstated within 90 days. Buyer-only events are loss of trader licence or market registration not reinstated within 30 days, and revocation of the Seller''s powers of representation. The Termination Amount is the present value, at the Interest Rate, of the difference between the Contract Price and the forward price for the Spanish bidding zone at the termination date. It is evidenced by at least two market quotations, determined by an independent expert, and applied to Expected Annual Production over the remaining Supply Period. The Defaulting Party pays it and bears the expert''s costs.', 'The expert shall determine, under section 20.3, the present value at the Interest Rate of the difference between the Contract Price and the forward price for the Spanish bidding zone at the early termination date, evidenced by quotations from at least two (2) market participants, applied to the Expected Annual Production over the remainder of the Supply Period.', 'Part II sections 12.1 (a) to (g), 13.1 to 13.5 and 16.4', 'The calculation is in the body and is not defined by reference to an unattached document, so it is found. The sign convention is not stated per party. If the Termination Amount is negative, nothing is payable by either Party (13.2). It is payable within 20 Business Days of the determination and can be drawn from the Defaulting Party''s credit support (13.4). No Termination Amount is payable on termination under sections 2.3, 3.7 or 10.5 (13.5). Where the Seller defaults, a Lender may cure or suspend the early termination date for up to 120 days (16.4).', 'correct');
INSERT INTO extractions VALUES (5, 'olivos-solar-ppa-execution', '12_change_in_law_and_force_majeure', 'claude-sonnet-5-5', '2026-10-29T10:24:39+00:00', 1, 'Change in law is addressed only as new taxes, levies and charges, under section 17 (Taxes, Levies and Regulatory Costs). A new charge on generation or sale from the Facility is borne by the Seller unless it exceeds 3% of the Seller''s revenue under the Agreement in the relevant Contract Year. Above that, the Parties meet to agree an equitable adjustment limited to the portion above 3%. If nothing is agreed within 90 days, either Party may refer the matter to the expert procedure. Reductions in generation-side charges benefit the Seller, and new charges on the Buyer''s purchase, trading or supply are borne by the Buyer. If Force Majeure continues for more than 180 consecutive days, either Party may terminate on 30 days'' notice if the event is still continuing, with no Termination Amount.', 'Should any law, regulation or administrative decision enacted after the Signing Date impose a new tax, levy or charge on the generation or sale of electricity from the Facility, the Seller shall bear such cost unless it exceeds three per cent (3%) of the Seller''s revenue under this Agreement in the relevant Contract Year, in which case the Parties shall meet to agree an equitable adjustment.', 'Part II sections 17.3, 17.4 and 17.5 (change in law); section 10.5 (Force Majeure termination)', 'There is no general change-in-law clause beyond taxes, levies and charges. No adjustment is available for corporate income tax or for penalties arising from the Seller''s non-compliance (17.5). The Seller must notify the Buyer of a new charge within 30 days of enactment, and the Parties meet within 30 days of that notice (17.3). Force Majeure notice is due within 5 Business Days (10.3).', 'correct');
